-- Full Learn/Watch/Practice/Apply coverage for every existing Academy
-- Classes topic, plus the 4 previously "coming soon" subjects (Technology &
-- Engineering, Foreign Language, Health & Fitness, Business & Finance) built
-- out and launched.
--
-- Three things ship in this file:
--
--   1. Every remaining existing class_topic row (the demonstration set of 6
--      was already enriched in 20260906120000_classroom_lesson_builder.sql)
--      gets `learn` (2 concept cards), `practice` (2 quiz questions), and
--      `apply` (a hands-on mini-project + checklist) merged into its meta —
--      146 topics across Math, Language Arts, Science, Social Sciences,
--      Art & Music, and Home Economics & Workshop. `help.videos` (the
--      existing curated links) is untouched — that's the "Watch" pillar,
--      already in place.
--
--   2. 16 new class_topic rows (4 grade bands x 4 subjects) for Technology &
--      Engineering, Foreign Language, Health & Fitness, and Business &
--      Finance — full Learn/Watch/Practice/Apply content plus real,
--      verified YouTube links, one topic per grade band per subject.
--
--   3. Flips `comingSoon` to false on those same 4 class_subject rows, so
--      they stop showing the "SOON" badge on the main Classes list and
--      become tappable straight into their new topic screen (see
--      src/screens/classes/{technologyEngineeringClass,foreignLanguageClass,
--      healthFitnessClass,businessFinanceClass}/ and the matching
--      Stack.Screen entries added to ClassesStack.js).
--
-- Apply this in the Supabase SQL editor, or via `supabase db push`. The
-- `update` statements are idempotent (merging the same object back onto
-- itself is harmless to re-run); the `insert` block for the 16 new topics
-- uses `on conflict do nothing` per the app's existing app_content seed
-- convention, but has no natural unique key, so only run this file once.

-- ── Enrich remaining Math topics (22) ────────────────────────────────────

update public.app_content
set meta = meta || '{"learn":[{"heading":"Regrouping to Add & Subtract","body":"When a column adds up to more than 9, you \"regroup\" — trade 10 ones for 1 ten and carry it to the next column. Subtraction works in reverse: if the top digit is too small, borrow a ten from the next column and break it into 10 ones."},{"heading":"Arrays and Properties of Multiplication","body":"An array of rows and columns (like 4 rows of 6 dots) shows multiplication as repeated groups. The commutative property means 4 × 6 gives the same total as 6 × 4 — just turn the array on its side. The associative property lets you group factors differently, like (2 × 3) × 4 = 2 × (3 × 4), without changing the answer."}],"practice":[{"question":"What is 47 + 38?","options":["75","85","95","815"],"answerIndex":1,"explanation":"Add ones: 7+8=15, write 5 and regroup 1 ten. Add tens: 4+3+1=8, giving 85."},{"question":"Which shows the commutative property of multiplication?","options":["3 × 5 = 5 × 3","3 × (5 × 2) = (3 × 5) × 2","3 × 1 = 3","3 × 0 = 0"],"answerIndex":0,"explanation":"The commutative property says you can swap the order of factors and get the same product."}],"apply":{"prompt":"Use 24 small objects (coins, beans, or blocks). Arrange them into an array (like 4 rows of 6) to model a multiplication fact, then solve a two-digit addition problem with regrouping using paper and pencil.","checklist":["Built an array with 24 objects","Wrote the multiplication fact the array shows","Solved a two-digit addition problem that needs regrouping","Explained out loud where the regrouped ten went"]}}'::jsonb
where type = 'class_topic' and key = 'NumbersAndOperations' and meta->>'topic_key' = 'whole';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Fractions and Decimals Are the Same Idea","body":"A fraction like 3/4 and a decimal like 0.75 both describe part of a whole — the fraction shows a division (3 ÷ 4) and the decimal shows the same value in tenths, hundredths, and so on. To compare them, it helps to convert to a common form, like giving fractions the same denominator or writing both as decimals."},{"heading":"Adding vs. Multiplying Fractions","body":"To add or subtract fractions, the denominators must match first (find a common denominator), because you can only combine same-size pieces. To multiply fractions, you multiply straight across (numerator × numerator, denominator × denominator) — no common denominator needed, because you''re finding \"a part of a part.\""}],"practice":[{"question":"Which fraction is equivalent to 0.75?","options":["1/2","2/3","3/4","4/5"],"answerIndex":2,"explanation":"3 ÷ 4 = 0.75, so 3/4 and 0.75 name the same value."},{"question":"What is 1/4 + 1/2?","options":["1/6","2/6","3/4","1/2"],"answerIndex":2,"explanation":"Rewrite 1/2 as 2/4, then add: 1/4 + 2/4 = 3/4."}],"apply":{"prompt":"Find a recipe (or make one up) that uses fractional measurements, like 3/4 cup flour or 1/2 teaspoon salt. Double the recipe by adding each fractional amount to itself, then rewrite every fraction in the recipe as a decimal.","checklist":["Listed at least 3 fractional measurements from the recipe","Doubled each amount using fraction addition or multiplication","Converted each original fraction to a decimal","Checked that equivalent fractions and decimals match"]}}'::jsonb
where type = 'class_topic' and key = 'NumbersAndOperations' and meta->>'topic_key' = 'fractions';

update public.app_content
set meta = meta || '{"learn":[{"heading":"What Makes a Number Rational","body":"A rational number can be written as a ratio of two integers, a/b, with b not zero — that includes whole numbers, negatives, fractions, and decimals that terminate (0.5) or repeat forever in a pattern (0.333...). Every rational number''s decimal form either ends or repeats."},{"heading":"Irrational Numbers Fill the Gaps","body":"Irrational numbers, like √2 or π, cannot be written as a simple fraction — their decimals go on forever with no repeating pattern. Together, the rational and irrational numbers make up the real numbers, which fill every point on the number line with no gaps."}],"practice":[{"question":"Which of these numbers is irrational?","options":["3/4","0.5","√2","-7"],"answerIndex":2,"explanation":"√2 cannot be written as a ratio of integers and its decimal never ends or repeats, so it is irrational."},{"question":"Why is 0.333... (repeating) a rational number?","options":["It is negative","It can be written as the fraction 1/3","It has a decimal point","It is greater than 1"],"answerIndex":1,"explanation":"Any repeating decimal can be written as a ratio of two integers, which is the definition of rational."}],"apply":{"prompt":"Draw a number line from -3 to 3 on paper. Plot these six numbers on it in the correct order: -2, 1/2, π, -1.5, √2, and 7/4. Label each point as rational or irrational.","checklist":["Drew a number line from -3 to 3","Plotted all six numbers in correct order","Labeled each as rational or irrational","Explained why π and √2 are irrational"]}}'::jsonb
where type = 'class_topic' and key = 'NumbersAndOperations' and meta->>'topic_key' = 'rational';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Finding the Rule in a Pattern","body":"A pattern like 3, 6, 9, 12 has a rule you can describe in words: \"start at 3 and add 3 each time.\" Once you know the rule, you can predict any term without listing every number in between."},{"heading":"Using Tables to See Relationships","body":"A table with an \"input\" column and \"output\" column helps you spot a pattern between two changing quantities, like the number of tables and the number of chairs needed. Look at how the output changes each time the input goes up by 1 — that tells you the rule."}],"practice":[{"question":"What is the next number in the pattern: 5, 10, 15, 20, ___?","options":["22","24","25","30"],"answerIndex":2,"explanation":"The rule is \"add 5 each time,\" so 20 + 5 = 25."},{"question":"A table shows: 1 table seats 4, 2 tables seat 8, 3 tables seat 12. How many people can sit at 5 tables?","options":["16","18","20","24"],"answerIndex":2,"explanation":"The rule is \"multiply the number of tables by 4,\" so 5 × 4 = 20."}],"apply":{"prompt":"Using buttons, coins, or dried beans, build a growing pattern (like adding 2 more objects to each row). Make a table recording the row number and the number of objects, then predict how many objects would be in row 10.","checklist":["Built at least 3 rows of a growing pattern","Recorded row number and object count in a table","Described the rule in words","Predicted the count for row 10 using the rule"]}}'::jsonb
where type = 'class_topic' and key = 'AlgebraAndFunctions' and meta->>'topic_key' = 'patterns';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Expressions vs. Equations","body":"An expression like 3x + 5 is a phrase with numbers, variables, and operations — it has no equals sign and no single answer until you plug in a value for x. An equation, like 3x + 5 = 20, states that two expressions are equal, and solving it means finding the value of x that makes it true."},{"heading":"Solving by Balancing","body":"An equation is like a balanced scale: whatever you do to one side (add, subtract, multiply, divide), you must do to the other side to keep it balanced. Quadratic equations (with an x²) often need factoring or the quadratic formula because there can be two solutions instead of one."}],"practice":[{"question":"What is the value of the expression 3x + 5 when x = 4?","options":["12","17","9","20"],"answerIndex":1,"explanation":"3 × 4 = 12, then 12 + 5 = 17."},{"question":"Solve for x: 2x + 6 = 20","options":["x = 6","x = 7","x = 8","x = 13"],"answerIndex":2,"explanation":"Subtract 6 from both sides to get 2x = 14, then divide both sides by 2 to get x = 8."}],"apply":{"prompt":"Imagine you are saving money and start with $10 that grows by $3 every week. Write an expression for your total money after w weeks, then write and solve an equation to find how many weeks it takes to reach $34.","checklist":["Wrote the expression 10 + 3w","Set the expression equal to 34 as an equation","Solved the equation by balancing both sides","Checked the answer by substituting it back in"]}}'::jsonb
where type = 'class_topic' and key = 'AlgebraAndFunctions' and meta->>'topic_key' = 'expressions';

update public.app_content
set meta = meta || '{"learn":[{"heading":"What Makes a Relation a Function","body":"A function is a rule that assigns exactly one output to each input — written f(x), read \"f of x.\" If you graph it, every vertical line crosses the graph at most once; if an input ever produced two different outputs, it wouldn''t be a function."},{"heading":"Choosing the Right Model","body":"Real data suggests which function family fits: if the value changes by the same amount each step, it''s linear; if it changes by the same percentage each step, it''s exponential (like compound interest or population growth); if it rises then falls symmetrically, it may be quadratic (like a thrown ball''s height)."}],"practice":[{"question":"If f(x) = 2x + 3, what is f(5)?","options":["10","11","13","8"],"answerIndex":2,"explanation":"f(5) = 2(5) + 3 = 10 + 3 = 13."},{"question":"A savings account grows by 5% each year. What type of function best models the balance over time?","options":["Linear","Quadratic","Exponential","Constant"],"answerIndex":2,"explanation":"A constant percentage change year after year is the hallmark of exponential growth."}],"apply":{"prompt":"Drop a ball from a fixed height and measure how high it bounces back, three times in a row. Record height vs. bounce number in a table, then decide whether a linear or exponential function better models the pattern and explain why.","checklist":["Recorded bounce height for at least 3 bounces","Made a table of bounce number vs. height","Compared successive differences and ratios","Chose linear or exponential and justified the choice"]}}'::jsonb
where type = 'class_topic' and key = 'AlgebraAndFunctions' and meta->>'topic_key' = 'functions';

update public.app_content
set meta = meta || '{"learn":[{"heading":"The Building Blocks of Shapes","body":"A point marks an exact location, a line goes on forever in both directions, and a line segment is a piece of a line with two endpoints. Angles form where two segments or rays meet, and shapes like triangles and polygons are built from segments connected end to end."},{"heading":"Congruent vs. Similar","body":"Two shapes are congruent if they are exactly the same size and shape — one could be placed exactly on top of the other. Two shapes are similar if they have the same shape but different sizes, like a photo and its enlargement — their angles match but their side lengths are scaled."}],"practice":[{"question":"A triangle with all three sides the same length is called what?","options":["Scalene","Equilateral","Right","Obtuse"],"answerIndex":1,"explanation":"An equilateral triangle has three equal sides and three equal angles."},{"question":"Two triangles have the same angle measures but one is twice as big as the other. What is their relationship?","options":["Congruent","Similar","Parallel","Perpendicular"],"answerIndex":1,"explanation":"Same shape but different size means the triangles are similar, not congruent."}],"apply":{"prompt":"Draw two triangles on paper: one congruent copy of a triangle you traced, and one similar but larger version of the same triangle. Use a ruler and tracing paper to check your work.","checklist":["Traced or drew an original triangle","Created a congruent copy using tracing paper","Created a similar, larger version using a ruler to scale each side","Measured angles to confirm they matched in both copies"]}}'::jsonb
where type = 'class_topic' and key = 'GeometrySpatialReasoning' and meta->>'topic_key' = 'plane';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Reading the Coordinate Plane","body":"Every point on the plane is named by an ordered pair (x, y): x tells you how far to move left or right from the origin, and y tells you how far to move up or down. The plane is divided into four quadrants, and the signs of x and y tell you which quadrant a point is in."},{"heading":"Distance, Midpoint, and Slope","body":"The distance formula (built from the Pythagorean theorem) finds the straight-line length between two points. The midpoint formula averages the x-coordinates and averages the y-coordinates to find the point exactly between them. Slope measures steepness as \"rise over run\" — how much y changes for each step in x."}],"practice":[{"question":"In which quadrant is the point (-3, 5) located?","options":["Quadrant I","Quadrant II","Quadrant III","Quadrant IV"],"answerIndex":1,"explanation":"Negative x and positive y place the point in Quadrant II (upper left)."},{"question":"What is the slope of the line through points (1, 2) and (4, 8)?","options":["2","3","6","1/2"],"answerIndex":0,"explanation":"Slope = (8 - 2) / (4 - 1) = 6 / 3 = 2."}],"apply":{"prompt":"On graph paper, plot 5 points to make a simple \"treasure map\" (like a pirate ship, a chest, and an island). Label the coordinates of each point, then calculate the distance and midpoint between two of them.","checklist":["Plotted at least 5 labeled points on graph paper","Recorded each point''s (x, y) coordinates","Calculated the distance between two of the points","Calculated the midpoint between two of the points"]}}'::jsonb
where type = 'class_topic' and key = 'GeometrySpatialReasoning' and meta->>'topic_key' = 'coordinate';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Four Types of Transformations","body":"A translation slides a shape to a new position without turning or flipping it. A rotation turns a shape around a fixed point. A reflection flips a shape over a line, like a mirror image. A dilation changes the size of a shape, making it bigger or smaller while keeping its shape the same."},{"heading":"Lines of Symmetry","body":"A shape has a line of symmetry if you can fold it along that line and both halves match up exactly. Some shapes, like a square, have several lines of symmetry; others, like a scalene triangle, have none."}],"practice":[{"question":"A shape slides 3 units to the right without turning or flipping. This is an example of what transformation?","options":["Rotation","Reflection","Translation","Dilation"],"answerIndex":2,"explanation":"Sliding a shape without turning or flipping is a translation."},{"question":"How many lines of symmetry does a square have?","options":["0","1","2","4"],"answerIndex":3,"explanation":"A square can be folded along 2 diagonals and 2 lines through the midpoints of opposite sides — 4 lines total."}],"apply":{"prompt":"Cut out a few paper shapes (square, rectangle, triangle, heart). Fold each one to find all its lines of symmetry, then trace one shape onto a grid and draw its reflection across a line.","checklist":["Cut out at least 3 different paper shapes","Found and marked every line of symmetry by folding","Traced one shape onto a grid","Drew an accurate reflection of that shape across a line"]}}'::jsonb
where type = 'class_topic' and key = 'GeometrySpatialReasoning' and meta->>'topic_key' = 'transformations';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Nets: Unfolding 3D Shapes","body":"A net is a flat, 2D pattern that folds up into a 3D solid — like cutting a cardboard box along its edges and laying it flat. Seeing the net of a shape helps you visualize exactly which flat faces make up its surface."},{"heading":"Surface Area vs. Volume","body":"Surface area is the total area of all the outer faces of a solid — how much wrapping paper you''d need to cover it — found by adding up the areas of every face in its net. Volume is how much space is inside the solid — how much it could hold — usually found by multiplying base area by height for prisms and cylinders."}],"practice":[{"question":"What is the volume of a rectangular prism with length 4, width 3, and height 5?","options":["12","60","35","20"],"answerIndex":1,"explanation":"Volume = length × width × height = 4 × 3 × 5 = 60."},{"question":"A net made of one rectangle rolled into a tube plus two circles on the ends forms which solid?","options":["Cube","Cone","Cylinder","Sphere"],"answerIndex":2,"explanation":"A cylinder''s net is a rectangle (the curved side) plus two circles (the top and bottom)."}],"apply":{"prompt":"Build a small 3D solid (a cube or rectangular prism) out of paper or cardboard by first drawing its net, cutting it out, and folding it together. Measure its dimensions and calculate its surface area and volume.","checklist":["Drew an accurate net for a chosen solid","Cut out and folded the net into a 3D shape","Measured the dimensions of the solid","Calculated both surface area and volume"]}}'::jsonb
where type = 'class_topic' and key = 'GeometrySpatialReasoning' and meta->>'topic_key' = 'solid';

update public.app_content
set meta = meta || '{"learn":[{"heading":"The Right Tool for the Job","body":"We use a ruler to measure how long something is, a scale to measure how heavy it is, a measuring cup to measure how much liquid it holds, and a clock to measure time. Picking the right tool and the right unit (like inches for a pencil, not miles!) helps your measurement make sense."},{"heading":"Big Units and Small Units","body":"Some units are bigger than others for measuring the same kind of thing — a foot is longer than an inch, and a gallon holds more than a cup. When you measure with a smaller unit, you need a bigger number to describe the same amount."}],"practice":[{"question":"Which is longer: an inch or a foot?","options":["An inch","A foot","They are the same","Neither measures length"],"answerIndex":1,"explanation":"A foot equals 12 inches, so a foot is longer."},{"question":"Which tool would you use to find out how much a puppy weighs?","options":["A ruler","A clock","A scale","A measuring cup"],"answerIndex":2,"explanation":"A scale measures weight."}],"apply":{"prompt":"Find 5 objects around your home. Use a ruler to measure the length of each one in inches, and write down which object was the longest and which was the shortest.","checklist":["Measured 5 different objects with a ruler","Wrote down each length","Identified the longest object","Identified the shortest object"]}}'::jsonb
where type = 'class_topic' and key = 'Measurement' and meta->>'topic_key' = 'units';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Perimeter and Area","body":"Perimeter is the distance around the outside of a shape — add up the length of every side. Area is the amount of flat space inside a shape — for a rectangle, multiply length by width, since you''re counting how many unit squares fit inside."},{"heading":"Volume Adds a Third Dimension","body":"Volume measures how much space is inside a 3D solid, like a box. For a rectangular box, multiply length × width × height — you''re stacking layers of area on top of each other, one layer for each unit of height."}],"practice":[{"question":"What is the perimeter of a rectangle with length 8 cm and width 5 cm?","options":["13 cm","26 cm","40 cm","20 cm"],"answerIndex":1,"explanation":"Perimeter = 2(length + width) = 2(8 + 5) = 26 cm."},{"question":"What is the area of a rectangle with length 6 in and width 4 in?","options":["10 in²","20 in²","24 in²","48 in²"],"answerIndex":2,"explanation":"Area = length × width = 6 × 4 = 24 square inches."}],"apply":{"prompt":"Measure the length and width of a room, a table, or a book at home. Calculate its perimeter and area, then find or estimate a third dimension (like height) to calculate volume for a box-shaped object.","checklist":["Measured length and width of a chosen object","Calculated the perimeter","Calculated the area","Measured a box-shaped object and calculated its volume"]}}'::jsonb
where type = 'class_topic' and key = 'Measurement' and meta->>'topic_key' = 'perimeter';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Classifying Angles","body":"An acute angle measures less than 90 degrees (a narrow opening), a right angle measures exactly 90 degrees (like a square corner), and an obtuse angle measures more than 90 but less than 180 degrees (a wide opening). A protractor lets you measure the exact degree of any angle."},{"heading":"Angle Sums in Polygons","body":"The three angles inside any triangle always add up to 180 degrees, no matter the triangle''s shape. For any polygon, you can find the sum of interior angles with the formula (n − 2) × 180°, where n is the number of sides."}],"practice":[{"question":"An angle measures 120°. What type of angle is it?","options":["Acute","Right","Obtuse","Straight"],"answerIndex":2,"explanation":"An angle between 90° and 180° is obtuse."},{"question":"A triangle has angles of 50° and 60°. What is the third angle?","options":["60°","70°","80°","90°"],"answerIndex":1,"explanation":"The three angles must sum to 180°: 180 − 50 − 60 = 70°."}],"apply":{"prompt":"Find or print a protractor. Measure at least 5 angles around your home (corners of books, picture frames, door openings) and classify each one as acute, right, or obtuse.","checklist":["Measured at least 5 real angles with a protractor","Recorded each angle''s degree measure","Classified each as acute, right, or obtuse","Found at least one example of each type"]}}'::jsonb
where type = 'class_topic' and key = 'Measurement' and meta->>'topic_key' = 'angles';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Map Scale","body":"A map scale, like \"1 inch = 10 miles,\" is a ratio that lets you convert a measured distance on the map into a real-world distance. Measure the distance between two points on the map with a ruler, then multiply by the scale to find the actual distance."},{"heading":"Elapsed Time and Scheduling","body":"Elapsed time is how much time passes between a start and an end point — useful for reading bus schedules, cooking, or planning a trip. Break the calculation into chunks (minutes to the next hour, then whole hours, then remaining minutes) to avoid mixing up base-60 minutes with base-10 numbers."}],"practice":[{"question":"On a map with a scale of 1 inch = 20 miles, two cities are 3.5 inches apart. How far apart are they in real life?","options":["23.5 miles","60 miles","70 miles","80 miles"],"answerIndex":2,"explanation":"3.5 × 20 = 70 miles."},{"question":"A movie starts at 6:45 PM and ends at 9:10 PM. How long is the movie?","options":["2 hours 5 minutes","2 hours 25 minutes","2 hours 15 minutes","3 hours 5 minutes"],"answerIndex":1,"explanation":"From 6:45 to 9:00 is 2 hours 15 minutes; from 9:00 to 9:10 is 10 more minutes, totaling 2 hours 25 minutes."}],"apply":{"prompt":"Find a real map (or print one) with a scale shown. Measure the distance between two real places you know using a ruler, then use the scale to calculate the actual distance and estimate how long a trip would take driving at 60 mph.","checklist":["Found a map with a stated scale","Measured map distance between two points with a ruler","Converted to real-world distance using the scale","Estimated travel time at a given speed"]}}'::jsonb
where type = 'class_topic' and key = 'Measurement' and meta->>'topic_key' = 'applications';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Collecting Good Data","body":"A survey asks the same clear question to a group of people, and an experiment measures something under controlled conditions, like counting how many seeds sprout with different amounts of water. Asking the same question the same way to everyone keeps the data fair to compare."},{"heading":"Choosing the Right Graph","body":"A bar graph compares amounts across separate categories (like favorite fruits). A line plot shows how often each value occurs along a number line, good for small sets of numbers. A histogram groups numeric data into ranges to show a distribution, and a box plot summarizes a data set''s spread using its median and quartiles."}],"practice":[{"question":"You want to compare how many students like pizza, tacos, and salad. Which graph is the best choice?","options":["Bar graph","Line plot","Box plot","None of these"],"answerIndex":0,"explanation":"A bar graph is ideal for comparing amounts across separate categories."},{"question":"Which of these is an example of an experiment rather than a survey?","options":["Asking classmates their favorite color","Measuring plant height with different amounts of sunlight","Asking neighbors how many pets they have","Asking friends their birth month"],"answerIndex":1,"explanation":"An experiment involves controlling a condition (sunlight) and measuring a result (plant height), not just asking a question."}],"apply":{"prompt":"Ask at least 10 people one clear survey question (like \"What''s your favorite season?\"). Record the results in a tally table, then create a bar graph to display the data.","checklist":["Asked the same question to at least 10 people","Recorded answers in a tally table","Created a bar graph from the data","Wrote one sentence describing what the graph shows"]}}'::jsonb
where type = 'class_topic' and key = 'DataStatisticsProbability' and meta->>'topic_key' = 'collection';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Mean, Median, and Mode","body":"The mean is the sum of all values divided by how many there are — the \"average.\" The median is the middle value when the data is sorted in order. The mode is the value that appears most often. The median is often more useful than the mean when a data set has extreme outliers, since one huge or tiny value can pull the mean far off."},{"heading":"Measuring Spread","body":"The range (highest value minus lowest value) gives a quick but rough sense of spread. The interquartile range (IQR) measures the spread of just the middle 50% of the data, making it less sensitive to outliers than the range. Standard deviation measures, on average, how far each value sits from the mean."}],"practice":[{"question":"What is the median of this data set: 4, 7, 9, 2, 5?","options":["4","5","7","9"],"answerIndex":1,"explanation":"Sorted: 2, 4, 5, 7, 9. The middle value is 5."},{"question":"A data set has one extremely high outlier. Which measure is least affected by it?","options":["Mean","Median","Range","Maximum"],"answerIndex":1,"explanation":"The median depends only on the middle position of sorted data, so an extreme outlier barely changes it, unlike the mean."}],"apply":{"prompt":"Collect a small data set from home or family, such as the ages or shoe sizes of everyone in your household. Calculate the mean, median, mode, and range of your data set by hand.","checklist":["Collected at least 5 data values","Calculated the mean","Calculated the median and mode","Calculated the range"]}}'::jsonb
where type = 'class_topic' and key = 'DataStatisticsProbability' and meta->>'topic_key' = 'descriptive';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Theoretical Probability","body":"Theoretical probability predicts how likely an event is based on counting: divide the number of favorable outcomes by the total number of possible outcomes. Rolling a 4 on a fair six-sided die has a theoretical probability of 1/6, since there is 1 favorable outcome out of 6 possible ones."},{"heading":"Theoretical vs. Experimental Probability","body":"Experimental probability comes from actually running a trial many times and counting what happened, like flipping a coin 50 times and seeing how many landed heads. Experimental results won''t always exactly match the theoretical prediction, but the more trials you run, the closer the experimental probability tends to get to the theoretical one."}],"practice":[{"question":"What is the theoretical probability of rolling an even number on a fair six-sided die?","options":["1/6","1/3","1/2","2/3"],"answerIndex":2,"explanation":"There are 3 even numbers (2, 4, 6) out of 6 total outcomes, so 3/6 = 1/2."},{"question":"You flip a coin 10 times and get 7 heads. This result is an example of what?","options":["Theoretical probability","Experimental probability","An impossible event","A certain event"],"answerIndex":1,"explanation":"Data gathered from actually running trials is experimental probability, which can differ from the theoretical 1/2."}],"apply":{"prompt":"Flip a coin 20 times and record how many times it lands heads and tails. Calculate the experimental probability of heads and compare it to the theoretical probability of 1/2.","checklist":["Flipped a coin 20 times","Recorded the results (heads/tails count)","Calculated experimental probability of heads","Compared it to the theoretical probability and explained any difference"]}}'::jsonb
where type = 'class_topic' and key = 'DataStatisticsProbability' and meta->>'topic_key' = 'probability';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Sampling a Population","body":"A population is the entire group you want to know about (like all students in a school), while a sample is a smaller group you actually measure. A random sample, where every member has an equal chance of being chosen, helps avoid bias so the sample fairly represents the whole population."},{"heading":"Confidence Intervals and Hypothesis Testing","body":"A confidence interval gives a range of plausible values for a population statistic, along with a confidence level (like 95%) describing how often that method would capture the true value across repeated samples. Hypothesis testing uses sample data to decide whether there is enough evidence to reject a starting assumption about the population."}],"practice":[{"question":"A researcher surveys only students in the front row of one class to represent the whole school. What is the main problem with this sample?","options":["It is too large","It is not random and may be biased","It has too many people","There is no problem"],"answerIndex":1,"explanation":"Choosing only front-row students is not random and likely does not represent the whole school fairly."},{"question":"A poll reports a result with a 95% confidence interval of 48% to 54%. What does this mean?","options":["Exactly 51% of the population agrees","The method used would capture the true population value in about 95% of samples like this one","There is a 95% chance the poll is wrong","The sample size was 95"],"answerIndex":1,"explanation":"A confidence interval describes the reliability of the estimation method, not a guarantee about one single interval."}],"apply":{"prompt":"Design a short survey question about a topic you care about. Describe a random sampling plan to fairly survey at least 15 people (avoiding bias), collect the data, and summarize your findings with a percentage.","checklist":["Wrote one clear survey question","Described a plan to randomly select at least 15 people","Collected responses from real people","Summarized the results as a percentage and noted any possible bias"]}}'::jsonb
where type = 'class_topic' and key = 'DataStatisticsProbability' and meta->>'topic_key' = 'inference';

update public.app_content
set meta = meta || '{"learn":[{"heading":"SOH-CAH-TOA","body":"In a right triangle, sine is the opposite side divided by the hypotenuse, cosine is the adjacent side divided by the hypotenuse, and tangent is the opposite side divided by the adjacent side — remembered as SOH-CAH-TOA. These ratios let you find unknown sides or angles without measuring them directly."},{"heading":"The Unit Circle","body":"The unit circle is a circle with radius 1 centered at the origin. As an angle sweeps around the circle, the x-coordinate of the point equals cosine of that angle and the y-coordinate equals sine — this extends sine and cosine to any angle, not just those inside a right triangle, and reveals patterns like sine repeating every 360°."}],"practice":[{"question":"In a right triangle, the side opposite a 30° angle is 5 and the hypotenuse is 10. What is sin(30°)?","options":["0.5","2","5","10"],"answerIndex":0,"explanation":"sin(30°) = opposite / hypotenuse = 5/10 = 0.5."},{"question":"On the unit circle, what is the value of sin(90°)?","options":["0","0.5","1","-1"],"answerIndex":2,"explanation":"At 90° on the unit circle, the point is (0, 1), so sin(90°) = the y-coordinate = 1."}],"apply":{"prompt":"On a sunny day, measure the length of the shadow cast by a fixed-height object (like a yardstick standing upright). Use the shadow length and the object''s height to calculate the angle of elevation of the sun using tangent.","checklist":["Measured the height of an upright object","Measured the length of its shadow","Set up tan(angle) = height / shadow length","Solved for the angle of elevation"]}}'::jsonb
where type = 'class_topic' and key = 'AdvancedMath' and meta->>'topic_key' = 'trigonometry';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Complex Numbers","body":"A complex number has the form a + bi, where a is the real part and bi is the imaginary part, built from i = √-1. Complex numbers let us find solutions to equations like x² = -1, which have no answer among the real numbers alone."},{"heading":"Arithmetic and Geometric Sequences","body":"An arithmetic sequence changes by adding the same constant each step (like 3, 7, 11, 15...), while a geometric sequence changes by multiplying by the same constant ratio each step (like 3, 6, 12, 24...). Recognizing which type a sequence is tells you whether to use an addition rule or a multiplication rule to find future terms."}],"practice":[{"question":"What is the value of i²?","options":["1","-1","i","0"],"answerIndex":1,"explanation":"By definition, i = √-1, so i² = -1."},{"question":"What is the next term in the geometric sequence 2, 6, 18, 54, ___?","options":["58","108","162","216"],"answerIndex":2,"explanation":"Each term is multiplied by 3, so 54 × 3 = 162."}],"apply":{"prompt":"Take a sheet of paper and fold it in half repeatedly, recording the number of layers after each fold (1, 2, 4, 8...). Identify this as a geometric sequence, find its common ratio, and predict the number of layers after 10 folds using the formula.","checklist":["Folded paper and recorded layers after at least 5 folds","Identified the sequence as geometric","Found the common ratio","Predicted the 10th term using the geometric formula"]}}'::jsonb
where type = 'class_topic' and key = 'AdvancedMath' and meta->>'topic_key' = 'precalculus';

update public.app_content
set meta = meta || '{"learn":[{"heading":"The Derivative as Rate of Change","body":"A derivative measures how fast something is changing at a single instant — like the exact speed of a car at one moment, not just its average speed over a trip. Graphically, it''s the slope of the line tangent to a curve at a specific point, found by taking the limit of the slope between two points as they get infinitely close together."},{"heading":"The Integral as Accumulated Area","body":"A definite integral finds the area between a curve and the x-axis over an interval — useful for adding up an infinite number of infinitely thin slices, like total distance traveled from a speed graph. Integration and differentiation are inverse operations of each other, which is the key idea behind the Fundamental Theorem of Calculus."}],"practice":[{"question":"What does the derivative of a position function represent?","options":["Total distance traveled","Velocity (rate of change of position)","Area under the curve","The starting position"],"answerIndex":1,"explanation":"The derivative of position with respect to time gives velocity, the instantaneous rate of change of position."},{"question":"What does a definite integral of a velocity function over a time interval represent?","options":["The velocity at one instant","The acceleration","The total displacement over that interval","The slope of the velocity graph"],"answerIndex":2,"explanation":"Integrating velocity over time accumulates the total displacement traveled during that interval."}],"apply":{"prompt":"Roll a ball down a ramp (or ride in a car and note the speedometer) and record its position or speed at several evenly spaced time intervals. Estimate the speed between two nearby time points using the change in position divided by the change in time, mimicking a derivative.","checklist":["Recorded position or speed at several time points","Chose two nearby time points to compare","Calculated change in position divided by change in time","Explained how this estimate approximates the instantaneous rate of change"]}}'::jsonb
where type = 'class_topic' and key = 'AdvancedMath' and meta->>'topic_key' = 'calculus';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Sets and Logic","body":"A set is a collection of distinct objects. The union of two sets (A ∪ B) combines everything in either set, while the intersection (A ∩ B) keeps only what''s in both. Logical statements can be combined with AND, OR, and NOT, and a truth table lists every possible true/false outcome of a statement."},{"heading":"Graph Theory Basics","body":"A graph is made of vertices (points, also called nodes) connected by edges (lines). Graphs can model real networks, like friendships, roads, or webpages — the number of edges touching a vertex is called its degree, and finding the shortest path between two vertices is a classic graph theory problem."}],"practice":[{"question":"If A = {1, 2, 3} and B = {2, 3, 4}, what is A ∩ B (the intersection)?","options":["{1, 2, 3, 4}","{2, 3}","{1, 4}","{}"],"answerIndex":1,"explanation":"The intersection contains only elements in both sets: 2 and 3."},{"question":"In graph theory, what do we call the points connected by edges in a graph?","options":["Nodes or vertices","Roots","Branches","Coordinates"],"answerIndex":0,"explanation":"The points in a graph are called vertices (or nodes), and the connections between them are edges."}],"apply":{"prompt":"Draw a graph representing a real network you know, such as which friends are connected to which other friends, or the subway/bus stops near you. Mark vertices and edges, then find the shortest path (fewest edges) between two chosen vertices.","checklist":["Drew at least 6 vertices representing a real network","Connected them with edges based on real relationships","Labeled the degree of at least 2 vertices","Found the shortest path between two chosen vertices"]}}'::jsonb
where type = 'class_topic' and key = 'AdvancedMath' and meta->>'topic_key' = 'discrete';

-- ── Enrich remaining Language Arts topics: Reading + Writing (26) ───────

update public.app_content
set meta = meta || '{"learn":[{"heading":"How Books Work","body":"Books have a front cover, a back cover, and pages that turn one at a time. In English, we read words from left to right and from the top of the page to the bottom, then sweep back to the left for the next line."},{"heading":"Letters Make Words","body":"A letter is a single symbol like \"b\" or \"t.\" When we put letters together, they make a word, and when we put words together with spaces between them, they make a sentence."}],"practice":[{"question":"When reading a page in English, which way do your eyes move first?","options":["Bottom to top","Right to left","Left to right","In circles"],"answerIndex":2,"explanation":"English print is read left to right, then top to bottom."},{"question":"What do we call the space between two words?","options":["A period","A word space","A letter","A title"],"answerIndex":1,"explanation":"Spaces separate one word from the next so readers know where each word starts and ends."}],"apply":{"prompt":"Grab any picture book. Point to the front cover, then point to the title. Open to the first page and use your finger to track each line of words from left to right as a grown-up reads it aloud.","checklist":["Pointed to the front cover","Pointed to the title","Tracked words left to right with a finger","Turned pages one at a time in order"]}}'::jsonb
where type = 'class_topic' and key = 'Reading' and meta->>'topic_key' = 'printConcepts';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Letters Have Sounds","body":"Every letter (or group of letters) stands for a sound. The letter \"b\" makes a /b/ sound like in \"bat,\" and \"sh\" makes one sound /sh/ like in \"ship.\" Sounding out letters in order helps you read a new word."},{"heading":"Sight Words","body":"Some common words, like \"the\" or \"said,\" don''t sound out the normal way, so readers learn to recognize them instantly by sight instead of sounding them out every time."}],"practice":[{"question":"What sound does the letter \"m\" make at the start of \"map\"?","options":["/s/","/m/","/t/","/p/"],"answerIndex":1,"explanation":"The letter \"m\" makes the /m/ sound, as heard at the beginning of \"map.\""},{"question":"Which word is a \"sight word\" kids usually memorize instead of sounding out?","options":["cat","said","jump","run"],"answerIndex":1,"explanation":"\"Said\" is not spelled the way it sounds, so readers learn to recognize it by sight."}],"apply":{"prompt":"Pick 5 words from a book you are reading. Sound out each letter slowly, then blend the sounds together to say the whole word.","checklist":["Chose 5 words","Sounded out each letter","Blended sounds into the whole word","Read each word out loud"]}}'::jsonb
where type = 'class_topic' and key = 'Reading' and meta->>'topic_key' = 'phonicsWordRecognition';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Speed, Accuracy, and Expression","body":"Fluent reading means reading words correctly (accuracy), at a smooth pace (speed), and with your voice going up and down to match the meaning (expression) — not just saying words one by one like a robot."},{"heading":"Practice Makes It Automatic","body":"The more you read the same words and stories, the more automatic word recognition becomes, which frees up your brain to focus on understanding the story instead of decoding every word."}],"practice":[{"question":"Which of these best describes a fluent reader?","options":["Reads very slowly and stops on every word","Reads smoothly, accurately, and with expression","Only reads silently","Skips words they do not know"],"answerIndex":1,"explanation":"Fluency means accurate, smooth reading with expression, not just fast reading."},{"question":"Why does re-reading the same story help fluency?","options":["It makes the story shorter","It helps word recognition become automatic","It changes the words","It is required by teachers"],"answerIndex":1,"explanation":"Repeated reading builds automatic word recognition, which frees attention for meaning and expression."}],"apply":{"prompt":"Choose a short page from a favorite book. Read it aloud three times, trying to sound more smooth and expressive each time — like a character talking, not a robot.","checklist":["Read the page aloud 3 times","Used a different voice for excited or sad parts","Read without stopping on every word by the 3rd try","Had someone listen to the last read-aloud"]}}'::jsonb
where type = 'class_topic' and key = 'Reading' and meta->>'topic_key' = 'fluency';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Character, Setting, Plot","body":"Every story has characters (the people or animals it happens to), a setting (the time and place it happens), and a plot (the sequence of events, including a problem and how it gets solved)."},{"heading":"How They Work Together","body":"The setting can shape what problems characters face, and the plot usually follows a pattern: a problem starts the story, events build tension, and a resolution wraps it up."}],"practice":[{"question":"In a story, the \"setting\" refers to...","options":["The main character","The time and place the story happens","The problem in the story","The ending"],"answerIndex":1,"explanation":"Setting is the when and where of a story."},{"question":"The series of events in a story, including the problem and how it is solved, is called the...","options":["Setting","Theme","Plot","Genre"],"answerIndex":2,"explanation":"Plot is the sequence of events that make up the story, centered on a problem and its resolution."}],"apply":{"prompt":"Pick a story you have read recently. Create a simple chart identifying its main character, setting, the problem, and how the problem was resolved.","checklist":["Identified the main character","Identified the setting (time and place)","Described the problem","Described how the problem was solved"]}}'::jsonb
where type = 'class_topic' and key = 'Reading' and meta->>'topic_key' = 'storyElements';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Finding the Theme","body":"A theme is the underlying message or life lesson a story teaches — like \"kindness matters\" or \"honesty is important.\" It is not stated directly; readers figure it out from what happens to the characters."},{"heading":"Author''s Purpose (PIE)","body":"Authors write for a reason: to Persuade (convince you of something), Inform (teach you facts), or Entertain (tell an enjoyable story). Looking at word choice and content helps you figure out which one."}],"practice":[{"question":"A story about a boy who learns to share his toys probably has the theme...","options":["Sharing is important","Toys are expensive","Boys like trucks","Sharing is boring"],"answerIndex":0,"explanation":"The lesson the character learns points to the underlying theme of the story."},{"question":"A magazine article listing facts about volcanoes was most likely written to...","options":["Persuade","Inform","Entertain","Confuse"],"answerIndex":1,"explanation":"An article full of facts is meant to inform readers about a topic."}],"apply":{"prompt":"Read a short story or article. Write one sentence stating its theme (if a story) or its purpose (if nonfiction), and give one piece of evidence from the text that supports your answer.","checklist":["Named the theme or purpose","Gave one piece of text evidence","Explained why that evidence supports the answer","Used a complete sentence"]}}'::jsonb
where type = 'class_topic' and key = 'Reading' and meta->>'topic_key' = 'themesAuthorsPurpose';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Metaphor vs. Simile","body":"A simile compares two things using \"like\" or \"as\" (\"brave as a lion\"), while a metaphor states that one thing IS another without those words (\"he is a lion in battle\") to create a vivid image."},{"heading":"Symbolism","body":"Symbolism is when an object, person, or color represents an idea beyond its literal meaning — a dove often symbolizes peace, and a storm often symbolizes conflict or turmoil in a story."}],"practice":[{"question":"Which sentence contains a simile?","options":["Her smile was sunshine.","Her smile was as bright as sunshine.","The sunshine smiled.","She never smiled."],"answerIndex":1,"explanation":"A simile uses \"like\" or \"as\" to compare two things; this sentence uses \"as.\""},{"question":"A dove appearing at the end of a war story most likely symbolizes...","options":["Danger","Peace","Hunger","Speed"],"answerIndex":1,"explanation":"Doves are a traditional symbol for peace, especially after conflict."}],"apply":{"prompt":"Write three original sentences about your day: one using a simile, one using a metaphor, and one that uses a simple symbol (an object that represents a feeling or idea).","checklist":["Wrote a sentence with a simile using \"like\" or \"as\"","Wrote a sentence with a metaphor (no \"like\"/\"as\")","Wrote a sentence using an object as a symbol","Labeled which device is which"]}}'::jsonb
where type = 'class_topic' and key = 'Reading' and meta->>'topic_key' = 'literaryDevices';

update public.app_content
set meta = meta || '{"learn":[{"heading":"What Is the Main Idea?","body":"The main idea is the most important point a paragraph or passage is making — what it is mostly about. Everything else in the passage is there to support or explain that one central point."},{"heading":"Supporting Details","body":"Supporting details are the facts, examples, and explanations that back up the main idea. A good way to find the main idea is to ask, \"What do all these details have in common?\""}],"practice":[{"question":"The main idea of a paragraph is best described as...","options":["A random fact","The most important point the paragraph makes","The last sentence only","The title of the book"],"answerIndex":1,"explanation":"The main idea is the central point that everything else in the paragraph supports."},{"question":"Supporting details in a paragraph mainly serve to...","options":["Confuse the reader","Back up and explain the main idea","Replace the main idea","End the paragraph"],"answerIndex":1,"explanation":"Supporting details provide evidence and explanation for the main idea."}],"apply":{"prompt":"Read a short nonfiction paragraph (from a book, magazine, or website). Write the main idea in one sentence, then list two supporting details from the text.","checklist":["Read a nonfiction paragraph","Wrote the main idea in one sentence","Listed two supporting details","Checked that details connect to the main idea"]}}'::jsonb
where type = 'class_topic' and key = 'Reading' and meta->>'topic_key' = 'mainIdea';

update public.app_content
set meta = meta || '{"learn":[{"heading":"What Are Text Features?","body":"Text features are the parts of a nonfiction text besides the main paragraphs — headings, bold words, captions, charts, diagrams, and the table of contents — that help readers find and understand information faster."},{"heading":"Using Them Strategically","body":"Headings preview what a section is about, captions explain pictures, and charts organize data visually — good readers glance at these features before reading closely to build a preview of the whole text."}],"practice":[{"question":"A short sentence under a photo that explains what it shows is called a...","options":["Heading","Caption","Index","Glossary"],"answerIndex":1,"explanation":"A caption is text that describes or explains an image."},{"question":"Which text feature would help you find the page number for a specific chapter?","options":["Table of contents","Caption","Bold word","Diagram"],"answerIndex":0,"explanation":"The table of contents lists chapters or sections with their page numbers."}],"apply":{"prompt":"Find a nonfiction book or magazine article. List every text feature you can spot (headings, captions, charts, bold words, etc.) and explain what each one helps you understand.","checklist":["Found at least 4 text features","Named each feature correctly","Explained what each feature shows","Used a real nonfiction source"]}}'::jsonb
where type = 'class_topic' and key = 'Reading' and meta->>'topic_key' = 'textFeatures';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Five Common Structures","body":"Authors organize informational text in patterns: cause/effect (why something happened), compare/contrast (how two things are alike/different), sequence (order of events), problem/solution, and description."},{"heading":"Signal Words Give It Away","body":"You can identify structure by its clue words: \"because\" and \"as a result\" signal cause/effect; \"however\" and \"similarly\" signal compare/contrast; \"first,\" \"next,\" \"finally\" signal sequence."}],"practice":[{"question":"A passage using words like \"however\" and \"in contrast\" is probably using which structure?","options":["Sequence","Compare/contrast","Cause/effect","Description"],"answerIndex":1,"explanation":"\"However\" and \"in contrast\" are signal words for the compare/contrast structure."},{"question":"A passage that explains why a volcano erupted and what happened afterward uses which structure?","options":["Cause/effect","Sequence","Description","Compare/contrast"],"answerIndex":0,"explanation":"Explaining why something happened and its result is the cause/effect structure."}],"apply":{"prompt":"Find a short informational article. Identify which text structure it mainly uses and highlight or list at least two signal words that helped you decide.","checklist":["Identified the text structure","Found at least 2 signal words","Explained why those words point to that structure","Used a real article"]}}'::jsonb
where type = 'class_topic' and key = 'Reading' and meta->>'topic_key' = 'textStructure';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Using the Sentence Around a Word","body":"When you hit a word you don''t know, look at the words and sentences around it — those \"context clues\" often hint at the meaning through definitions, examples, synonyms, or contrast within the same passage."},{"heading":"Types of Clues","body":"Sometimes the author gives a direct definition (\"a mammal, an animal with fur, that...\"), sometimes an example (\"pets, such as dogs and cats\"), and sometimes a contrast word like \"but\" or \"unlike\" that hints at an opposite meaning."}],"practice":[{"question":"In \"The arid desert had almost no rainfall,\" what does \"arid\" most likely mean?","options":["Wet","Dry","Cold","Green"],"answerIndex":1,"explanation":"\"Almost no rainfall\" is a context clue showing \"arid\" means dry."},{"question":"Which strategy uses the words around an unknown word to figure out its meaning?","options":["Skipping the word","Context clues","Reading faster","Looking at the cover"],"answerIndex":1,"explanation":"Context clues use surrounding text to infer meaning."}],"apply":{"prompt":"Find three unfamiliar words in a book you are reading. For each one, write the sentence it appears in, guess its meaning using context clues, then check a dictionary to see how close you were.","checklist":["Found 3 unfamiliar words","Wrote down the sentence for each","Guessed a meaning using context clues","Checked each guess against a dictionary"]}}'::jsonb
where type = 'class_topic' and key = 'Reading' and meta->>'topic_key' = 'contextClues';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Roots, Prefixes, Suffixes","body":"A root carries a word''s core meaning (like \"port,\" meaning \"to carry\"). A prefix attaches to the front (\"trans-\" means across, so \"transport\" = carry across); a suffix attaches to the end and can change meaning or part of speech."},{"heading":"Why Learning Them Helps","body":"Once you know that \"bio\" means life and \"-ology\" means study of, you can figure out that \"biology\" means the study of life — and unlock dozens of related words without memorizing each one separately."}],"practice":[{"question":"The root \"spect\" means \"to look.\" What does \"inspect\" most likely mean?","options":["To look inside/closely at","To listen","To run away","To build"],"answerIndex":0,"explanation":"\"In-\" (into) + \"spect\" (look) suggests looking closely at or into something."},{"question":"Which prefix means \"not\" or \"opposite of,\" as in \"unhappy\"?","options":["re-","un-","pre-","-ful"],"answerIndex":1,"explanation":"The prefix \"un-\" reverses or negates a word''s meaning."}],"apply":{"prompt":"Choose one Greek or Latin root (like \"bio,\" \"graph,\" \"tele,\" or \"spect\"). List at least 4 English words built from it, and explain how the root''s meaning shows up in each one.","checklist":["Chose a root and stated its meaning","Listed at least 4 words using that root","Explained the meaning connection for each word","Used a dictionary to check any doubts"]}}'::jsonb
where type = 'class_topic' and key = 'Reading' and meta->>'topic_key' = 'wordRootsAffixes';

update public.app_content
set meta = meta || '{"learn":[{"heading":"What Are Academic & Domain-Specific Terms?","body":"Academic vocabulary (like \"analyze,\" \"synthesize,\" \"hypothesis\") appears across many subjects in school writing, while domain-specific terms (like \"mitochondria\" or \"amendment\") belong to one particular field of study."},{"heading":"Reading Across Subjects","body":"Strong readers in high school build a working vocabulary of these terms because they appear constantly in textbooks and exams — precise understanding of a term like \"correlation\" versus \"causation\" can change how you interpret an entire passage."}],"practice":[{"question":"Which term is a general academic word likely to appear across many subjects?","options":["Photosynthesis","Analyze","Amendment","Mitochondria"],"answerIndex":1,"explanation":"\"Analyze\" is a general academic verb used across subjects, unlike the other domain-specific terms."},{"question":"\"Amendment\" is a domain-specific term most associated with which subject?","options":["Biology","Government/History","Chemistry","Art"],"answerIndex":1,"explanation":"\"Amendment\" refers to a formal change to a law or constitution, a term specific to government and history."}],"apply":{"prompt":"Pick a chapter from one of your textbooks (science, history, or math). List 5 domain-specific terms from it, and write a precise one-sentence definition for each using context from the chapter.","checklist":["Chose a textbook chapter","Listed 5 domain-specific terms","Wrote a precise definition for each","Used context from the chapter, not just a dictionary copy"]}}'::jsonb
where type = 'class_topic' and key = 'Reading' and meta->>'topic_key' = 'academicDomainTerms';

update public.app_content
set meta = meta || '{"learn":[{"heading":"What Is an Inference?","body":"An inference is a logical conclusion you draw by combining clues the author gives with what you already know — the author doesn''t state it directly, but the text plus your background knowledge lead you there."},{"heading":"Text Evidence + Background Knowledge","body":"A strong inference always has two parts: specific evidence from the text and a piece of your own knowledge or reasoning that connects the dots — \"the text says X, and I know Y, so I can infer Z.\""}],"practice":[{"question":"An inference is best described as...","options":["A fact directly stated in the text","A conclusion drawn from clues plus background knowledge","A random guess with no evidence","The title of the passage"],"answerIndex":1,"explanation":"Inferences combine textual evidence with prior knowledge to reach a logical conclusion."},{"question":"If a character \"slammed the door and threw her backpack on the floor,\" you can infer she is probably feeling...","options":["Relaxed","Angry or upset","Sleepy","Bored"],"answerIndex":1,"explanation":"Slamming a door and throwing a backpack are actions that suggest frustration, even though the text never says \"angry.\""}],"apply":{"prompt":"Read a short passage or a page of a novel. Write one inference about a character or situation, then explain the specific text evidence and background knowledge that led you there.","checklist":["Wrote a clear inference (not a directly stated fact)","Cited specific text evidence","Explained the background knowledge used","Connected both to the conclusion"]}}'::jsonb
where type = 'class_topic' and key = 'Reading' and meta->>'topic_key' = 'makingInferences';

update public.app_content
set meta = meta || '{"learn":[{"heading":"What Belongs in a Summary","body":"A summary retells the most important events or ideas of a text in your own words, in a much shorter form — it leaves out small details and never adds your personal opinion."},{"heading":"Somebody-Wanted-But-So-Then","body":"A handy trick for summarizing a story: Somebody (the character) Wanted (a goal) But (a problem) So (what they did) Then (the result) — this keeps a summary short and focused on the essentials."}],"practice":[{"question":"A good summary should...","options":["Include every single detail","Retell the main points in your own words, briefly","Give your personal opinion of the story","Be longer than the original text"],"answerIndex":1,"explanation":"Summaries are brief restatements of the most important ideas, not full retellings or opinions."},{"question":"In the \"Somebody-Wanted-But-So\" strategy, the \"But\" stands for...","options":["The setting","The character''s problem","The ending","The title"],"answerIndex":1,"explanation":"\"But\" identifies the obstacle or problem that gets in the way of what the character wanted."}],"apply":{"prompt":"Read a short story. Write a 3-4 sentence summary using the Somebody-Wanted-But-So-Then structure, without copying full sentences from the original text.","checklist":["Identified the somebody (character)","Identified what they wanted and the problem (but)","Explained what they did and the result (so-then)","Wrote it in your own words, 3-4 sentences"]}}'::jsonb
where type = 'class_topic' and key = 'Reading' and meta->>'topic_key' = 'summarizing';

update public.app_content
set meta = meta || '{"learn":[{"heading":"What Is Self-Monitoring?","body":"Self-monitoring means noticing, while you read, whether you are actually understanding the text — catching the moment your mind wanders or a passage stops making sense, instead of reading blindly to the end."},{"heading":"Fix-Up Strategies","body":"When comprehension breaks down, strong readers pause and use fix-up strategies: re-reading the confusing part, reading on for more context, looking up an unfamiliar word, or asking themselves a clarifying question before continuing."}],"practice":[{"question":"Self-monitoring while reading means...","options":["Reading as fast as possible","Tracking whether you understand what you are reading","Skipping difficult sections","Reading only the first and last paragraph"],"answerIndex":1,"explanation":"Self-monitoring is the ongoing awareness of your own comprehension as you read."},{"question":"If you realize you have no idea what the last paragraph said, the best \"fix-up\" strategy is to...","options":["Keep reading forward without stopping","Close the book","Re-read the confusing paragraph","Skip to the next chapter"],"answerIndex":2,"explanation":"Re-reading a confusing section is a core fix-up strategy for restoring comprehension."}],"apply":{"prompt":"Read a challenging article or textbook section. Every paragraph, pause and jot a quick self-check note (\"got it\" or \"confused, re-read\"). Where you got confused, apply one fix-up strategy and note what helped.","checklist":["Paused after each paragraph to self-check","Marked at least one point of confusion","Applied a specific fix-up strategy","Noted whether the strategy helped"]}}'::jsonb
where type = 'class_topic' and key = 'Reading' and meta->>'topic_key' = 'monitoringSelfQuestioning';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Claim + Evidence + Reasoning","body":"Argumentative writing states a clear claim (your position), then supports it with evidence (facts, examples, data) and reasoning that explains how the evidence proves your claim."},{"heading":"Addressing the Other Side","body":"Strong argumentative writing also acknowledges a counterargument — an opposing view — and explains why your position still holds up, which makes your argument more persuasive and credible."}],"practice":[{"question":"The sentence that states your position in an argumentative essay is called the...","options":["Counterargument","Claim","Citation","Conclusion"],"answerIndex":1,"explanation":"The claim is the writer''s stated position or thesis."},{"question":"Addressing an opposing viewpoint in your essay and explaining why your position still stands is called...","options":["Plagiarism","A counterargument rebuttal","A hook","Formatting"],"answerIndex":1,"explanation":"Acknowledging and responding to the other side strengthens the credibility of an argument."}],"apply":{"prompt":"Write a short argumentative paragraph on a topic you care about (like school lunch, homework, or screen time). Include a clear claim, two pieces of evidence, and one sentence addressing a counterargument.","checklist":["Stated a clear claim","Included two pieces of evidence","Addressed one counterargument","Wrote in a full paragraph"]}}'::jsonb
where type = 'class_topic' and key = 'Writing' and meta->>'topic_key' = 'opinionArgumentative';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Explaining, Not Persuading","body":"Informative/explanatory writing teaches the reader about a topic using facts, definitions, and examples — its goal is to make something clear, not to convince the reader of an opinion."},{"heading":"Organizing with Structure","body":"Good informative writing groups related facts together under clear topic sentences, often using text features like headings, and ends with a concluding statement that wraps up the information."}],"practice":[{"question":"The main goal of informative/explanatory writing is to...","options":["Convince the reader of an opinion","Tell an exciting story","Clearly explain facts about a topic","Persuade with emotional language"],"answerIndex":2,"explanation":"Informative writing is meant to inform and explain, not persuade or entertain."},{"question":"Which sentence would fit best in an informative paragraph about sharks?","options":["I think sharks are the scariest animal!","Sharks have been around for over 400 million years.","Once upon a time, a shark went on an adventure.","You should never go in the ocean."],"answerIndex":1,"explanation":"This is a factual, informative statement — not an opinion or a story."}],"apply":{"prompt":"Choose an animal, place, or object you know facts about. Write an informative paragraph with a topic sentence, three supporting facts, and a concluding sentence.","checklist":["Wrote a clear topic sentence","Included 3 supporting facts","Avoided personal opinions","Wrote a concluding sentence"]}}'::jsonb
where type = 'class_topic' and key = 'Writing' and meta->>'topic_key' = 'informativeExplanatory';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Telling a Story","body":"A narrative tells a story that happened (or a made-up one) with characters, a setting (where and when), and events that happen in order — usually a beginning, middle, and end."},{"heading":"Using Your Senses and Feelings","body":"Good narratives include small details — what things looked, sounded, or felt like — and tell how the character felt, which helps the reader picture the story and care about what happens."}],"practice":[{"question":"A narrative is a piece of writing that...","options":["Lists facts about animals","Tells a story with a beginning, middle, and end","Gives directions for a recipe","Argues an opinion"],"answerIndex":1,"explanation":"Narratives tell stories in order, from beginning to end."},{"question":"Which sentence belongs in a narrative story?","options":["Dogs have four legs and fur.","She grabbed her umbrella and ran through the rain.","The capital of France is Paris.","Water boils at 100 degrees Celsius."],"answerIndex":1,"explanation":"This sentence describes an action happening to a character — part of a story, not a fact list."}],"apply":{"prompt":"Write a short story (4-6 sentences) about something fun that happened to you, or make one up. Include a beginning, a middle event, and an end.","checklist":["Has a clear beginning","Has a middle event or problem","Has an ending","Tells events in order"]}}'::jsonb
where type = 'class_topic' and key = 'Writing' and meta->>'topic_key' = 'narrative';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Why Plan First","body":"Before writing, good writers gather ideas and information — brainstorming topics, jotting notes, or making a simple outline — so they know what they want to say before they start drafting."},{"heading":"Graphic Organizers","body":"Tools like webs, outlines, or T-charts help writers sort their ideas into groups before writing, which makes the actual drafting faster and keeps the writing organized."}],"practice":[{"question":"What is the main purpose of the planning stage of writing?","options":["To publish the final piece","To gather and organize ideas before drafting","To fix spelling mistakes","To share your writing with others"],"answerIndex":1,"explanation":"Planning happens before drafting, to gather and organize ideas."},{"question":"A tool like a web or outline used before writing is called a...","options":["Rough draft","Graphic organizer","Final copy","Citation"],"answerIndex":1,"explanation":"Graphic organizers help writers visually sort ideas during the planning stage."}],"apply":{"prompt":"Pick a topic you want to write about. Make a simple graphic organizer (a web or list) with at least 4 ideas or facts you could include in your writing.","checklist":["Chose a specific topic","Made a graphic organizer or outline","Listed at least 4 ideas","Grouped related ideas together"]}}'::jsonb
where type = 'class_topic' and key = 'Writing' and meta->>'topic_key' = 'planningResearch';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Getting Ideas on Paper","body":"Drafting means writing your first version of a piece using your plan as a guide — the goal is to get all your ideas down in order, not to make it perfect yet."},{"heading":"It''s Okay to Be Messy","body":"A first draft is expected to have mistakes and rough spots — writers focus on content and organization during drafting, and save fixing spelling, grammar, and word choice for the revising and editing stage later."}],"practice":[{"question":"The main goal while drafting is to...","options":["Get your ideas written down in order","Fix every spelling mistake","Publish the final copy","Share it with the class"],"answerIndex":0,"explanation":"Drafting is about getting ideas on paper using your plan, not perfecting the writing."},{"question":"It is normal for a first draft to...","options":["Be completely perfect","Have some mistakes and rough spots","Be shorter than the final published piece","Skip the topic entirely"],"answerIndex":1,"explanation":"First drafts are expected to be imperfect — polishing happens during revising and editing."}],"apply":{"prompt":"Using a graphic organizer or plan you already made (or make a quick one now), write a first draft paragraph. Do not stop to fix small mistakes — just get your ideas down.","checklist":["Used a plan or organizer to guide the draft","Wrote a full paragraph","Kept writing without stopping to fix every mistake","Included all main ideas from the plan"]}}'::jsonb
where type = 'class_topic' and key = 'Writing' and meta->>'topic_key' = 'drafting';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Revising vs. Editing","body":"Revising means improving the content — reorganizing ideas, adding detail, cutting unclear parts, or strengthening word choice. Editing comes after and focuses on fixing mechanics: spelling, grammar, capitalization, and punctuation."},{"heading":"Reading With Fresh Eyes","body":"Effective revision often means reading your draft aloud or having someone else read it — hearing awkward phrasing or gaps in logic is much easier than just seeing it silently on the page."}],"practice":[{"question":"Which task belongs to REVISING rather than editing?","options":["Fixing a comma splice","Correcting a spelling error","Reorganizing paragraphs for clarity","Capitalizing a proper noun"],"answerIndex":2,"explanation":"Reorganizing ideas for clarity is a content-level change, which is revising, not editing."},{"question":"Editing mainly focuses on fixing...","options":["The order of ideas","Spelling, grammar, and punctuation","The topic of the essay","The audience"],"answerIndex":1,"explanation":"Editing addresses surface-level mechanics like spelling and grammar."}],"apply":{"prompt":"Take a draft paragraph you already wrote (or write a quick one). First revise it for content — add a detail, cut something unclear. Then edit it for spelling, grammar, and punctuation.","checklist":["Revised for content (added or cut something)","Edited for spelling and grammar","Read the paragraph aloud at least once","Compared the final version to the original"]}}'::jsonb
where type = 'class_topic' and key = 'Writing' and meta->>'topic_key' = 'revisingEditing';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Sharing the Final Piece","body":"Publishing is the last step of the writing process — presenting a polished, error-free piece to its intended audience, whether that''s reading it aloud, posting it online, printing it, or turning it in."},{"heading":"Formatting for the Audience","body":"Publishing often includes formatting choices — adding a title, neat handwriting or typed text, illustrations, or a proper layout — that make the piece look finished and considerate of the reader."}],"practice":[{"question":"Publishing happens...","options":["Before planning","As the last step, after revising and editing","Instead of drafting","Before the topic is chosen"],"answerIndex":1,"explanation":"Publishing is the final stage, coming after the piece has been revised and edited."},{"question":"A piece that is ready to publish should be...","options":["A rough first draft with mistakes","Polished, edited, and formatted for the audience","Unfinished","Missing a title"],"answerIndex":1,"explanation":"Published work should be in its most polished, finished form."}],"apply":{"prompt":"Take a piece of writing you have revised and edited. Prepare it for publishing: give it a title, format it neatly (typed or handwritten clearly), and share it with a family member or friend.","checklist":["Gave the piece a title","Formatted it neatly","Made sure it was fully revised and edited","Shared it with a real audience"]}}'::jsonb
where type = 'class_topic' and key = 'Writing' and meta->>'topic_key' = 'publishing';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Evaluating Credibility","body":"Reliable sources are current, written by qualified authors or reputable organizations, and can be fact-checked against other sources. Watch for bias, outdated information, and sites without a clear author or publisher."},{"heading":"Primary vs. Secondary Sources","body":"A primary source is firsthand evidence — an original document, interview, or dataset — while a secondary source analyzes or interprets primary sources, like a textbook or news article summarizing research."}],"practice":[{"question":"Which is a red flag that a website might be an unreliable source?","options":["It cites its data","It has a clear publish date and author","It has no author, date, or way to verify claims","It is published by a university"],"answerIndex":2,"explanation":"Missing authorship, dates, and verifiability are strong signs a source may be unreliable."},{"question":"An original interview transcript used as research evidence is an example of a...","options":["Secondary source","Primary source","Unreliable source","Citation"],"answerIndex":1,"explanation":"A primary source is firsthand, original material, like an interview transcript."}],"apply":{"prompt":"Pick a research topic. Find two potential sources online and evaluate each for credibility — check the author, publish date, and whether claims can be verified elsewhere. Decide which is more reliable and explain why.","checklist":["Found two potential sources","Checked author and publish date for each","Checked whether claims are verifiable","Explained which source is more reliable and why"]}}'::jsonb
where type = 'class_topic' and key = 'Writing' and meta->>'topic_key' = 'gatheringSources';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Taking Notes in Your Own Words","body":"Good research notes paraphrase key information in your own words rather than copying full sentences — this helps you understand the material and avoids accidentally plagiarizing later."},{"heading":"Organizing by Topic","body":"Sorting notes into categories or subtopics — using headings, color-coding, or note cards — makes it much easier to find information again and see how ideas from different sources connect."}],"practice":[{"question":"Why should research notes usually be written in your own words instead of copied exactly?","options":["It takes less time","It helps you understand and avoids plagiarism","Copying is required","It makes notes longer"],"answerIndex":1,"explanation":"Paraphrasing builds understanding and prevents accidental plagiarism."},{"question":"Sorting notes into categories by subtopic mainly helps you...","options":["Forget the source","Find and connect information more easily later","Make the notes longer","Avoid needing an outline"],"answerIndex":1,"explanation":"Organized notes are easier to retrieve and connect when drafting."}],"apply":{"prompt":"Research a topic using two sources. Take notes in your own words, sorted into at least two categories or subtopics, and record where each note came from.","checklist":["Used two sources","Paraphrased notes in your own words","Sorted notes into categories","Recorded the source for each note"]}}'::jsonb
where type = 'class_topic' and key = 'Writing' and meta->>'topic_key' = 'noteTakingOrganizing';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Why We Cite","body":"Citing evidence gives credit to the original source of information or ideas, allows readers to verify claims, and helps you avoid plagiarism — presenting someone else''s words or ideas as your own."},{"heading":"In-Text Citations","body":"An in-text citation, like an APA citation (Author, Year), appears right where you use a source''s information in your writing, and connects to a full reference listed at the end of your paper."}],"practice":[{"question":"The main reason writers cite their sources is to...","options":["Make the paper longer","Give credit and let readers verify claims","Confuse the reader","Avoid writing an introduction"],"answerIndex":1,"explanation":"Citations credit original authors and allow readers to check claims."},{"question":"In APA style, an in-text citation typically includes the...","options":["Author''s name and the year","Full title only","Page count","The reader''s name"],"answerIndex":0,"explanation":"APA in-text citations typically use (Author, Year) format."}],"apply":{"prompt":"Find a short fact or quote from a reliable source. Write a sentence using that evidence in your own paragraph, with a properly formatted in-text citation, and create the matching reference list entry.","checklist":["Used evidence from a real source","Included a correct in-text citation","Created a matching reference list entry","Did not copy the source word-for-word without quotation marks"]}}'::jsonb
where type = 'class_topic' and key = 'Writing' and meta->>'topic_key' = 'citingEvidence';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Forming Letters Correctly","body":"Handwriting means forming each letter with consistent shape and size, starting and ending strokes in the right place — practicing this helps your writing become neat and easy for others to read."},{"heading":"Learning to Type","body":"Keyboarding means learning where letters are on a keyboard and using the correct fingers for each key, which helps you type faster and more accurately as you write more on computers."}],"practice":[{"question":"When holding a pencil to write, your grip should be...","options":["Very tight, with a fist","Relaxed, usually with three fingers","Not holding it at all","Held in your mouth"],"answerIndex":1,"explanation":"A relaxed, three-finger (tripod) grip helps with control and reduces hand fatigue."},{"question":"Learning where letters are on a keyboard and using the right fingers to press them is called...","options":["Handwriting","Keyboarding","Drafting","Editing"],"answerIndex":1,"explanation":"Keyboarding is the skill of typing accurately and efficiently using proper finger placement."}],"apply":{"prompt":"Practice writing your full name and the alphabet neatly on paper. Then, if you have access to a keyboard, practice typing the same words, trying to use the correct fingers for each key.","checklist":["Wrote your name neatly","Wrote the alphabet in order","Practiced typing the same words (if keyboard available)","Checked letters are consistent in size and shape"]}}'::jsonb
where type = 'class_topic' and key = 'Writing' and meta->>'topic_key' = 'handwritingKeyboarding';

-- ── Enrich remaining Language Arts topics: Speaking/Language/Media (17) ─

update public.app_content
set meta = meta || '{"learn":[{"heading":"What Is Active Listening?","body":"Active listening means using your ears, eyes, and body to show someone you are paying attention to what they say. You look at the speaker, stay quiet while they talk, and think about their words instead of planning what to say next."},{"heading":"Showing You''re Listening","body":"You can show you are listening by nodding your head, keeping your body still, and asking a question about what the person said. Good listeners repeat back the main idea to make sure they understood correctly."}],"practice":[{"question":"What should you do with your eyes when someone is talking to you?","options":["Look at the speaker","Look at your shoes","Look out the window","Close them"],"answerIndex":0,"explanation":"Looking at the speaker shows you are paying attention and helps you catch their words."},{"question":"Which of these is an active listening behavior?","options":["Interrupting to talk about yourself","Nodding and asking a question","Playing with a toy","Walking away"],"answerIndex":1,"explanation":"Nodding and asking a question shows you heard and understood the speaker."}],"apply":{"prompt":"Play a ''Listen and Repeat'' game with a partner: one person tells a short story about their day, and the listener repeats back three details they heard.","checklist":["Sit facing your partner and make eye contact","Let your partner finish without interrupting","Repeat back 3 things you remember hearing","Ask your partner one question about their story"]}}'::jsonb
where type = 'class_topic' and key = 'SpeakingAndListening' and meta->>'topic_key' = 'activeListening';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Joining a Group Discussion","body":"Participating in a discussion means sharing your own ideas while also listening to what classmates say. Good discussion partners wait for a turn to speak, stay on topic, and connect their comment to something someone else just said."},{"heading":"Building on Others'' Ideas","body":"Instead of just stating a new idea, strong discussion participants say things like ''I agree with what you said, and I also think...'' This shows you were listening and helps the group build a deeper understanding together."}],"practice":[{"question":"What is a good way to add to a discussion after someone else speaks?","options":["Say the exact same thing again","Build on their idea by adding something new","Ignore what they said and change the subject","Talk over them"],"answerIndex":1,"explanation":"Building on an idea shows you listened and moves the group''s thinking forward."},{"question":"Why is it important to wait your turn in a group discussion?","options":["So everyone gets a chance to share ideas","Because talking is not allowed","So the teacher can leave the room","Because it makes the discussion shorter"],"answerIndex":0,"explanation":"Waiting your turn makes sure everyone''s ideas are heard and respected."}],"apply":{"prompt":"Hold a 4-person discussion circle about a class book or topic where each person must connect their comment to the previous speaker.","checklist":["Everyone shares at least one idea","Each comment starts with ''I agree/disagree because...'' or ''Building on that...''","No one interrupts while another person is talking","The group summarizes one thing they learned from each other"]}}'::jsonb
where type = 'class_topic' and key = 'SpeakingAndListening' and meta->>'topic_key' = 'participatingDiscussions';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Asking Good Questions","body":"A good question starts with a question word like who, what, where, when, why, or how, and it asks for information you don''t already know. Asking questions helps you understand a story or lesson better."},{"heading":"Giving Clear Answers","body":"When you answer a question, try to answer in a full sentence and stay on topic. For example, if someone asks ''What is your favorite animal?'' a clear answer is ''My favorite animal is a dog'' instead of just ''Dog.''"}],"practice":[{"question":"Which word usually starts a question?","options":["Because","What","And","The"],"answerIndex":1,"explanation":"Question words like what, who, where, when, why, and how are used to start questions."},{"question":"Which is the clearest answer to ''What did you eat for breakfast?''","options":["Cereal.","I ate cereal for breakfast.","Yes.","Maybe."],"answerIndex":1,"explanation":"A full sentence answer clearly tells the listener exactly what was eaten."}],"apply":{"prompt":"Play a question-and-answer interview game where you ask a family member 5 questions about their favorite things and write down their answers in full sentences.","checklist":["Write 5 questions using different question words","Ask each question out loud and listen carefully","Write down each answer in a complete sentence","Share one interesting answer with the class"]}}'::jsonb
where type = 'class_topic' and key = 'SpeakingAndListening' and meta->>'topic_key' = 'askingAnsweringQuestions';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Structuring a Presentation","body":"An effective oral presentation has a clear introduction that states your topic, a body that presents your main points with evidence or examples, and a conclusion that sums up your message. Organizing your ideas ahead of time keeps your audience following along."},{"heading":"Delivery Matters","body":"How you say something is as important as what you say. Speaking clearly, making eye contact, using a strong volume, and pacing yourself instead of rushing all help your audience understand and stay engaged with your message."}],"practice":[{"question":"What should the introduction of an oral presentation do?","options":["List every source you used","Introduce the topic and grab attention","Restate the conclusion","Ask the audience to leave"],"answerIndex":1,"explanation":"An introduction should clearly state the topic and hook the audience''s interest."},{"question":"Which delivery habit most improves an oral presentation?","options":["Reading silently from note cards","Speaking in a monotone voice","Making eye contact and speaking clearly","Facing away from the audience"],"answerIndex":2,"explanation":"Eye contact and clear speech help the audience stay engaged and understand the message."}],"apply":{"prompt":"Prepare and deliver a 2-minute oral presentation on a topic you know well, using notecards with only key points (not full sentences).","checklist":["Write an intro, 2-3 main points, and a conclusion","Practice out loud at least twice before presenting","Use eye contact and a clear, audible voice","Time yourself to stay close to 2 minutes"]}}'::jsonb
where type = 'class_topic' and key = 'SpeakingAndListening' and meta->>'topic_key' = 'oralPresentations';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Bringing Stories to Life","body":"Storytelling and dramatic reading use your voice and body to make a story more exciting for listeners. Changing your voice for different characters, pausing at exciting moments, and using facial expressions all help bring a story to life."},{"heading":"Voice and Gesture Choices","body":"Skilled storytellers change their pace and volume to match the mood of a scene—speaking slowly and quietly for a sad moment, or fast and loud for an exciting chase. Gestures and expressions add extra meaning without needing more words."}],"practice":[{"question":"What can a storyteller change to show a character is scared?","options":["The color of the book","Their tone of voice and pace","The title of the story","Nothing, voice never changes"],"answerIndex":1,"explanation":"Changing tone and pace helps show a character''s emotion, like fear."},{"question":"Why do dramatic readers use gestures?","options":["To confuse the audience","To add meaning and expression without extra words","To end the story early","Because it is required by law"],"answerIndex":1,"explanation":"Gestures add expression and help convey meaning beyond the words alone."}],"apply":{"prompt":"Choose a short passage from a favorite book and perform a 1-minute dramatic reading using different voices for at least two characters.","checklist":["Pick a passage with dialogue between two or more characters","Practice a distinct voice for each character","Use pauses and volume changes to build excitement","Perform it for a family member or classmate"]}}'::jsonb
where type = 'class_topic' and key = 'SpeakingAndListening' and meta->>'topic_key' = 'storytellingDramaticReadings';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Choosing the Right Visual Aid","body":"Multimedia and visual aids—slides, charts, images, or audio clips—should support your spoken message, not replace it. Each visual should be simple, readable from a distance, and directly tied to the point you are currently making."},{"heading":"Avoiding Common Pitfalls","body":"A common mistake is cramming too much text onto a slide or reading directly from it, which disengages the audience. Effective presenters use visuals as a backdrop—brief labels, a compelling image, or a simple graph—while the speaker delivers the explanation."}],"practice":[{"question":"What is the main purpose of a visual aid in a presentation?","options":["To replace the need for speaking","To support and clarify the spoken message","To fill time","To distract the audience"],"answerIndex":1,"explanation":"Visual aids should reinforce and clarify what the speaker is saying, not replace it."},{"question":"Which slide design mistake most commonly disengages an audience?","options":["Using one clear image per slide","Cramming dense paragraphs of text onto a slide","Using a large, readable font","Including a simple, relevant chart"],"answerIndex":1,"explanation":"Dense text forces the audience to read instead of listen, disengaging them from the speaker."}],"apply":{"prompt":"Design a 5-slide visual aid deck for a presentation on a topic of your choice, using no more than 8 words of text per slide.","checklist":["Each slide supports one main point of your talk","No slide has more than 8 words of text","At least one slide uses an image, chart, or diagram","Present it aloud without reading directly from the slides"]}}'::jsonb
where type = 'class_topic' and key = 'SpeakingAndListening' and meta->>'topic_key' = 'multimediaVisualAids';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Parts of a Sentence","body":"Grammar and syntax are the rules for how words fit together to make sentences that make sense. Every complete sentence needs a subject (who or what it''s about) and a predicate (what the subject does or is)."},{"heading":"Word Order Matters","body":"In English, changing the order of words in a sentence can change its meaning. For example, ''The dog chased the cat'' means something different from ''The cat chased the dog,'' even though both sentences use the exact same words."}],"practice":[{"question":"What two parts does a complete sentence need?","options":["A noun and an adjective","A subject and a predicate","A question and an answer","A comma and a period"],"answerIndex":1,"explanation":"A complete sentence needs a subject and a predicate to express a full thought."},{"question":"Which sentence is grammatically complete?","options":["Running to the store quickly.","The boy ran to the store.","Because it was raining outside.","Under the big oak tree."],"answerIndex":1,"explanation":"''The boy ran to the store'' has both a subject (the boy) and a predicate (ran to the store)."}],"apply":{"prompt":"Write 5 sentences about your weekend, then underline the subject once and the predicate twice in each sentence.","checklist":["Write 5 complete sentences","Underline the subject of each sentence once","Underline the predicate of each sentence twice","Check that each sentence expresses a full thought"]}}'::jsonb
where type = 'class_topic' and key = 'Language' and meta->>'topic_key' = 'grammarSyntax';

update public.app_content
set meta = meta || '{"learn":[{"heading":"End Marks","body":"Every sentence needs an end mark to show the reader it is finished. A period (.) ends a telling sentence, a question mark (?) ends an asking sentence, and an exclamation point (!) ends an excited sentence."},{"heading":"Capital Letters","body":"Capitalization rules tell us when to use a big letter. We capitalize the first word of every sentence, the word ''I,'' and names of people and places, so readers know these are important."}],"practice":[{"question":"Which punctuation mark ends a question?","options":["Period (.)","Question mark (?)","Comma (,)","Exclamation point (!)"],"answerIndex":1,"explanation":"A question mark shows the sentence is asking something."},{"question":"Which word should always be capitalized no matter where it appears in a sentence?","options":["the","and","I","dog"],"answerIndex":2,"explanation":"The word ''I'' is always capitalized in English, even in the middle of a sentence."}],"apply":{"prompt":"Write 4 short sentences about your favorite game: one telling, one asking, one excited, and one with your name in it, using correct end marks and capital letters.","checklist":["One sentence ends with a period","One sentence ends with a question mark","One sentence ends with an exclamation point","Your name and the first word of each sentence are capitalized"]}}'::jsonb
where type = 'class_topic' and key = 'Language' and meta->>'topic_key' = 'punctuationMechanics';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Sound It Out","body":"Spelling means putting letters in the right order to write a word correctly. One way to spell a word you don''t know is to say it slowly and listen for each sound, then write the letter that matches each sound."},{"heading":"Word Patterns","body":"Many words follow patterns, like words that end in ''ake'' (cake, make, lake) or start with ''sh'' (ship, shop, shell). Learning these patterns helps you spell new words that sound similar to ones you already know."}],"practice":[{"question":"What is a good strategy for spelling an unfamiliar word?","options":["Guess without thinking","Say it slowly and listen for each sound","Skip the word entirely","Write a different word instead"],"answerIndex":1,"explanation":"Sounding out a word slowly helps you identify each letter sound to spell it."},{"question":"Which word follows the same ''ake'' pattern as ''cake''?","options":["dog","lake","sun","cup"],"answerIndex":1,"explanation":"''Lake'' ends in the same ''ake'' pattern as ''cake.''"}],"apply":{"prompt":"Make a list of 5 words that all share the same spelling pattern (like ''at,'' ''ake,'' or ''sh''), and practice writing each one 3 times.","checklist":["Choose one spelling pattern to focus on","List 5 words that use that pattern","Write each word 3 times correctly","Ask someone to quiz you on the words"]}}'::jsonb
where type = 'class_topic' and key = 'Language' and meta->>'topic_key' = 'spelling';

update public.app_content
set meta = meta || '{"learn":[{"heading":"What Is Register?","body":"Register refers to the level of formality a writer or speaker chooses based on audience and purpose—for example, a text message to a friend uses casual language, while a college application essay requires formal, precise language."},{"heading":"Matching Style to Purpose","body":"Skilled writers adjust word choice, sentence length, and tone to fit the situation. Using slang in a job application or overly formal language in a casual conversation both create a mismatch that can confuse or alienate the audience."}],"practice":[{"question":"Which situation calls for a formal register?","options":["Texting a close friend","Writing a cover letter for a job","Posting a casual comment online","Chatting with a sibling"],"answerIndex":1,"explanation":"A cover letter is a professional document requiring formal language and tone."},{"question":"What does ''register'' mean in the context of language?","options":["The pitch of your voice","The level of formality used for a given audience and purpose","The number of words in a sentence","A type of punctuation mark"],"answerIndex":1,"explanation":"Register describes how formal or informal language is, adjusted for audience and purpose."}],"apply":{"prompt":"Write the same short message (e.g., asking for an extension on an assignment) in two versions: one casual text to a friend, and one formal email to a teacher.","checklist":["Write a casual version using informal language and contractions","Write a formal version using complete sentences and polite phrasing","Identify at least 3 specific word or phrase differences between the two","Explain why each version fits its audience"]}}'::jsonb
where type = 'class_topic' and key = 'Language' and meta->>'topic_key' = 'registersStyleChoices';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Types of Sentences","body":"Sentence variety means mixing simple sentences (one independent clause), compound sentences (two independent clauses joined by a conjunction), and complex sentences (an independent clause plus a dependent clause) to keep writing interesting."},{"heading":"Why Variety Matters","body":"Using only short, simple sentences can make writing feel choppy, while relying only on long sentences can confuse readers. Mixing sentence lengths and structures creates rhythm and helps emphasize your most important ideas."}],"practice":[{"question":"What is a compound sentence?","options":["A single independent clause","Two independent clauses joined by a conjunction","A sentence with no verb","A question with two parts"],"answerIndex":1,"explanation":"A compound sentence joins two independent clauses, often with a conjunction like ''and'' or ''but.''"},{"question":"Why should writers use a mix of sentence types?","options":["To make the essay longer","To create rhythm and avoid choppy or confusing writing","Because teachers require exactly 3 types","To use every punctuation mark at least once"],"answerIndex":1,"explanation":"Varying sentence types creates rhythm and keeps readers engaged."}],"apply":{"prompt":"Take a paragraph you''ve written that uses only simple sentences and revise it to include at least one compound and one complex sentence.","checklist":["Identify all simple sentences in your paragraph","Combine two related simple sentences into a compound sentence","Turn one simple sentence into a complex sentence using a dependent clause","Read the revised paragraph aloud to check its flow"]}}'::jsonb
where type = 'class_topic' and key = 'Language' and meta->>'topic_key' = 'sentenceVariety';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Synonyms and Antonyms","body":"Synonyms are words that have the same or nearly the same meaning, like ''happy'' and ''joyful.'' Antonyms are words with opposite meanings, like ''hot'' and ''cold.'' Knowing both helps you choose more precise words in your writing."},{"heading":"Why Word Choice Matters","body":"Using synonyms lets you avoid repeating the same word too often and can add more specific shades of meaning—for example, ''sprint'' is more specific than just ''run.'' Understanding antonyms also helps you describe contrasts clearly."}],"practice":[{"question":"Which word is a synonym for ''happy''?","options":["Sad","Joyful","Angry","Tired"],"answerIndex":1,"explanation":"''Joyful'' means nearly the same thing as ''happy,'' making it a synonym."},{"question":"Which word is an antonym for ''hot''?","options":["Warm","Cold","Sunny","Bright"],"answerIndex":1,"explanation":"''Cold'' means the opposite of ''hot,'' making it an antonym."}],"apply":{"prompt":"Pick 5 overused words from your own writing (like ''good,'' ''said,'' ''nice'') and create a synonym list of 3 alternatives for each.","checklist":["List 5 words you use too often","Find 3 synonyms for each word using a thesaurus","Rewrite one sentence for each word using a stronger synonym","Share your favorite improved sentence with a classmate"]}}'::jsonb
where type = 'class_topic' and key = 'Language' and meta->>'topic_key' = 'wordRelationships';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Denotation vs. Connotation","body":"Nuance in word meaning involves understanding both denotation (a word''s dictionary definition) and connotation (the feelings or associations a word carries). For example, ''thrifty'' and ''stingy'' both mean careful with money, but ''thrifty'' feels positive while ''stingy'' feels negative."},{"heading":"Precision in Word Choice","body":"Skilled writers select the word that most precisely captures their intended meaning and tone, rather than settling for the first synonym that comes to mind. Choosing between ''assertive,'' ''aggressive,'' and ''confident'' can completely change how a reader perceives a character."}],"practice":[{"question":"What is ''connotation''?","options":["A word''s dictionary definition","The feeling or association a word carries beyond its literal meaning","A type of punctuation","The number of syllables in a word"],"answerIndex":1,"explanation":"Connotation refers to the emotional or cultural associations attached to a word."},{"question":"Which pair of words best illustrates a nuance in meaning despite similar denotation?","options":["Cat and dog","Thrifty and stingy","Blue and red","Run and jump"],"answerIndex":1,"explanation":"''Thrifty'' and ''stingy'' both describe careful spending but carry very different connotations."}],"apply":{"prompt":"Choose 3 pairs of near-synonyms (e.g., ''confident/arrogant,'' ''curious/nosy'') and write a sentence with each word showing how the connotation changes the meaning.","checklist":["Choose 3 pairs of near-synonym words with different connotations","Write one sentence using each word (6 sentences total)","Explain in one sentence how the connotation changes the tone","Identify whether each word is positive, negative, or neutral"]}}'::jsonb
where type = 'class_topic' and key = 'Language' and meta->>'topic_key' = 'nuancesWordMeaning';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Why Was This Made?","body":"Every media message—an ad, article, or video—was created for a purpose, such as to inform, persuade, entertain, or sell something. Identifying the purpose helps you understand why certain information was included and other information left out."},{"heading":"Spotting Bias","body":"Bias is a slant or leaning toward one side of an issue, often shown through loaded language, one-sided facts, or an unbalanced selection of sources. Recognizing bias doesn''t mean a source is useless—it means you should look for other perspectives too."}],"practice":[{"question":"What is the purpose of most advertisements?","options":["To provide unbiased news","To persuade you to buy something","To entertain with no other goal","To teach history"],"answerIndex":1,"explanation":"Advertisements are created primarily to persuade viewers to purchase a product or service."},{"question":"Which is a sign that a media message might be biased?","options":["It presents multiple perspectives equally","It uses loaded, emotional language for one side only","It cites its sources clearly","It includes statistics from research studies"],"answerIndex":1,"explanation":"Using emotional or loaded language for only one side is a common sign of bias."}],"apply":{"prompt":"Find two news articles about the same event from different sources and compare their word choices and what facts each one emphasizes or leaves out.","checklist":["Choose two articles covering the same event","Identify the likely purpose of each article","List at least 3 examples of loaded or emotional language, if present","Write a sentence describing which facts each source emphasized or omitted"]}}'::jsonb
where type = 'class_topic' and key = 'MediaDigitalLiteracy' and meta->>'topic_key' = 'identifyingPurposeBias';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Checking Credibility","body":"Evaluating a source means checking whether it''s trustworthy before believing or sharing it. Ask who wrote it, what their expertise is, when it was published, and whether other reliable sources report the same information."},{"heading":"Red Flags to Watch For","body":"Warning signs of an unreliable source include no listed author, no publication date, extreme or emotional claims, and a lack of links or citations to evidence. Reliable sources are usually transparent about where their information comes from."}],"practice":[{"question":"Which question helps you evaluate whether a source is credible?","options":["Is the website''s font size large?","Who wrote it and what is their expertise?","Is the article long?","Does it have colorful pictures?"],"answerIndex":1,"explanation":"Checking the author''s identity and expertise is a key step in evaluating credibility."},{"question":"Which is a red flag that a source might be unreliable?","options":["It cites named research studies","It has a clear author and publish date","It makes extreme claims with no evidence","It is written by a known expert"],"answerIndex":2,"explanation":"Extreme claims without supporting evidence are a common warning sign of unreliable sources."}],"apply":{"prompt":"Pick a website or article you found online and evaluate its credibility using at least 4 criteria (author, date, evidence, purpose).","checklist":["Identify the author and their credentials, if listed","Check the publication or last-updated date","Note whether claims are backed by evidence or sources","Decide and explain whether you would trust this source"]}}'::jsonb
where type = 'class_topic' and key = 'MediaDigitalLiteracy' and meta->>'topic_key' = 'evaluatingSources';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Combining Media Elements","body":"Integrating multimedia means purposefully combining text, images, audio, and video so each element adds something the others can''t. For example, a chart might show data a paragraph can''t easily convey, while narration adds emotional tone that plain text lacks."},{"heading":"Avoiding Media Overload","body":"Effective multimedia integration is intentional, not just decorative—every image, clip, or graphic should serve the message. Cluttering a project with unrelated media can distract the audience and weaken the overall impact."}],"practice":[{"question":"What is the main goal of integrating multiple media types in a project?","options":["To make the project as long as possible","To have each element add something unique to the message","To use every media type available regardless of fit","To avoid using any text at all"],"answerIndex":1,"explanation":"Good multimedia integration is purposeful—each element should contribute something the others cannot."},{"question":"What is a risk of adding too much unrelated media to a project?","options":["It always makes the project more persuasive","It can distract from the message and weaken impact","It automatically improves credibility","It has no effect on the audience"],"answerIndex":1,"explanation":"Unrelated or excessive media can distract the audience and dilute the overall message."}],"apply":{"prompt":"Create a short multimedia project (a slide, webpage mockup, or video storyboard) on a topic of your choice that combines text, at least one image, and either audio or video.","checklist":["Include text that explains your main point","Include at least one image or graphic that adds information","Include an audio or video element that adds tone or explanation not covered by the text","Explain in one sentence why you chose each media element"]}}'::jsonb
where type = 'class_topic' and key = 'MediaDigitalLiteracy' and meta->>'topic_key' = 'integratingMedia';

update public.app_content
set meta = meta || '{"learn":[{"heading":"What Is Digital Storytelling?","body":"Digital storytelling combines traditional narrative elements—character, setting, conflict—with digital tools like images, video, music, and voice narration to share a story in a new format, such as a short video or interactive slideshow."},{"heading":"Planning Before Creating","body":"Successful digital stories usually start with a storyboard—a plan that maps out each scene, what will be shown, and what will be said or heard before any recording or editing begins. Planning ahead saves time and keeps the story focused."}],"practice":[{"question":"What is a storyboard used for in digital storytelling?","options":["To publish the final story online","To plan out scenes before creating the digital story","To edit video after it''s filmed","To choose background music only"],"answerIndex":1,"explanation":"A storyboard maps out each scene in advance, helping creators plan before producing their story."},{"question":"Which combination best describes digital storytelling?","options":["Only spoken narration with no visuals","Traditional story elements combined with digital tools like images and audio","A story written only on paper","A story with no plot or characters"],"answerIndex":1,"explanation":"Digital storytelling blends narrative elements like character and plot with digital media tools."}],"apply":{"prompt":"Create a storyboard for a 1-minute digital story (personal narrative or fictional) that plans out at least 4 scenes with images, text, and narration ideas.","checklist":["Sketch or describe at least 4 scenes in order","Note what image or visual goes with each scene","Write a short line of narration or text for each scene","Share your storyboard plan with a partner for feedback"]}}'::jsonb
where type = 'class_topic' and key = 'MediaDigitalLiteracy' and meta->>'topic_key' = 'digitalStorytelling';

-- ── Enrich remaining Science topics (17) ─────────────────────────────────

update public.app_content
set meta = meta || '{"learn":[{"heading":"Our Sun and Planets","body":"The Sun is a giant ball of hot, glowing gas at the center of our solar system. Eight planets, including Earth, travel around the Sun in big circles called orbits. The Sun gives us light and heat, and without it nothing on Earth could live."},{"heading":"Our Moon","body":"The Moon travels around the Earth, not the Sun. It does not make its own light — we see it glow because it reflects sunlight, like a mirror. The Moon changes shape in the sky over about a month; that is called its phases."}],"practice":[{"question":"What is at the center of our solar system?","options":["The Moon","The Sun","Earth","A star cluster"],"answerIndex":1,"explanation":"The Sun sits at the center, and the planets orbit around it."},{"question":"Why does the Moon appear to glow at night?","options":["It makes its own light","It reflects sunlight","It is on fire","It is made of light"],"answerIndex":1,"explanation":"The Moon has no light of its own — we see sunlight bouncing off it."}],"apply":{"prompt":"Watch the Moon every night for a week (or look at photos online) and draw what shape it is each night.","checklist":["Drew or noted the Moon shape for at least 5 nights","Circled the night it looked most \"full\"","Circled the night it looked most \"thin\" or hidden"]}}'::jsonb
where type = 'class_topic' and key = 'AstronomyAndSpace' and meta->>'topic_key' = 'solarSystem';

update public.app_content
set meta = meta || '{"learn":[{"heading":"What Is a Galaxy?","body":"A galaxy is a huge collection of stars, gas, dust, and planets all held together by gravity. Our solar system is just one tiny part of the Milky Way galaxy, which contains hundreds of billions of stars arranged in a spinning, spiral shape."},{"heading":"Stars Are Suns","body":"Every star you see at night is a giant ball of burning gas, just like our Sun — they only look small and dim because they are unimaginably far away. Stars come in different sizes, colors, and temperatures, and some are much bigger and hotter than our own Sun."}],"practice":[{"question":"What galaxy is our solar system located in?","options":["Andromeda","The Milky Way","The Sombrero Galaxy","The Orion Nebula"],"answerIndex":1,"explanation":"Our solar system is one small part of the spiral-shaped Milky Way galaxy."},{"question":"Why do stars look tiny in the night sky even though many are bigger than the Sun?","options":["They are actually small","They are extremely far away","They are dying out","They are made of ice"],"answerIndex":1,"explanation":"Stars are so far from Earth that their enormous size appears as a tiny point of light."}],"apply":{"prompt":"On a clear night, go outside (or use a stargazing app) and try to spot a patch of sky that looks hazy or \"milky\" — that band is part of our own Milky Way galaxy viewed from inside it.","checklist":["Found a dark viewing spot away from bright lights","Located or identified the Milky Way band or a star app equivalent","Counted how many individual stars you could see with just your eyes"]}}'::jsonb
where type = 'class_topic' and key = 'AstronomyAndSpace' and meta->>'topic_key' = 'starsGalaxies';

update public.app_content
set meta = meta || '{"learn":[{"heading":"A Universe of Galaxies","body":"Beyond the Milky Way lie billions of other galaxies, each containing billions of stars of its own, spread across the observable universe. Galaxies come in different shapes — spiral, elliptical, and irregular — and are grouped into clusters held together by gravity."},{"heading":"How We Study Them","body":"Astronomers use telescopes that detect visible light, radio waves, and infrared radiation to study galaxies too far away to visit. Because light takes time to travel, looking at a distant galaxy means seeing it as it looked millions or billions of years ago."}],"practice":[{"question":"Which of these is NOT a common galaxy shape?","options":["Spiral","Elliptical","Irregular","Cubic"],"answerIndex":3,"explanation":"Galaxies are generally classified as spiral, elliptical, or irregular — not cubic."},{"question":"Why does looking at a distant galaxy show us the past?","options":["Telescopes are old technology","Light takes time to travel across space","Galaxies move backward in time","Old photos are used"],"answerIndex":1,"explanation":"Because light travels at a fixed speed, light from far away left its source long ago, so we see it as it was in the past."}],"apply":{"prompt":"Research one real galaxy other than the Milky Way (such as Andromeda) and create a short fact sheet about its shape, distance from Earth, and how it was discovered.","checklist":["Named the galaxy and its shape","Recorded its approximate distance from Earth in light-years","Noted the telescope or method used to study it"]}}'::jsonb
where type = 'class_topic' and key = 'AstronomyAndSpace' and meta->>'topic_key' = 'spaceExploration';

update public.app_content
set meta = meta || '{"learn":[{"heading":"What Is a Force?","body":"A force is simply a push or a pull. Every time you throw a ball, open a door, or kick a soccer ball, you are using a force to make something move, stop, or change direction."},{"heading":"Bigger Push, Bigger Change","body":"A bigger force makes an object speed up, slow down, or change direction more. A gentle push rolls a toy car slowly, while a hard push sends it zooming — and friction, the rubbing between surfaces, is a force that slows moving things down."}],"practice":[{"question":"Which of these is an example of a force?","options":["A color","A push","A sound","A smell"],"answerIndex":1,"explanation":"A push (or a pull) is a force — it can start, stop, or change an object''s motion."},{"question":"What force slows down a rolling ball on the ground?","options":["Gravity","Friction","Magnetism","Light"],"answerIndex":1,"explanation":"Friction is the rubbing force between the ball and the ground that slows it down."}],"apply":{"prompt":"Roll a ball or toy car on three different surfaces (like carpet, wood floor, and grass) with the same push each time, and see which surface lets it roll the farthest.","checklist":["Tested on at least 3 different surfaces","Used about the same push each time","Recorded which surface let it roll farthest and guessed why"]}}'::jsonb
where type = 'class_topic' and key = 'Physics' and meta->>'topic_key' = 'forcesMotion';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Work and Energy","body":"In physics, \"work\" happens only when a force moves an object over a distance — pushing on a wall that doesn''t budge is not scientific work. Energy is the ability to do work, and it can change forms, like when the chemical energy in food becomes kinetic energy when you run."},{"heading":"Simple Machines","body":"Simple machines like levers, pulleys, wheels, and inclined planes don''t create new energy — they just change the size or direction of a force, making a task easier to do. A ramp, for example, lets you move something heavy upward using less force spread over a longer distance."}],"practice":[{"question":"In physics, when does \"work\" actually happen?","options":["Whenever you feel tired","When a force moves an object over a distance","Only when using a machine","When energy is destroyed"],"answerIndex":1,"explanation":"Scientific work requires a force to actually move an object across some distance."},{"question":"What do simple machines like ramps and levers actually do?","options":["Create new energy","Destroy energy","Change the size or direction of a force","Store electricity"],"answerIndex":2,"explanation":"Simple machines make tasks easier by changing how much force is needed or which direction it is applied, not by creating energy."}],"apply":{"prompt":"Build a simple ramp (a board propped on books) and compare how much easier it feels to slide a heavy book up the ramp versus lifting it straight up.","checklist":["Built a ramp at one incline","Tried lifting the object straight up and noted the effort","Tried sliding it up the ramp and compared the effort"]}}'::jsonb
where type = 'class_topic' and key = 'Physics' and meta->>'topic_key' = 'energyWorkMachines';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Simple Harmonic Motion","body":"Simple harmonic motion is a repeating back-and-forth movement, like a pendulum swinging or a spring bouncing, where the restoring force pulling the object back to center is proportional to how far it has moved. The time for one full swing, called the period, stays constant for a given pendulum length, regardless of how wide the swing is."},{"heading":"Heat and Thermodynamics","body":"Thermodynamics is the study of heat and energy transfer. Heat always flows from a hotter object to a colder one until they reach the same temperature, and the total energy in a closed system is always conserved — it just changes form, as described by the first law of thermodynamics."}],"practice":[{"question":"What determines the period of a simple pendulum?","options":["How wide it swings","Its length","Its color","How heavy the bob is"],"answerIndex":1,"explanation":"A pendulum''s period depends mainly on its length (and gravity), not its swing width or mass."},{"question":"According to thermodynamics, which direction does heat naturally flow?","options":["Cold to hot","Hot to cold","It never moves","Randomly"],"answerIndex":1,"explanation":"Heat spontaneously flows from a hotter object to a colder one until thermal equilibrium is reached."}],"apply":{"prompt":"Build a simple pendulum with string and a small weight, then test how changing the string length affects the time for 10 full swings.","checklist":["Timed 10 swings at one string length","Changed the length and timed 10 swings again","Compared results and explained the relationship between length and period"]}}'::jsonb
where type = 'class_topic' and key = 'Physics' and meta->>'topic_key' = 'motionThermodynamics';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Weather vs. Climate","body":"Weather is what is happening outside right now, like rain, sun, or snow today. Climate is the usual pattern of weather in a place over many years, like how a desert is usually hot and dry while the North Pole is usually cold and icy."},{"heading":"Extreme Weather","body":"Sometimes weather gets very big and powerful, like thunderstorms, hurricanes, blizzards, and tornadoes. These extreme events can be dangerous, which is why scientists watch the sky closely and warn people ahead of time so they can stay safe."}],"practice":[{"question":"Which one describes climate rather than weather?","options":["It is raining right now","Deserts are usually hot and dry","It is snowing today","There is a rainbow outside"],"answerIndex":1,"explanation":"Climate describes the usual, long-term pattern of weather in a place, not what is happening in one moment."},{"question":"Why do scientists track extreme weather like hurricanes?","options":["For fun","To warn people and help keep them safe","To make it rain","To change the climate"],"answerIndex":1,"explanation":"Tracking extreme weather lets scientists warn people in advance so they can prepare and stay safe."}],"apply":{"prompt":"Keep a simple weather journal for 5 days: write or draw whether it was sunny, rainy, cloudy, or windy each day.","checklist":["Recorded weather for at least 5 days","Noted the warmest and coldest day","Guessed whether the week matched what you''d expect for your climate"]}}'::jsonb
where type = 'class_topic' and key = 'EarthAndEnvironmental' and meta->>'topic_key' = 'weatherClimate';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Three Kinds of Rock","body":"Igneous rock forms when hot melted rock cools and hardens, sedimentary rock forms when layers of sand, mud, and shells press together over time, and metamorphic rock forms when heat and pressure change an existing rock into something new. Rocks are always slowly changing between these types over long stretches of time."},{"heading":"From Rock to Soil","body":"Weathering is the process of wind, water, ice, and plant roots slowly breaking big rocks into smaller and smaller pieces. Over a very long time, this broken-down rock mixes with dead plant and animal material to become soil, the loose ground that plants grow in."}],"practice":[{"question":"How does sedimentary rock typically form?","options":["Melted rock cooling quickly","Layers of sediment pressing together over time","Sudden heat and pressure","Volcanic eruptions"],"answerIndex":1,"explanation":"Sedimentary rock builds up as layers of sand, mud, and other material get pressed together over long periods."},{"question":"What is weathering?","options":["Rock forming underground","Wind, water, and ice breaking rock down","Rock melting into lava","Soil turning into rock"],"answerIndex":1,"explanation":"Weathering is the gradual breakdown of rock by forces like wind, water, ice, and plant roots."}],"apply":{"prompt":"Collect 3 different rocks or pebbles from outside and examine them with a magnifying glass, noting their color, texture, and any visible layers or crystals.","checklist":["Collected at least 3 different rocks","Described the texture and color of each","Guessed which rock type (igneous, sedimentary, or metamorphic) each might be"]}}'::jsonb
where type = 'class_topic' and key = 'EarthAndEnvironmental' and meta->>'topic_key' = 'rocksSoil';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Four Main Layers","body":"Earth has four main layers: the thin, rocky crust we live on, the hot, slowly flowing mantle beneath it, the liquid metal outer core, and the solid metal inner core at the very center. Each layer gets hotter and denser the deeper you go."},{"heading":"Why It Matters","body":"The mantle''s slow-flowing rock drives the movement of the tectonic plates that make up Earth''s crust, which causes earthquakes, volcanoes, and mountain building over millions of years. The spinning liquid outer core also generates Earth''s magnetic field, which shields us from harmful solar radiation."}],"practice":[{"question":"Which layer of Earth do we live on top of?","options":["The mantle","The crust","The outer core","The inner core"],"answerIndex":1,"explanation":"The crust is the thin, rocky outermost layer where we live."},{"question":"What does the movement of Earth''s outer core help create?","options":["Ocean tides","Earth''s magnetic field","Weather patterns","The atmosphere"],"answerIndex":1,"explanation":"The spinning liquid metal outer core generates Earth''s protective magnetic field."}],"apply":{"prompt":"Make a model of Earth''s layers using a hard-boiled egg (or a drawing): the shell is the crust, the egg white is the mantle, and the yolk is the core.","checklist":["Identified or built a model with 3-4 distinct layers","Labeled each layer with its name","Noted which layer is thickest and which is hottest"]}}'::jsonb
where type = 'class_topic' and key = 'EarthAndEnvironmental' and meta->>'topic_key' = 'earthsLayers';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Three States of Matter","body":"A solid holds its own shape, like an ice cube or a rock. A liquid takes the shape of whatever container it is in but keeps the same amount of space, like water. A gas spreads out to fill any space it is in, like the air around us."},{"heading":"Changing State","body":"Adding heat can turn a solid into a liquid (melting) and a liquid into a gas (evaporating), while removing heat does the opposite (freezing and condensing). The matter itself stays the same stuff — only its state changes, like water freezing into ice and melting back again."}],"practice":[{"question":"What happens when you heat an ice cube until it becomes water?","options":["Freezing","Melting","Evaporating","Condensing"],"answerIndex":1,"explanation":"Melting is the change from a solid to a liquid caused by adding heat."},{"question":"Which state of matter spreads out to fill its whole container?","options":["Solid","Liquid","Gas","None of these"],"answerIndex":2,"explanation":"Gas particles spread apart to fill all the available space in a container."}],"apply":{"prompt":"Put an ice cube in a cup and watch it change state over an hour, checking on it every 15 minutes.","checklist":["Recorded what the ice looked like at the start","Checked and noted changes every 15 minutes","Described the state change(s) you observed by the end"]}}'::jsonb
where type = 'class_topic' and key = 'Chemistry' and meta->>'topic_key' = 'statesOfMatter';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Atoms and Elements","body":"An atom is the smallest unit of matter that still has the properties of an element. An element is a pure substance made of only one type of atom — like oxygen, gold, or hydrogen — and there are about 118 known elements, each listed on the periodic table."},{"heading":"Molecules Are Combinations","body":"When two or more atoms bond together, they form a molecule. Some molecules are made of one element, like O2 (two oxygen atoms), while others are compounds made of different elements bonded together, like H2O (water), which is two hydrogen atoms and one oxygen atom."}],"practice":[{"question":"What is an element?","options":["A mix of different atoms","A pure substance made of one type of atom","A type of molecule only","A liquid"],"answerIndex":1,"explanation":"An element is a pure substance made up of only one kind of atom."},{"question":"What does the formula H2O tell you?","options":["1 hydrogen atom and 2 oxygen atoms","2 hydrogen atoms and 1 oxygen atom","2 hydrogen molecules","Pure oxygen"],"answerIndex":1,"explanation":"H2O means each water molecule is made of two hydrogen atoms bonded to one oxygen atom."}],"apply":{"prompt":"Look at the ingredient list on 3 household items (like table salt, baking soda, and water) and research what elements make up each one.","checklist":["Listed 3 household substances","Identified the elements in each (e.g. salt = sodium + chlorine)","Noted whether each is an element or a compound"]}}'::jsonb
where type = 'class_topic' and key = 'Chemistry' and meta->>'topic_key' = 'atomsElements';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Organized by Atomic Number","body":"The periodic table arranges all known elements in order of atomic number — the number of protons in one atom of that element. Elements are grouped into rows (periods) and columns (groups), and elements in the same column share similar chemical properties because they have the same number of electrons in their outer shell."},{"heading":"Predicting Properties","body":"Because of its organization, the periodic table lets scientists predict how an element will behave before ever testing it — for example, elements in the leftmost column (alkali metals) are all highly reactive with water. Metals, nonmetals, and metalloids each occupy their own regions of the table."}],"practice":[{"question":"What determines an element''s position (atomic number) on the periodic table?","options":["Its color","The number of protons in its atoms","Its melting point","Its weight in grams"],"answerIndex":1,"explanation":"Atomic number is defined by the number of protons in an atom, and elements are arranged in order of this number."},{"question":"Why do elements in the same column of the periodic table behave similarly?","options":["They are the same size","They have similar outer electron arrangements","They are all metals","They were discovered together"],"answerIndex":1,"explanation":"Elements in the same group share a similar number of outer-shell electrons, which drives similar chemical behavior."}],"apply":{"prompt":"Pick 3 elements from different regions of the periodic table (a metal, a nonmetal, and a noble gas) and research one real-world use for each.","checklist":["Chose one metal, one nonmetal, and one noble gas","Found each element''s atomic number","Recorded one real-world use for each element"]}}'::jsonb
where type = 'class_topic' and key = 'Chemistry' and meta->>'topic_key' = 'periodicTable';

update public.app_content
set meta = meta || '{"learn":[{"heading":"The Cell: Life''s Basic Unit","body":"Every living thing is made of cells, the smallest units that can carry out the functions of life. A cell has a nucleus that controls its activities, a cell membrane that holds it together, and organelles like mitochondria that produce energy for the cell to use."},{"heading":"From Cells to Systems","body":"Similar cells group together to form tissues, tissues combine to form organs like the heart or lungs, and organs work together as organ systems, like the circulatory or respiratory system. This organization lets a complex body like yours carry out life functions no single cell could manage alone."}],"practice":[{"question":"What part of the cell controls its activities?","options":["The cell membrane","The nucleus","The mitochondria","The cytoplasm"],"answerIndex":1,"explanation":"The nucleus acts as the control center of the cell, directing its activities."},{"question":"What is the correct order of organization from smallest to largest?","options":["Organ, tissue, cell, system","Cell, tissue, organ, system","System, organ, tissue, cell","Tissue, cell, system, organ"],"answerIndex":1,"explanation":"Cells combine into tissues, tissues form organs, and organs work together as organ systems."}],"apply":{"prompt":"Pick one body system (like the digestive or circulatory system) and diagram its main organs, labeling the job each organ does.","checklist":["Chose one body system","Listed at least 3 organs in that system","Wrote one job for each organ"]}}'::jsonb
where type = 'class_topic' and key = 'Biology' and meta->>'topic_key' = 'cellsBodySystems';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Mitosis: Copying a Cell","body":"Mitosis is the process by which one cell divides into two identical daughter cells, each with a complete copy of the original DNA. It proceeds through distinct phases — prophase, metaphase, anaphase, and telophase — and is how your body grows, replaces worn-out cells, and heals wounds."},{"heading":"Cellular Respiration","body":"Cellular respiration is the process mitochondria use to convert glucose (sugar) and oxygen into usable energy (ATP), releasing carbon dioxide and water as byproducts. This is essentially the reverse of photosynthesis, and it happens continuously in nearly every cell in your body to power everything you do."}],"practice":[{"question":"What is the main purpose of mitosis?","options":["To create sperm and egg cells","To produce two identical daughter cells for growth and repair","To break down glucose for energy","To combine two different cells"],"answerIndex":1,"explanation":"Mitosis produces two genetically identical daughter cells, allowing organisms to grow and repair tissue."},{"question":"What do mitochondria produce during cellular respiration?","options":["Oxygen","DNA","Usable energy (ATP)","Chlorophyll"],"answerIndex":2,"explanation":"Mitochondria convert glucose and oxygen into ATP, the energy currency cells use to function."}],"apply":{"prompt":"Track your breathing rate before and after one minute of exercise (like jumping jacks) to see cellular respiration''s oxygen demand in action.","checklist":["Counted resting breaths per minute","Did 1 minute of exercise","Counted breaths per minute right after and explained the change using cellular respiration"]}}'::jsonb
where type = 'class_topic' and key = 'Biology' and meta->>'topic_key' = 'cellProcesses';

update public.app_content
set meta = meta || '{"learn":[{"heading":"A Big Blue World","body":"Oceans cover most of Earth''s surface with salty water, and they are home to an enormous number of living things, from tiny plankton to giant whales. Ocean animals need water to breathe (through gills) or to swim to the surface for air, like dolphins and whales."},{"heading":"Many Kinds of Ocean Life","body":"Fish, crabs, octopuses, sea turtles, and coral are just a few of the many kinds of animals living in the ocean, and each has special body parts to help it survive underwater, like fins for swimming or shells for protection. Plants and plant-like ocean life, like seaweed, use sunlight near the surface to grow, just like plants on land."}],"practice":[{"question":"How do fish breathe underwater?","options":["With lungs","With gills","They hold their breath","They do not need to breathe"],"answerIndex":1,"explanation":"Fish use gills to take oxygen directly from the water."},{"question":"Which ocean animal must swim to the surface to breathe air?","options":["A crab","A dolphin","A fish","A jellyfish"],"answerIndex":1,"explanation":"Dolphins are mammals and must surface to breathe air through their blowhole, unlike fish."}],"apply":{"prompt":"Choose 3 ocean animals and draw or describe one special body part each uses to survive in the water (like fins, gills, or a shell).","checklist":["Chose 3 different ocean animals","Named one special body part for each","Explained how that body part helps it survive"]}}'::jsonb
where type = 'class_topic' and key = 'Oceanography' and meta->>'topic_key' = 'oceanBasics';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Waves and Tides","body":"Waves are usually caused by wind blowing across the surface of the water, pushing it into rolling shapes. Tides are the regular rise and fall of ocean water levels, caused mainly by the pull of the Moon''s gravity on Earth''s oceans, and most coastlines get two high tides and two low tides each day."},{"heading":"Ocean Currents","body":"Currents are like rivers within the ocean — large, steady movements of water caused by wind, temperature differences, and the rotation of the Earth. Currents carry warm and cold water around the globe, which affects weather and helps sea creatures travel and find food."}],"practice":[{"question":"What mainly causes ocean waves?","options":["The Moon''s gravity","Wind blowing across the water","Fish swimming","Earth spinning"],"answerIndex":1,"explanation":"Waves are primarily created by wind pushing across the surface of the ocean."},{"question":"What mainly causes ocean tides?","options":["Wind","The Moon''s gravitational pull","Ocean currents","Boat traffic"],"answerIndex":1,"explanation":"The Moon''s gravity pulls on Earth''s oceans, causing the regular rise and fall we call tides."}],"apply":{"prompt":"If you live near a coast, observe the tide at two different times of day (or look up a tide chart online) and note how the water line changes.","checklist":["Checked or looked up the tide at two different times","Noted whether the water was higher or lower each time","Explained the change using the Moon''s pull"]}}'::jsonb
where type = 'class_topic' and key = 'Oceanography' and meta->>'topic_key' = 'wavesTidesCurrents';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Currents Shape Ecosystems and Climate","body":"Ocean currents distribute heat around the planet, moderating regional climates — for example, the Gulf Stream keeps parts of Western Europe milder than their latitude would otherwise suggest. Currents also transport nutrients that support entire marine food webs, from plankton to whales."},{"heading":"Human Impact on the Ocean","body":"Human activities like overfishing, plastic pollution, and rising carbon dioxide emissions (which cause ocean acidification and warming) are disrupting marine ecosystems worldwide. Coral reefs, which support roughly a quarter of all marine species, are especially sensitive to small changes in ocean temperature and pH."}],"practice":[{"question":"How do ocean currents affect regional climate?","options":["They have no effect","They distribute heat around the planet","They only affect rainfall","They cool the entire Earth equally"],"answerIndex":1,"explanation":"Currents like the Gulf Stream carry warm or cold water that moderates the climate of nearby land regions."},{"question":"Why are coral reefs especially vulnerable to climate change?","options":["They need cold water only","They are sensitive to small shifts in temperature and pH","They do not support other species","They grow faster when oceans warm"],"answerIndex":1,"explanation":"Coral is highly sensitive to changes in ocean temperature and acidity, which can cause bleaching and die-offs."}],"apply":{"prompt":"Research one specific human impact on the ocean (such as coral bleaching, plastic pollution, or overfishing) and outline one realistic action individuals can take to reduce it.","checklist":["Chose one specific human impact on oceans","Explained how it affects marine ecosystems","Listed one realistic individual action to help"]}}'::jsonb
where type = 'class_topic' and key = 'Oceanography' and meta->>'topic_key' = 'oceanEcosystems';

-- ── Enrich remaining Social Sciences topics (11) ─────────────────────────

update public.app_content
set meta = meta || '{"learn":[{"heading":"Rivers Made Farming Possible","body":"Long ago, people moved around a lot to hunt animals and gather plants. Near big rivers like the Indus, the water and soil were so good for growing food that people could stay in one place and farm all year."},{"heading":"From Farms to Cities","body":"When farmers grew more food than their families needed, other people did not have to farm anymore — they could build houses, make tools, or trade instead. That is how small farming villages near the Indus grew into big, busy cities."}],"practice":[{"question":"Why did early people settle near rivers like the Indus?","options":["Rivers were fun to swim in","Rivers gave water and good soil for farming","Rivers had no animals nearby","Rivers made travel impossible"],"answerIndex":1,"explanation":"A steady water supply and rich soil let people farm instead of always moving around."},{"question":"What happened when farmers grew extra food?","options":["Everyone still had to farm","Some people could do other jobs, and villages grew into cities","The extra food was thrown away","People stopped living near the river"],"answerIndex":1,"explanation":"Extra food freed some people to build, make tools, or trade, which helped villages grow into cities."}],"apply":{"prompt":"Draw a simple map showing a river with a village on its bank. Label 3 things the river gives the village (like water, fish, or good soil).","checklist":["Drew a river on the map","Drew a village next to the river","Labeled 3 things the river provides"]}}'::jsonb
where type = 'class_topic' and key = 'History' and meta->>'topic_key' = 'earlyCivilizations';

update public.app_content
set meta = meta || '{"learn":[{"heading":"A Loaded Word","body":"Historians once defined \"civilization\" using a checklist — cities, writing, government, monuments — and judged societies as more or less \"advanced\" by it. Today most historians treat that checklist skeptically: it was built from a Western viewpoint and often ignored complex societies, like nomadic or oral cultures, that did not fit the mold."},{"heading":"Collapse Is Not Simple","body":"Civilizations that seem to \"collapse,\" like the Bronze Age societies of the eastern Mediterranean, rarely vanish for one reason. Historians point to combinations of causes — climate shifts, trade breakdowns, invasions, and internal unrest — that stack up and make a society lose the complexity it once had."}],"practice":[{"question":"Why do many historians today question the traditional \"checklist\" definition of civilization?","options":["It has too many categories","It reflects a Western bias and excludes societies that do not fit it","It is too scientific","All historians have always agreed on it"],"answerIndex":1,"explanation":"The checklist approach judged societies by criteria rooted in a Western perspective, sidelining societies organized differently."},{"question":"According to historians, what usually causes a civilization to collapse?","options":["A single sudden event","Multiple combined factors like climate, trade, and conflict","Collapse never actually happens","Only foreign invasion"],"answerIndex":1,"explanation":"Collapse is typically the result of several stacked pressures rather than one isolated cause."}],"apply":{"prompt":"Pick one historical or modern society. List 3 factors that could cause it to become unstable (like environment, economy, or conflict), and explain how they might combine.","checklist":["Named the society","Listed 3 destabilizing factors","Explained how the factors could combine"]}}'::jsonb
where type = 'class_topic' and key = 'History' and meta->>'topic_key' = 'rethinkingHistory';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Seven Big Land Pieces","body":"The world has 7 continents: Africa, Antarctica, Asia, Australia, Europe, North America, and South America. A continent is a huge piece of land, and we live on one of them right now!"},{"heading":"Oceans Are Everywhere","body":"There are 5 big oceans full of salty water: the Pacific, Atlantic, Indian, Southern, and Arctic. Oceans are so big that they touch almost every continent, and a map uses blue color to show where the water is."}],"practice":[{"question":"How many continents are there?","options":["4","5","7","10"],"answerIndex":2,"explanation":"There are 7 continents on Earth."},{"question":"What color do maps usually use to show oceans?","options":["Green","Blue","Red","Yellow"],"answerIndex":1,"explanation":"Maps use blue to show oceans and other water."}],"apply":{"prompt":"Draw a big circle for the world. Draw and label 2 continents and 1 ocean on it.","checklist":["Drew a circle for the world","Labeled 2 continents","Labeled 1 ocean"]}}'::jsonb
where type = 'class_topic' and key = 'Geography' and meta->>'topic_key' = 'mapsContinentsOceans';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Countries Have Borders","body":"A country is a piece of land with its own government, laws, and borders — invisible lines that show where one country ends and another begins. There are almost 200 countries in the world, each shown as its own color on a map."},{"heading":"Flags and Culture","body":"Every country has its own flag, made of colors and symbols that stand for its history or values. Culture is the food, language, holidays, and traditions that people in a place share — and it can be different even between countries that are neighbors."}],"practice":[{"question":"What is a border?","options":["A type of flag","The line that separates one country from another","A kind of ocean","A tall mountain"],"answerIndex":1,"explanation":"A border is the line that marks where one country ends and another begins."},{"question":"What does \"culture\" include?","options":["Only a country''s flag","Food, language, and traditions people share","Only the weather","Only the money used"],"answerIndex":1,"explanation":"Culture includes the shared food, language, holidays, and traditions of a group of people."}],"apply":{"prompt":"Pick one country that is not the one you live in. Find its flag and write down 2 things about its culture (like a food, language, or holiday).","checklist":["Named the country","Drew or described its flag","Wrote 2 facts about its culture"]}}'::jsonb
where type = 'class_topic' and key = 'Geography' and meta->>'topic_key' = 'countriesCulturesFlags';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Physical vs. Human Geography","body":"Physical geography studies natural features — mountains, rivers, climate, and landforms. Human geography studies how people live: where cities form, how populations move, and how people use and change the land around them."},{"heading":"Scale: From World to Address","body":"Geography works at every scale, from the whole planet down to your street address. A continent contains countries, countries contain cities, and cities contain neighborhoods — each level connects to the ones above and below it."}],"practice":[{"question":"What does human geography study?","options":["Only mountains and rivers","How people live, move, and use the land","Only weather patterns","Only oceans"],"answerIndex":1,"explanation":"Human geography focuses on people — where they settle, how populations move, and how they shape the land."},{"question":"Which is an example of physical geography?","options":["A city''s population size","A mountain range","A country''s government","A local language"],"answerIndex":1,"explanation":"Mountain ranges are natural landforms, which is what physical geography studies."}],"apply":{"prompt":"Write your own address (continent, country, state/region, city). Then note 1 physical geography feature (like a river or hill) and 1 human geography feature (like a road or building) near where you live.","checklist":["Wrote out the full address chain","Named 1 physical feature nearby","Named 1 human-made feature nearby"]}}'::jsonb
where type = 'class_topic' and key = 'Geography' and meta->>'topic_key' = 'humanPhysicalGeography';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Why We Need Rules","body":"Rules keep people safe and fair to each other, whether at home, at school, or in a whole country. Without rules, it would be hard to know what is okay to do and what is not, and it would be easier for people to get hurt or treated unfairly."},{"heading":"The Constitution Is Our Rulebook","body":"The Constitution is the most important set of rules for the United States. It explains how the government is set up, what jobs different leaders have, and what rights every citizen gets to keep, like freedom of speech."}],"practice":[{"question":"Why do communities need rules?","options":["To make life boring","To keep people safe and treat everyone fairly","Rules are not actually needed","Only adults need rules"],"answerIndex":1,"explanation":"Rules help keep people safe and make sure everyone is treated fairly."},{"question":"What is the Constitution?","options":["A list of state capitals","The document that sets up America''s government and rights","A map of the country","A book of songs"],"answerIndex":1,"explanation":"The Constitution lays out how the U.S. government works and protects citizens'' rights."}],"apply":{"prompt":"Write 3 rules for your own classroom or home. Next to each rule, explain in 1 sentence why it is fair or helpful.","checklist":["Wrote 3 rules","Explained why each rule is fair or helpful","Rules make sense for the setting chosen"]}}'::jsonb
where type = 'class_topic' and key = 'CivicsAndGovernment' and meta->>'topic_key' = 'rulesRightsConstitution';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Two Chambers, One Congress","body":"Article 1 of the Constitution creates Congress, the legislative branch, and splits it into two chambers: the House of Representatives and the Senate. This \"bicameral\" design was a compromise — the House is based on state population, while the Senate gives every state 2 seats regardless of size."},{"heading":"How a Bill Becomes a Law","body":"A proposed law, called a bill, has to pass both the House and the Senate in the same form before it goes to the President. This two-chamber process forces lawmakers to debate and compromise, which slows things down but is meant to prevent hasty or one-sided laws."}],"practice":[{"question":"What are the two chambers of Congress?","options":["The House and the Senate","The Senate and the Supreme Court","The House and the Cabinet","The Senate and the Presidency"],"answerIndex":0,"explanation":"Congress is bicameral, made up of the House of Representatives and the Senate."},{"question":"How are seats in the Senate assigned to states?","options":["Based on population","Every state gets exactly 2 seats","Based on land area","States take turns each year"],"answerIndex":1,"explanation":"Every state gets 2 senators no matter its population, unlike the House, which is based on population."}],"apply":{"prompt":"Pick a rule you wish existed at your school. Write it as a short \"bill,\" then explain how you would get 2 different groups (like students and teachers) to agree to it, just like the House and Senate must agree.","checklist":["Wrote the bill as a short rule","Identified the 2 groups that must agree","Explained how you would get them to agree"]}}'::jsonb
where type = 'class_topic' and key = 'CivicsAndGovernment' and meta->>'topic_key' = 'congressLawmaking';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Compromises That Built the Constitution","body":"The Constitutional Convention of 1787 was full of disagreement, especially between large and small states over representation. The Great Compromise created a bicameral Congress — a House based on population and a Senate with equal representation — while the Three-Fifths Compromise, later erased by the 13th and 14th Amendments, dealt with how enslaved people were counted."},{"heading":"Federalism Divides Power","body":"Federalism is the system that splits governing power between the national government and the state governments, each with its own responsibilities. Some powers, like declaring war, belong only to the federal government; others, like running local schools, are mostly left to the states; and some, like taxation, are shared by both."}],"practice":[{"question":"What did the Great Compromise establish?","options":["A single-chamber legislature","A bicameral Congress with a population-based House and equal-representation Senate","The abolition of slavery","Direct election of the President"],"answerIndex":1,"explanation":"The Great Compromise balanced large and small states by creating two chambers with different representation rules."},{"question":"What does federalism describe?","options":["Power held only by the President","Power divided between national and state governments","Power held only by the courts","Power divided among foreign nations"],"answerIndex":1,"explanation":"Federalism is a system of government where power is shared between a national government and state governments."}],"apply":{"prompt":"Choose 3 government powers (like building roads, printing money, running schools, and declaring war). Research and sort each one as a federal power, a state power, or a shared power.","checklist":["Chose 3 government powers","Correctly classified each as federal, state, or shared","Briefly explained the reasoning for one"]}}'::jsonb
where type = 'class_topic' and key = 'CivicsAndGovernment' and meta->>'topic_key' = 'constitutionGovernment';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Emotions Show Up in Your Body","body":"Emotions are not just thoughts — they show up in your body too, like a fast heartbeat when you are scared or a smile when you are happy. Your face and body often tell others how you feel even before you say any words."},{"heading":"Stress and Feelings Are Connected","body":"Stress happens when something feels hard or worrying, like a big test or a fight with a friend. Too much stress for too long can make your body feel tired or sick, so it helps to notice stress early and find ways to calm down, like deep breathing or talking to someone."}],"practice":[{"question":"How do emotions often show up besides in your thoughts?","options":["They never show up anywhere else","In your body, like your heartbeat or face","Only in your dreams","Only when you are alone"],"answerIndex":1,"explanation":"Emotions show up physically too, like a racing heart when scared or a smile when happy."},{"question":"What can happen if stress lasts too long?","options":["Nothing changes at all","It can make your body feel tired or unwell","It always makes you stronger","It disappears on its own instantly"],"answerIndex":1,"explanation":"Long-lasting stress can affect the body and make a person feel tired or unwell."}],"apply":{"prompt":"For one day, notice 3 moments when you feel an emotion. Write down the emotion, what your body did (like your face or heartbeat), and what caused it.","checklist":["Recorded 3 different emotional moments","Described a body signal for each","Named what caused each emotion"]}}'::jsonb
where type = 'class_topic' and key = 'PsychologicalAndSociology' and meta->>'topic_key' = 'understandingEmotions';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Groups Change Behavior","body":"People often act differently in a group than they would by themselves — a behavior called conformity. Someone might go along with what everyone else is doing, even if they privately disagree, because fitting in feels safer than standing out."},{"heading":"Social Influence Is Powerful","body":"The people around us — friends, family, and even strangers — shape our choices without us always noticing. This can be positive, like a friend encouraging you to try harder, or negative, like feeling pressured to do something you know is not a good idea."}],"practice":[{"question":"What is conformity?","options":["Always disagreeing with a group","Going along with a group even if you privately disagree","Making decisions completely alone","Ignoring everyone around you"],"answerIndex":1,"explanation":"Conformity is adjusting your behavior to match a group, sometimes even against your own private opinion."},{"question":"Can social influence be a good thing?","options":["No, it is always bad","Yes, like a friend encouraging positive behavior","It only affects adults","It only happens online"],"answerIndex":1,"explanation":"Social influence can be positive, such as friends motivating each other to do better."}],"apply":{"prompt":"Think of a time you did something differently because you were in a group versus alone. Write 2-3 sentences describing what happened and whether the group''s influence was positive or negative.","checklist":["Described a real group situation","Explained how behavior changed","Judged whether the influence was positive or negative"]}}'::jsonb
where type = 'class_topic' and key = 'PsychologicalAndSociology' and meta->>'topic_key' = 'socialThinking';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Psychology vs. Sociology","body":"Psychology is the scientific study of the mind and individual behavior — how a single person thinks, feels, and acts. Sociology studies people at a broader level: how groups, institutions, and social structures shape human behavior and how individuals develop within society."},{"heading":"Socialization Across a Lifetime","body":"Socialization is the lifelong process by which people learn the norms, values, and roles of their society, starting with family and expanding to schools, peer groups, and media. This process explains why people from different cultures or generations can hold very different beliefs about what is \"normal.\""}],"practice":[{"question":"What is the main focus of psychology?","options":["Government structures","The mind and individual behavior","International trade","Weather patterns"],"answerIndex":1,"explanation":"Psychology is the scientific study of the mind and individual behavior."},{"question":"What does sociology study that psychology typically does not?","options":["Individual dreams","How groups and social structures shape behavior","Brain chemistry","Personal memory"],"answerIndex":1,"explanation":"Sociology looks at the broader level of groups, institutions, and social structures, not just the individual mind."}],"apply":{"prompt":"Interview someone from a different generation than you (a parent, grandparent, or older sibling). Ask what \"normal\" behavior for teenagers looked like when they were young, then compare it to today in 3-4 sentences.","checklist":["Conducted the interview","Recorded what was considered normal in their generation","Compared it to today in your own words"]}}'::jsonb
where type = 'class_topic' and key = 'PsychologicalAndSociology' and meta->>'topic_key' = 'introPsychSociety';

-- ── Enrich remaining Art & Music topics (24) ─────────────────────────────

update public.app_content
set meta = meta || '{"learn":[{"heading":"Three Kinds of Paint","body":"Watercolor is thinned with water and stays transparent, so light areas come from the white paper showing through. Acrylic is water-based but dries fast and permanent, while oil paint dries slowly and blends smoothly, letting artists work on a painting over days or weeks."},{"heading":"Mixing Your Own Colors","body":"The three primary colors — red, yellow, and blue — combine to make secondary colors like orange, green, and purple. Adding white makes a tint (lighter), and adding black makes a shade (darker), giving you an almost unlimited palette from just a few tubes."}],"practice":[{"question":"Which paint dries the fastest?","options":["Watercolor","Acrylic","Oil paint","They all dry at the same speed"],"answerIndex":1,"explanation":"Acrylic paint dries quickly, often within minutes, because it''s water-based, unlike oil paint which can take days."},{"question":"What color do you get when you mix blue and yellow paint?","options":["Purple","Orange","Green","Brown"],"answerIndex":2,"explanation":"Blue and yellow are primary colors that combine to make green, a secondary color."}],"apply":{"prompt":"Paint a simple landscape (sky, ground, and one object like a tree or house) using only the three primary colors plus white, mixing every other color you need on your palette.","checklist":["Mixed at least 2 secondary colors from primaries","Used different brushstrokes for different textures (like sky vs. ground)","Painting has a clear foreground and background"]}}'::jsonb
where type = 'class_topic' and key = 'VisualArt' and meta->>'topic_key' = 'painting';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Thinking in the Round","body":"Unlike a drawing on flat paper, a sculpture exists in three dimensions and has to look good from every angle — front, back, sides, and even the top. Artists rotate their work constantly while making it to check all those views."},{"heading":"Additive vs. Subtractive","body":"There are two main approaches to sculpting: additive, where you build up a form by adding material (like stacking clay or welding metal), and subtractive, where you carve away material from a larger block (like wood or stone) until the form emerges."}],"practice":[{"question":"What makes sculpture different from drawing or painting?","options":["It''s always made of clay","It exists in three dimensions and can be viewed from many angles","It can''t have color","It is only used for statues of people"],"answerIndex":1,"explanation":"Sculpture is three-dimensional, so unlike a flat drawing, it must be considered from all sides."},{"question":"Carving a figure out of a block of wood is an example of which sculpting method?","options":["Additive","Subtractive","Modeling","Casting"],"answerIndex":1,"explanation":"Carving removes material from a larger block, which is the subtractive method — the opposite of building up with clay."}],"apply":{"prompt":"Using air-dry clay, plasticine, or even shaped aluminum foil, build a small three-dimensional form (an animal, a bowl, or an abstract shape) and check that it looks good from at least four different angles.","checklist":["Sculpture stands on its own without falling over","Checked and adjusted the form from the front, back, and both sides","Used at least one texture (smooth, rough, or bumpy) on purpose"]}}'::jsonb
where type = 'class_topic' and key = 'VisualArt' and meta->>'topic_key' = 'sculpture3d';

update public.app_content
set meta = meta || '{"learn":[{"heading":"What Makes Printmaking Different","body":"Printmaking creates multiple original copies — called an \"edition\" — from one prepared surface, like a carved block, an etched plate, or a screen. That is different from painting or drawing, which produce a single, unique piece."},{"heading":"Relief vs. Intaglio","body":"In relief printing (like woodblock or linocut), you carve away the areas that should stay blank, so ink sits on the raised surface that remains. In intaglio, it''s the opposite — ink sits in carved grooves below the surface, and a printing press forces the paper into those grooves to pick it up."}],"practice":[{"question":"In relief printmaking, where does the ink go?","options":["Into carved grooves below the surface","Only on the raised (uncarved) areas","Directly onto the paper with no plate","Nowhere — relief prints use no ink"],"answerIndex":1,"explanation":"Relief printing carves away the areas meant to stay blank, leaving ink on the raised surface that remains."},{"question":"What is a set of identical prints made from the same plate called?","options":["A palette","A collage","An edition","A wash"],"answerIndex":2,"explanation":"A set of prints pulled from the same plate or block is called an edition."}],"apply":{"prompt":"Carve a simple design into a foam sheet or a potato half (a shape, initial, or pattern), ink it, and stamp at least 3 identical prints to create your own small edition.","checklist":["Carved a design with clear raised and recessed areas","Printed at least 3 matching copies","Signed and numbered the edition (e.g., 1/3, 2/3, 3/3)"]}}'::jsonb
where type = 'class_topic' and key = 'VisualArt' and meta->>'topic_key' = 'printmaking';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Working Clay by Hand","body":"There are three basic hand-building techniques: pinch (shaping clay with your fingers from a single ball), coil (stacking and smoothing rolled ropes of clay), and slab (cutting and joining flat sheets). These don''t require a pottery wheel, just your hands and simple tools."},{"heading":"The Structure of Weaving","body":"Weaving interlaces two sets of threads: the warp, which is stretched vertically and held in place on the loom, and the weft, which is woven horizontally over and under the warp threads to build up the fabric."}],"practice":[{"question":"Which hand-building technique starts by rolling clay into long ropes and stacking them?","options":["Pinch","Coil","Slab","Wheel-throwing"],"answerIndex":1,"explanation":"Coil building stacks rolled ropes of clay and smooths them together to build up the walls of a form."},{"question":"In weaving, what are the fixed threads held on the loom called?","options":["Weft","Warp","Shuttle","Selvage"],"answerIndex":1,"explanation":"The warp threads are strung vertically on the loom and stay in place while the weft is woven through them."}],"apply":{"prompt":"Choose one: hand-build a small clay pinch pot, or weave a small sample on a cardboard loom using yarn or fabric strips.","checklist":["If clay: used at least one hand-building technique (pinch, coil, or slab)","If weaving: kept a consistent over-under pattern across at least 10 rows","Finished piece can hold its shape on its own"]}}'::jsonb
where type = 'class_topic' and key = 'VisualArt' and meta->>'topic_key' = 'ceramicsFiber';

update public.app_content
set meta = meta || '{"learn":[{"heading":"The Exposure Triangle","body":"Three settings control how bright or dark a photo turns out: aperture (how wide the lens opening is), shutter speed (how long light hits the sensor), and ISO (how sensitive the sensor is to light). Balancing all three gives you a properly exposed photo."},{"heading":"The Rule of Thirds","body":"Imagine a grid dividing your photo into 9 equal parts, like a tic-tac-toe board. Placing your subject along those grid lines or at their intersections — instead of dead center — usually creates a more balanced and interesting composition."}],"practice":[{"question":"Which of these is part of the \"exposure triangle\" that controls how bright or dark a photo is?","options":["Shutter speed","Filter","Crop","Filename"],"answerIndex":0,"explanation":"Shutter speed, along with aperture and ISO, is one of the three settings that control a photo''s exposure."},{"question":"According to the rule of thirds, where should the main subject of a photo usually be placed?","options":["Always dead center","Along imaginary lines or intersections dividing the frame into thirds","In the very top corner","It doesn''t matter"],"answerIndex":1,"explanation":"The rule of thirds suggests placing key elements along the grid lines or their intersections for a more balanced composition."}],"apply":{"prompt":"Take 5 photos of the same object or scene using the rule of thirds instead of centering it, then pick your favorite and adjust its brightness or contrast in a free photo editor.","checklist":["Took at least 5 photos applying the rule of thirds","Selected the strongest photo and explained why","Made at least one edit (brightness, contrast, or crop) to the chosen photo"]}}'::jsonb
where type = 'class_topic' and key = 'VisualArt' and meta->>'topic_key' = 'photographyDigital';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Beyond a Single Medium","body":"Mixed media artwork deliberately combines two or more distinct materials or techniques — like paint, collage, and found objects — in a single piece, letting the artist use each material''s unique texture, color, or meaning."},{"heading":"Art That Responds to Space","body":"Installation and site-specific art is created for, and responds to, a particular location. The artist considers how viewers move through and experience the space itself, not just how a flat piece looks on a wall."}],"practice":[{"question":"What defines \"mixed media\" artwork?","options":["Art made only with paint","Art that combines two or more different materials or techniques","Art displayed only in museums","Art that must be digital"],"answerIndex":1,"explanation":"Mixed media art deliberately combines multiple materials or techniques, such as paint, paper, and found objects, within one piece."},{"question":"What makes a work \"site-specific\"?","options":["It is created to be displayed anywhere","It is designed for and responds to a particular location","It can only be made of clay","It has no relationship to its surroundings"],"answerIndex":1,"explanation":"Site-specific art is conceived for a particular place and takes that location''s space, history, or context into account."}],"apply":{"prompt":"Create a small mixed-media piece combining at least three different materials (for example, drawing, torn paper or collage, and a found object like fabric or cardboard) that responds to a specific space in your home or school.","checklist":["Used at least 3 different materials or techniques","Considered how the piece relates to the specific space you chose","Can explain why you chose to combine those particular materials"]}}'::jsonb
where type = 'class_topic' and key = 'VisualArt' and meta->>'topic_key' = 'mixedMediaInstallation';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Elements Are the Ingredients","body":"The elements of art — line, shape, form, color, texture, and space — are the basic building blocks every artist works with, like ingredients in a recipe. Every artwork, no matter the style, is built from some combination of these."},{"heading":"Principles Are How You Arrange Them","body":"The principles of art — balance, contrast, emphasis, movement, pattern, rhythm, and unity — describe how an artist organizes the elements to make a piece feel complete and interesting, the way a recipe tells you how to combine ingredients."}],"practice":[{"question":"Which of these is an \"element of art\" rather than a \"principle of art\"?","options":["Balance","Color","Emphasis","Unity"],"answerIndex":1,"explanation":"Color is a basic building block, an element; balance, emphasis, and unity describe how those elements are arranged, which makes them principles."},{"question":"If an artist repeats a shape across a painting to create visual flow, which principle are they using?","options":["Contrast","Pattern","Space","Line"],"answerIndex":1,"explanation":"Repeating a shape or motif to create rhythm and visual flow is the principle of pattern."}],"apply":{"prompt":"Create a small artwork (a drawing or collage) that intentionally uses at least 3 elements of art (like line, shape, and color) and 2 principles of art (like balance, contrast, or pattern).","checklist":["Can point out 3 elements of art you used","Can point out 2 principles of art you used","The piece feels intentional, not random"]}}'::jsonb
where type = 'class_topic' and key = 'VisualArt' and meta->>'topic_key' = 'elementsPrinciples';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Art Movements Tell a Story","body":"Art history is organized into movements — Renaissance, Impressionism, Cubism, and more — each reflecting the ideas, technology, and events of its time period. Knowing the movement helps explain why an artwork looks and means what it does."},{"heading":"The Four Steps of Art Criticism","body":"Formal art criticism follows four steps, in order: description (what do you literally see), analysis (how are elements and principles used), interpretation (what does it mean), and judgment (how well does it succeed). Skipping straight to judgment leads to shallow opinions."}],"practice":[{"question":"Why do art historians group artworks into \"movements\" like Impressionism or Cubism?","options":["Because all artists in a movement used the same brand of paint","Because these groupings reflect shared ideas, techniques, or historical context of a time period","Movements are randomly assigned by museums","Movements only apply to sculpture"],"answerIndex":1,"explanation":"Art movements group works that share stylistic approaches or ideas, often shaped by the historical or cultural moment they came from."},{"question":"In the four steps of art criticism, what comes right before \"judgment\"?","options":["Interpretation","Nothing — judgment comes first","Framing","Pricing"],"answerIndex":0,"explanation":"The standard order is description, analysis, interpretation, then judgment — forming an opinion should come only after understanding the work."}],"apply":{"prompt":"Choose one famous artwork (from a book, museum website, or class example) and write a short critique following the four steps: describe what you see, analyze the elements and principles used, interpret its meaning, and give your judgment.","checklist":["Described only what is visible, without opinions, in step 1","Identified at least 2 elements or principles used in the piece","Gave a final judgment supported by your analysis"]}}'::jsonb
where type = 'class_topic' and key = 'VisualArt' and meta->>'topic_key' = 'artHistoryCriticism';

update public.app_content
set meta = meta || '{"learn":[{"heading":"What Is Sight-Singing?","body":"Sight-singing means reading and singing written music accurately the very first time you see it, without ever having heard it before. It relies on recognizing pitch relationships, like do-re-mi steps, and rhythm patterns at a glance."},{"heading":"Singing Together vs. Singing Alone","body":"In a choir, singers blend their voice with everyone else''s — matching pitch, dynamics, and breathing together, and listening as much as singing. As a soloist, a singer instead has full freedom to shape their own interpretation."}],"practice":[{"question":"What does \"sight-singing\" mean?","options":["Singing with your eyes closed","Singing written music accurately without having heard it before","Singing only songs you memorized","Singing a duet"],"answerIndex":1,"explanation":"Sight-singing is reading notated music and singing it correctly on the first try."},{"question":"In a choir, why is \"blending\" your voice with others important?","options":["So one voice can be heard over everyone else","So the group sounds unified rather than like separate individual voices","Blending isn''t important in choir","To sing louder than the accompaniment"],"answerIndex":1,"explanation":"Blending means matching pitch, tone, and dynamics with the group so the ensemble sounds like one unified voice."}],"apply":{"prompt":"Learn a simple 4-8 measure melody (from a method book or app) using solfège (do-re-mi), then record yourself singing it and check your pitch accuracy against a piano or tuner app.","checklist":["Practiced the melody using solfège syllables","Recorded or performed the full phrase from memory or notation","Identified at least one spot where pitch needed correcting"]}}'::jsonb
where type = 'class_topic' and key = 'Music' and meta->>'topic_key' = 'vocalChoral';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Families of Instruments","body":"Band instruments group into woodwinds (like flute and clarinet, which use a reed or blown air across an opening), brass (like trumpet and trombone, played by buzzing the lips into a mouthpiece), and percussion (drums and mallets, played by striking or shaking)."},{"heading":"Band vs. Orchestra vs. Jazz Ensemble","body":"A concert band combines woodwinds, brass, and percussion with no strings. An orchestra adds a full string section — violin, viola, cello, and bass — as its core. A jazz ensemble usually pairs a rhythm section (piano, bass, drums) with horns, often featuring improvisation."}],"practice":[{"question":"Which family does the trumpet belong to?","options":["Woodwinds","Brass","Percussion","Strings"],"answerIndex":1,"explanation":"The trumpet is a brass instrument, played by buzzing the lips into a metal mouthpiece."},{"question":"What is the main instrument family found in an orchestra that is usually NOT in a concert band?","options":["Percussion","Woodwinds","Strings","Brass"],"answerIndex":2,"explanation":"Orchestras are built around a string section (violins, violas, cellos, basses), which concert bands typically don''t include."}],"apply":{"prompt":"Research one instrument from each family (woodwind, brass, percussion, and string) and create a short chart or poster showing how each one produces sound.","checklist":["Included one instrument from each of the 4 families","Explained how each instrument makes sound","Noted which family is missing from a standard concert band"]}}'::jsonb
where type = 'class_topic' and key = 'Music' and meta->>'topic_key' = 'instrumental';

update public.app_content
set meta = meta || '{"learn":[{"heading":"What Makes Chamber Music Different","body":"Chamber music is written for a small group, usually one performer per part, with 2-9 musicians and no conductor. That means the musicians rely on eye contact, listening, and nonverbal cues to stay together instead of following a conductor."},{"heading":"Rehearsing as a Team","body":"Efficient chamber rehearsal means isolating tricky passages, agreeing on tempo and dynamics as a group, and deciding together who is \"leading\" a phrase at any given moment — all through communication rather than one designated leader."}],"practice":[{"question":"What is a key feature of chamber music ensembles?","options":["They always have more than 50 performers","They have no conductor and usually one performer per part","They only play electronic music","They never rehearse together"],"answerIndex":1,"explanation":"Chamber ensembles are small groups, typically with one player per part, and perform without a conductor."},{"question":"Without a conductor, how do chamber musicians stay together during a performance?","options":["They ignore each other and play independently","They listen closely and use eye contact and cues to coordinate","They use a metronome the whole time instead of listening","They take turns stopping to check in"],"answerIndex":1,"explanation":"Chamber musicians rely on active listening and visual cues to stay synchronized since there''s no conductor."}],"apply":{"prompt":"With 2-4 classmates or friends, rehearse a short piece or rhythm pattern together without a conductor, deciding as a group who cues the start and how you''ll stay in sync.","checklist":["Practiced without anyone conducting the group","Agreed together on tempo and who gives the starting cue","Performed the piece staying together through at least one tricky section"]}}'::jsonb
where type = 'class_topic' and key = 'Music' and meta->>'topic_key' = 'ensembleChamber';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Interpretation Is a Choice","body":"Sheet music gives you the notes and rhythms, but the performer decides how to shape a phrase — dynamics, tempo flexibility (rubato), and tone color. Two performers playing the exact same piece can sound very different because of their interpretive choices."},{"heading":"Stage Presence Beyond the Notes","body":"A confident walk-on and walk-off, good posture, eye contact with the audience, and handling mistakes smoothly instead of stopping or panicking all shape how a performance is received, separate from technical accuracy."}],"practice":[{"question":"Why might two performers playing the exact same written piece sound noticeably different?","options":["One of them is using different notes","Performers make different interpretive choices about dynamics, tempo, and tone","Sheet music sounds different depending on who reads it","It is impossible for this to happen"],"answerIndex":1,"explanation":"The notes may be identical, but performers make personal choices about expression, dynamics, and pacing that shape interpretation."},{"question":"If you make a small mistake during a solo recital, what is generally the best response?","options":["Stop and restart the piece from the beginning","Keep going smoothly as if nothing happened","Apologize out loud to the audience","Leave the stage immediately"],"answerIndex":1,"explanation":"Skilled performers keep going and recover smoothly; stopping or drawing attention to a small error disrupts the performance more than the mistake itself."}],"apply":{"prompt":"Prepare a short piece (30-90 seconds) and perform it for at least one other person, making 2 deliberate interpretive choices — like a dynamic swell or a tempo change — beyond just playing the correct notes.","checklist":["Identified 2 specific interpretive choices before performing","Performed with confident posture and stage presence","Got feedback from your listener on how the interpretation came across"]}}'::jsonb
where type = 'class_topic' and key = 'Music' and meta->>'topic_key' = 'soloPerformance';

update public.app_content
set meta = meta || '{"learn":[{"heading":"The Staff and the Notes","body":"Music is written on a 5-line staff, where each line and space represents a different pitch. A clef, like the treble or bass clef, tells you exactly which pitches those lines and spaces represent."},{"heading":"Reading Rhythm","body":"Note shapes tell you how long to hold a sound, not just which pitch to play. In common (4/4) time, a whole note lasts 4 beats, a half note lasts 2 beats, and a quarter note lasts 1 beat — the time signature tells you how many beats fit in each measure."}],"practice":[{"question":"What does the treble clef tell a musician?","options":["How loud to play","Which pitches the lines and spaces of the staff represent","How fast to play","Which instrument to use"],"answerIndex":1,"explanation":"A clef establishes which pitch each line and space on the staff corresponds to."},{"question":"In 4/4 time, how many beats does a quarter note get?","options":["4 beats","2 beats","1 beat","Half a beat"],"answerIndex":2,"explanation":"A quarter note equals one beat in 4/4 time, where the bottom \"4\" means the quarter note is the beat unit."}],"apply":{"prompt":"Write out (or find) a simple 4-measure rhythm in 4/4 time using quarter, half, and whole notes, then clap or tap it while counting the beats out loud.","checklist":["Rhythm fits exactly 4 beats in each of the 4 measures","Used at least 2 different note values (e.g., quarter and half notes)","Clapped the rhythm accurately while counting beats aloud"]}}'::jsonb
where type = 'class_topic' and key = 'Music' and meta->>'topic_key' = 'notationSightReading';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Chords Are Built From Scales","body":"A basic triad chord is built by stacking three notes from a scale: the root, third, and fifth. Whether that chord sounds major or minor depends on the distance, or interval, between the root and the third."},{"heading":"Melody vs. Harmony","body":"Melody is a single line of notes played one after another — the \"tune\" you hum. Harmony is notes played together, usually as chords, that support and add depth or color underneath that melody."}],"practice":[{"question":"A basic triad chord is built by stacking which scale degrees?","options":["Every other white key on a piano","The root, third, and fifth","Every note in the scale","Only the root note repeated"],"answerIndex":1,"explanation":"A triad stacks the root (1st), third, and fifth notes of a scale."},{"question":"What is the main difference between melody and harmony?","options":["Melody is a single line of notes; harmony is notes played together","They are the same thing","Harmony only exists in singing","Melody is always faster than harmony"],"answerIndex":0,"explanation":"Melody is a sequence of single notes (the tune); harmony is the combination of notes sounding together, like chords."}],"apply":{"prompt":"Pick a simple major scale on an instrument or keyboard app, build the triad chord on the 1st, 4th, and 5th scale degrees, and play a short 4-chord progression using them under a simple melody.","checklist":["Correctly built 3 triads from the same scale","Played the chords in a sequence (progression)","Played or hummed a simple melody that fits over the chords"]}}'::jsonb
where type = 'class_topic' and key = 'Music' and meta->>'topic_key' = 'harmonyMelody';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Finding the Beat","body":"The beat is the steady pulse in music, like a heartbeat, that you can clap or tap along to. Tempo is how fast or slow that beat goes."},{"heading":"Music in Groups","body":"Beats are grouped into small repeating patterns, like counting 4 beats and then starting again — this grouping is called the meter, so a song feels like it has a countable pattern, such as \"1-2-3-4, 1-2-3-4.\""}],"practice":[{"question":"What do we call the steady pulse you can clap along to in a song?","options":["The melody","The beat","The lyrics","The title"],"answerIndex":1,"explanation":"The beat is the steady, repeating pulse underneath the music, like a heartbeat."},{"question":"If a song is played very fast, we say it has a fast what?","options":["Tempo","Color","Shape","Smell"],"answerIndex":0,"explanation":"Tempo describes how fast or slow the beat of a song moves."}],"apply":{"prompt":"Pick your favorite song and clap along to the steady beat for the whole chorus, then try clapping it faster (fast tempo) and slower (slow tempo).","checklist":["Clapped the steady beat without losing it for a full chorus","Tried clapping the beat faster than normal","Tried clapping the beat slower than normal"]}}'::jsonb
where type = 'class_topic' and key = 'Music' and meta->>'topic_key' = 'rhythmMeter';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Sketching Musical Ideas","body":"Composers rarely write a finished piece start to finish in one pass. They typically sketch small motifs, chord progressions, or melodic fragments, then develop, expand, and connect them — much like a writer drafting and revising."},{"heading":"Arranging vs. Composing","body":"Composing means creating original musical material — melody, harmony, and structure. Arranging means taking existing music and reshaping it for a different setting, like turning a solo piano piece into a full band arrangement."}],"practice":[{"question":"What is the difference between composing and arranging?","options":["They are the same thing","Composing creates original music; arranging reshapes existing music for a different setting","Arranging always comes before composing","Only classical musicians arrange music"],"answerIndex":1,"explanation":"Composing generates new musical material, while arranging takes existing music and adapts it for different instruments or styles."},{"question":"How do most composers typically begin writing a piece?","options":["By writing the entire piece perfectly in one sitting from start to finish","By sketching small ideas like motifs or chord progressions, then developing them","By only using a computer to generate the music","Composers never start with small ideas"],"answerIndex":1,"explanation":"Composers commonly begin with small sketched ideas — a motif, a chord progression, a rhythm — that they then develop and connect."}],"apply":{"prompt":"Compose a short 8-measure original melody or beat (using an instrument, voice, or a free DAW/app like GarageBand), starting from one small musical idea (a motif) that you repeat and develop.","checklist":["Started from a single short motif or idea","Developed or varied that idea at least once (repeated it with a change)","Piece is a complete 8-measure phrase with a clear ending"]}}'::jsonb
where type = 'class_topic' and key = 'Music' and meta->>'topic_key' = 'compositionTechniques';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Four Big Periods","body":"Western art music history broadly moves through Baroque (roughly 1600-1750, ornate and structured, like Bach), Classical (roughly 1750-1820, balanced and clear, like Mozart), Romantic (roughly 1820-1900, emotional and expressive, like Tchaikovsky), and 20th-Century/Contemporary music, which often experiments with new tonal systems."},{"heading":"What Changes Between Periods","body":"Each period shifted in instrumentation, harmony rules, and the purpose of music. Baroque music often served the church or court, Romantic music emphasized personal emotion and individual expression, and 20th-century composers frequently broke traditional harmony rules on purpose."}],"practice":[{"question":"Which period is generally known for highly emotional, expressive music that emphasized individual feeling?","options":["Baroque","Classical","Romantic","Medieval"],"answerIndex":2,"explanation":"The Romantic period (roughly 1820-1900) emphasized personal emotion and dramatic expression."},{"question":"Composers like Bach, known for ornate, structured counterpoint, belong to which period?","options":["Baroque","Romantic","Contemporary","Classical"],"answerIndex":0,"explanation":"Bach is a defining composer of the Baroque period, known for intricate, structured counterpoint."}],"apply":{"prompt":"Listen to one short piece each from two different periods (for example, a Bach Baroque piece and a Tchaikovsky Romantic piece) and write a short comparison of how they differ in mood, instrumentation, and structure.","checklist":["Listened to a full excerpt from each of 2 different periods","Named the period and approximate era for each piece","Described at least 2 specific differences between them"]}}'::jsonb
where type = 'class_topic' and key = 'Music' and meta->>'topic_key' = 'westernArtMusic';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Beyond the Major/Minor Scale","body":"Much of world and folk music uses scales or tuning systems different from the Western major/minor system — for example, pentatonic scales (5 notes, common in East Asian and folk music worldwide) or microtonal systems (notes \"between\" piano keys, common in Middle Eastern and Indian music)."},{"heading":"Instruments Reflect Culture","body":"Traditional instruments often reflect the materials, history, and values of the culture that created them — like the sitar (India), the djembe (West Africa), or the didgeridoo (Aboriginal Australia). Each has a role connected to its cultural context, not just its sound."}],"practice":[{"question":"What is a pentatonic scale?","options":["A scale with 12 notes","A scale with 5 notes","A scale used only in Western classical music","A rhythm pattern, not a scale"],"answerIndex":1,"explanation":"A pentatonic scale uses 5 notes and is found widely in folk and traditional music around the world."},{"question":"Why might a traditional instrument be tied closely to its culture of origin?","options":["Instruments have no connection to culture","Its materials, construction, and playing role often reflect that culture''s history and values","All traditional instruments sound identical","Cultural context doesn''t affect music"],"answerIndex":1,"explanation":"Traditional instruments are often shaped by locally available materials and carry specific cultural or ceremonial roles."}],"apply":{"prompt":"Choose one non-Western instrument or musical tradition (for example, sitar, djembe, gamelan, or mariachi) to research, then try to recreate a simple pattern from it using household objects or an instrument you have.","checklist":["Identified the instrument or tradition and its cultural origin","Described one thing that makes its scale or rhythm distinct from Western pop/classical music","Attempted to play or clap a simple pattern inspired by it"]}}'::jsonb
where type = 'class_topic' and key = 'Music' and meta->>'topic_key' = 'worldFolk';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Where Genres Come From","body":"Jazz grew out of blues and ragtime in early-1900s New Orleans and features improvisation. Rock grew from blues and R&B in the 1950s with electric guitars and drums. Hip-hop began in the 1970s in the Bronx, New York, with DJs, MCs, and rhythmic spoken lyrics over beats."},{"heading":"What Makes Each Genre Sound Different","body":"Genres are shaped by their instruments and rhythms. Jazz often features improvised horn or piano solos over swung rhythms; rock centers electric guitar and drum kit with a strong backbeat; hip-hop centers rhythm and rhyme over sampled or programmed beats; electronic music is built from synthesizers and computer-made sounds."}],"practice":[{"question":"Which genre is especially known for musicians improvising, or making up solos on the spot?","options":["Jazz","Classical","Hip-hop","Electronic"],"answerIndex":0,"explanation":"Improvisation, especially solos over chord changes, is a defining feature of jazz."},{"question":"Hip-hop originated in which city in the 1970s?","options":["New Orleans","The Bronx, New York City","Nashville","Los Angeles"],"answerIndex":1,"explanation":"Hip-hop began in the Bronx in New York City in the 1970s, with DJs and MCs performing over beats."}],"apply":{"prompt":"Listen to one short song from 2 different genres (for example, jazz and hip-hop), and make a chart comparing the instruments, rhythm feel, and vocal style (or lack of vocals) in each.","checklist":["Listened to a full song from each of 2 genres","Identified at least 2 instruments used in each song","Described how the rhythm or beat feels different between the two"]}}'::jsonb
where type = 'class_topic' and key = 'Music' and meta->>'topic_key' = 'popularGenres';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Training Your Ear for Intervals","body":"An interval is the distance between two pitches. Ear training means learning to recognize and name intervals — like a perfect fifth or a major third — by sound alone, often by associating each interval with the opening notes of a familiar song."},{"heading":"Major vs. Minor Chords by Ear","body":"Major chords generally sound bright or happy while minor chords sound darker or sadder, because of a lowered third note. A trained ear can often tell major from minor apart within a couple of seconds, without ever seeing the notation."}],"practice":[{"question":"What is a musical \"interval\"?","options":["A pause between songs","The distance between 2 pitches","A type of chord only","A tempo marking"],"answerIndex":1,"explanation":"An interval is the distance in pitch between two notes."},{"question":"Which best describes the typical emotional character difference between major and minor chords?","options":["Major sounds sad, minor sounds happy","Major typically sounds bright/happy, minor typically sounds darker/sadder","They always sound identical","Only minor chords exist in music"],"answerIndex":1,"explanation":"Because of the lowered third in a minor chord, major chords tend to sound brighter and minor chords tend to sound darker or more melancholy."}],"apply":{"prompt":"Using a piano app or real piano, have a friend play a major chord and a minor chord back to back 5 times without you looking, and try to identify each one by ear only.","checklist":["Practiced telling major from minor by ear at least 5 times","Recorded your accuracy (how many you got right)","Could explain in your own words how each one sounds different"]}}'::jsonb
where type = 'class_topic' and key = 'Music' and meta->>'topic_key' = 'earTraining';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Listening for Form","body":"Musical form is the overall structure or organization of a piece — like verse-chorus form in pop music, or ABA form in classical music. Identifying form means noticing when sections repeat, change, or return."},{"heading":"Texture and Timbre","body":"Texture describes how many \"layers\" are happening at once — monophonic is a single line, homophonic is a melody with accompaniment, and polyphonic is multiple independent melodic lines at once. Timbre is the unique tone color that lets you tell instruments or voices apart even at the same pitch and volume."}],"practice":[{"question":"What does \"musical form\" refer to?","options":["How loud a piece is","The overall structural organization of a piece, such as verse-chorus","The tempo marking","The instrument used"],"answerIndex":1,"explanation":"Form describes the large-scale structure of a piece — how its sections are organized and relate to each other."},{"question":"What is \"timbre\"?","options":["The speed of a piece","The tone color or quality that distinguishes instruments or voices from each other","The loudness of a note","The key signature"],"answerIndex":1,"explanation":"Timbre is the distinct tone quality that lets you tell a violin from a flute even when playing the same pitch and volume."}],"apply":{"prompt":"Listen closely to one song and map out its form (for example, Intro-Verse-Chorus-Verse-Chorus-Bridge-Chorus), noting the timestamp where each section starts.","checklist":["Labeled at least 4 distinct sections with approximate timestamps","Identified which sections repeat","Described the texture (thin/thick, few/many layers) in at least one section"]}}'::jsonb
where type = 'class_topic' and key = 'Music' and meta->>'topic_key' = 'criticalListening';

update public.app_content
set meta = meta || '{"learn":[{"heading":"How Signal Flow Works","body":"Recording signal flow is the path sound travels: from the source (voice or instrument), into a microphone that converts sound into an electrical signal, through a preamp that boosts that signal, into an interface or mixer, and finally into recording software. Understanding this path helps troubleshoot problems."},{"heading":"Mic Placement Matters","body":"Where you place a microphone relative to the sound source changes the recording dramatically. Too close can cause distortion or overly boomy bass (called the proximity effect); too far picks up more room echo and noise. Different mic types, like condenser versus dynamic, suit different situations."}],"practice":[{"question":"What is \"signal flow\" in recording?","options":["The tempo of the song being recorded","The path sound travels from source through mic and equipment into the recording","The volume of the mix","A type of microphone"],"answerIndex":1,"explanation":"Signal flow describes the path an audio signal takes from its source through the microphone, preamp, and interface into the recording software."},{"question":"What can happen if a microphone is placed too close to a sound source?","options":["Nothing changes","It can cause distortion or an overly boomy bass sound (proximity effect)","The recording becomes silent","It automatically improves audio quality"],"answerIndex":1,"explanation":"Placing a mic too close can trigger the proximity effect, causing excess bass buildup or distortion."}],"apply":{"prompt":"Using a phone or any microphone, record the same short phrase (spoken or sung) at 3 different distances from the mic, then listen back and describe how the sound changed.","checklist":["Recorded the same phrase at 3 distinct distances","Listened back and compared the recordings","Described how proximity affected the tone or clarity"]}}'::jsonb
where type = 'class_topic' and key = 'Music' and meta->>'topic_key' = 'recordingTechniques';

update public.app_content
set meta = meta || '{"learn":[{"heading":"What a DAW Does","body":"A Digital Audio Workstation — like GarageBand, Logic, Ableton, or FL Studio — is software for recording, editing, arranging, and mixing audio and MIDI on a computer or tablet. It is essentially the digital equivalent of a whole recording studio."},{"heading":"MIDI vs. Audio","body":"Audio tracks are actual recorded sound waves. MIDI tracks are instructions — which note, how long, how hard — that trigger a virtual instrument to generate sound. That means MIDI can be edited and replayed with a completely different instrument sound after recording."}],"practice":[{"question":"What does DAW stand for?","options":["Digital Audio Workstation","Direct Audio Wire","Digital Amplifier Wave","Data Audio Web"],"answerIndex":0,"explanation":"DAW stands for Digital Audio Workstation, the software used to record, edit, and mix music."},{"question":"What is a key difference between a MIDI track and an audio track?","options":["They are identical","MIDI stores playing instructions (note, length, velocity) rather than recorded sound","Audio tracks cannot be edited","MIDI only works with drums"],"answerIndex":1,"explanation":"MIDI records performance data like which notes were played and how, so it can later be changed or reassigned to a different instrument sound, unlike a recorded audio waveform."}],"apply":{"prompt":"Using a free DAW (GarageBand, BandLab, or similar), create a short 8-16 bar track combining at least one recorded audio track and one MIDI/virtual instrument track.","checklist":["Included at least one recorded audio track","Included at least one MIDI/virtual instrument track","Balanced the volume levels so no track overpowers the others"]}}'::jsonb
where type = 'class_topic' and key = 'Music' and meta->>'topic_key' = 'daws';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Building Sound From Scratch","body":"Synthesis creates sound electronically, usually starting with a basic waveform (sine, square, or sawtooth), then shaping it with filters that cut or boost certain frequencies and envelopes that control how volume changes over time — attack, decay, sustain, and release."},{"heading":"Sampling Uses Existing Sound","body":"Sampling means taking a recorded snippet of real sound — a drum hit, a vocal phrase, an orchestral note — and reusing or manipulating it, like pitching it up or down, looping it, or chopping it, inside new music, rather than generating sound from scratch like synthesis does."}],"practice":[{"question":"What are the four stages of a typical synthesizer envelope, known as ADSR?","options":["Attack, Decay, Sustain, Release","Start, Middle, End, Fade","Loud, Soft, Fast, Slow","Bass, Mid, Treble, Volume"],"answerIndex":0,"explanation":"ADSR stands for Attack, Decay, Sustain, and Release — the four stages describing how a sound''s volume changes over time."},{"question":"What is the main difference between synthesis and sampling?","options":["They are the same technique","Synthesis generates sound electronically from scratch; sampling reuses recorded sound","Sampling can only be used for drums","Synthesis always uses real instrument recordings"],"answerIndex":1,"explanation":"Synthesis builds sound from basic waveforms, while sampling takes and manipulates pre-recorded audio."}],"apply":{"prompt":"Using a free synth app or a DAW''s built-in synthesizer, create one original sound by adjusting the waveform, filter, and ADSR envelope, then separately import or record a short sample and manipulate it (pitch, loop, or chop) in the same project.","checklist":["Created a synthesized sound and adjusted at least 2 parameters (e.g., filter and envelope)","Used a sampled sound and manipulated it in some way","Can explain the difference between the synth sound and the sampled sound in your project"]}}'::jsonb
where type = 'class_topic' and key = 'Music' and meta->>'topic_key' = 'synthesisSampling';

-- ── Enrich remaining Home Economics & Workshop topics (29) ──────────────

update public.app_content
set meta = meta || '{"learn":[{"heading":"The Big Three: Macronutrients","body":"Macronutrients are the nutrients your body needs in large amounts: proteins build and repair muscle, carbohydrates are the body''s main energy source, and fats support hormone production and help absorb certain vitamins. Every food is a mix of these three in different proportions."},{"heading":"The Small but Mighty: Micronutrients","body":"Micronutrients — vitamins and minerals like vitamin C, iron, and calcium — are needed only in small amounts but are essential for things like immune function, strong bones, and healthy blood. A varied diet of fruits, vegetables, proteins, and whole grains is the easiest way to get enough of both macro- and micronutrients."}],"practice":[{"question":"Which of these is a macronutrient?","options":["Vitamin C","Iron","Protein","Calcium"],"answerIndex":2,"explanation":"Protein, along with carbohydrates and fats, is one of the three macronutrients needed in large amounts."},{"question":"What is the main job of carbohydrates in the body?","options":["Building muscle","Providing energy","Fighting infection","Strengthening bones"],"answerIndex":1,"explanation":"Carbohydrates are broken down into glucose, the body''s primary source of energy."}],"apply":{"prompt":"Look at the nutrition label on a food item at home. Identify how many grams of protein, carbohydrates, and fat it contains per serving.","checklist":["Found a food with a nutrition label","Recorded grams of protein","Recorded grams of carbohydrates","Recorded grams of fat"]}}'::jsonb
where type = 'class_topic' and key = 'NutritionAndFood' and meta->>'topic_key' = 'macroMicro';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Plan Before You Shop","body":"A good meal plan starts with picking recipes for the week, checking what you already have, and writing a grocery list organized by store section. This saves money, cuts down on food waste, and avoids last-minute unhealthy choices."},{"heading":"Balance Every Plate","body":"A well-planned meal usually includes a protein, a whole grain or starch, and vegetables or fruit — filling roughly half the plate with produce. Prepping ingredients in batches (like chopping vegetables or cooking rice ahead of time) makes weeknight cooking much faster."}],"practice":[{"question":"What should you do before writing a grocery list?","options":["Go to the store immediately","Check what food you already have at home","Buy only snacks","Skip planning meals"],"answerIndex":1,"explanation":"Checking your pantry and fridge first prevents buying duplicates and reduces food waste."},{"question":"A balanced meal typically fills about half the plate with what?","options":["Dessert","Vegetables or fruit","Bread only","Soda"],"answerIndex":1,"explanation":"Filling half the plate with vegetables or fruit is a simple way to build a balanced, nutrient-rich meal."}],"apply":{"prompt":"Plan one balanced dinner for your family this week: pick a protein, a grain or starch, and a vegetable, then write a short grocery list for it.","checklist":["Chose a protein","Chose a grain or starch","Chose a vegetable or fruit","Wrote a grocery list"]}}'::jsonb
where type = 'class_topic' and key = 'NutritionAndFood' and meta->>'topic_key' = 'mealPlanning';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Dry Heat vs. Moist Heat","body":"Sautéing and roasting are \"dry heat\" methods that use hot pans or oven air to brown food and build flavor quickly. Braising is a \"moist heat\" method that cooks tougher cuts of meat slowly in liquid until they become tender."},{"heading":"Knife Skills Come First","body":"Before you can sauté or braise anything, you need consistent knife cuts — like dicing, mincing, and julienning — so food cooks evenly. Always cut with fingertips curled under (the \"claw grip\") and keep the knife blade away from your body."}],"practice":[{"question":"Which cooking method uses liquid and long, slow cooking to tenderize tough meat?","options":["Sautéing","Braising","Searing only","Deep frying"],"answerIndex":1,"explanation":"Braising combines searing with slow cooking in liquid, which breaks down tough fibers over time."},{"question":"What is the \"claw grip\" used for in knife skills?","options":["Holding the pan handle","Protecting your fingertips while cutting","Sharpening the blade","Stirring sauce"],"answerIndex":1,"explanation":"Curling your fingertips under while gripping the food keeps them safely away from the blade."}],"apply":{"prompt":"With adult supervision, practice the claw grip by dicing one vegetable (like a carrot or bell pepper) into evenly sized pieces.","checklist":["Used the claw grip","Cut pieces roughly the same size","Kept fingertips away from the blade","Had adult supervision"]}}'::jsonb
where type = 'class_topic' and key = 'NutritionAndFood' and meta->>'topic_key' = 'culinaryTechniques';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Restrictions Have Different Causes","body":"Dietary restrictions can come from allergies (an immune reaction that can be life-threatening, like a peanut allergy), intolerances (digestive discomfort, like lactose intolerance), medical needs (like diabetes), or personal/religious choices (like vegetarianism, veganism, halal, or kosher). Understanding the difference matters when cooking for others."},{"heading":"Cultural Cuisine Reflects History","body":"Traditional cuisines developed around the ingredients, climate, and trade routes available in a region — for example, rice-based dishes in much of Asia or corn-based dishes across Latin America. Learning about cultural foods builds respect for the traditions and history behind them, not just the flavors."}],"practice":[{"question":"Which of these is an example of a food allergy rather than a lifestyle choice?","options":["Vegetarianism","A peanut allergy","Following a kosher diet","Veganism"],"answerIndex":1,"explanation":"A peanut allergy is an immune system reaction and can be medically serious, unlike a chosen diet."},{"question":"Why do traditional cuisines often differ so much by region?","options":["Random chance","Available ingredients, climate, and trade history shaped local cooking","All cuisines are actually the same","Governments require it"],"answerIndex":1,"explanation":"What grows locally and what trade brought in over centuries shaped each region''s traditional dishes."}],"apply":{"prompt":"Research one traditional dish from a culture different from your own. Note its main ingredients and one dietary restriction (allergy, intolerance, or religious rule) that would affect whether someone could eat it.","checklist":["Chose a dish from another culture","Listed its main ingredients","Identified a related dietary restriction","Wrote a short summary"]}}'::jsonb
where type = 'class_topic' and key = 'NutritionAndFood' and meta->>'topic_key' = 'specialDiets';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Key Fabric Properties","body":"Fabrics are judged by properties like strength (resistance to tearing), stretch (how much it gives), drape (how it falls or hangs on a body), and texture (smooth, rough, or fuzzy to the touch). A stiff cotton canvas behaves very differently from a flowing silk, even in the same garment shape."},{"heading":"Match Fabric to Function","body":"Choosing fabric means matching properties to the garment''s job — a swimsuit needs stretch and quick-drying fibers, while a winter coat needs warmth and durability. Natural fibers like cotton and wool differ from synthetics like polyester in breathability, stretch, and how they react to washing."}],"practice":[{"question":"Which fabric property describes how a fabric hangs or falls on the body?","options":["Strength","Drape","Texture","Color"],"answerIndex":1,"explanation":"Drape describes how fluidly or stiffly a fabric falls, which affects the silhouette of a garment."},{"question":"Why would a swimsuit fabric need to have good stretch?","options":["To make it stiffer","So it moves with the body and fits snugly","To make it heavier","It does not need stretch"],"answerIndex":1,"explanation":"Stretch allows the fabric to move with the body and maintain a snug, flexible fit while swimming."}],"apply":{"prompt":"Collect three different fabric scraps or clothing items at home. Test and record their strength, stretch, and texture by hand.","checklist":["Gathered three fabric samples","Tested stretch by hand","Noted texture (smooth/rough)","Wrote down which fabric would suit which garment"]}}'::jsonb
where type = 'class_topic' and key = 'TextilesAndApparel' and meta->>'topic_key' = 'fabricProperties';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Stitches Build the Garment","body":"A running stitch is the simplest hand stitch for basic seams, while a backstitch is stronger and used where a seam needs to hold up to stress. Machine stitching uses a straight stitch for most seams and a zigzag stitch to finish raw edges so they don''t fray."},{"heading":"Seams Hold It Together","body":"A seam is where two fabric pieces are joined, and seam allowance (usually 1/2 to 5/8 inch) is the extra fabric left beyond the stitch line so the seam doesn''t pull apart. Garment construction follows an order — like sewing darts and shoulder seams before side seams — so the piece keeps its shape."}],"practice":[{"question":"What is a \"seam allowance\"?","options":["The color of the thread","Extra fabric left beyond the stitch line to prevent the seam from pulling apart","The type of needle used","A decorative stitch"],"answerIndex":1,"explanation":"Seam allowance is the margin of fabric between the stitch line and the raw edge, which keeps the seam secure."},{"question":"Which hand stitch is generally stronger and better for stressed seams?","options":["Running stitch","Backstitch","Loose basting stitch","None, they are all equal"],"answerIndex":1,"explanation":"A backstitch overlaps each stitch, making it much sturdier than a simple running stitch."}],"apply":{"prompt":"Using scrap fabric, needle, and thread (with adult supervision if needed), practice sewing a straight running stitch seam about 4 inches long.","checklist":["Threaded a needle","Sewed a straight running stitch","Kept even stitch spacing","Tied off the thread at the end"]}}'::jsonb
where type = 'class_topic' and key = 'TextilesAndApparel' and meta->>'topic_key' = 'sewingTechniques';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Trends Move in Cycles","body":"Fashion trends often start with designers or subcultures, spread through media and influencers, get mass-produced by retailers, and eventually fade as new trends emerge — many trends also cycle back decades later (like the return of 90s styles). Forecasters study color, fabric, and runway shows years in advance to predict what will be popular."},{"heading":"Design Principles Guide Choices","body":"Elements like line, shape, color, and texture combine with principles like balance, proportion, and emphasis to create a cohesive outfit or collection. For example, a bold accessory can create \"emphasis\" that draws the eye, while repeating a color creates visual \"harmony\" across a look."}],"practice":[{"question":"What does it mean when a fashion trend \"cycles back\"?","options":["It disappears forever","A past style becomes popular again years later","It only happens once","It refers to recycling old clothes"],"answerIndex":1,"explanation":"Many fashion trends fade and later resurface as popular again, often reinterpreted for a new era."},{"question":"Using a bold accessory to draw the eye to one part of an outfit is an example of which design principle?","options":["Balance","Emphasis","Repetition","Rhythm"],"answerIndex":1,"explanation":"Emphasis is the design principle used to create a focal point that draws attention."}],"apply":{"prompt":"Create a simple mood board (drawn, printed, or digital) for an outfit idea using one color palette and one design principle (like emphasis or balance).","checklist":["Chose a color palette","Applied one design principle","Included at least 3 outfit elements","Explained your choices in a sentence"]}}'::jsonb
where type = 'class_topic' and key = 'TextilesAndApparel' and meta->>'topic_key' = 'fashionDesign';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Read the Care Label","body":"Clothing care labels use symbols to tell you how to wash, dry, and iron a garment safely — a picture of a washtub with an X means do not wash by machine, and a triangle with an X means do not use bleach. Always check the label before washing, especially for delicate or new items."},{"heading":"Storage Protects Fabric","body":"Folding sweaters instead of hanging them prevents stretching at the shoulders, and keeping clothes out of direct sunlight prevents fading. Cedar blocks or sachets help keep moths away from wool and other natural fibers in storage."}],"practice":[{"question":"What does a washtub symbol with an X through it on a care label mean?","options":["Wash in hot water","Do not machine wash","Iron on high heat","Dry clean only"],"answerIndex":1,"explanation":"An X through the washtub symbol means the item should not be machine washed."},{"question":"Why should sweaters usually be folded instead of hung on a hanger?","options":["Folding uses less space","Hanging can stretch out the shoulders over time","Folded sweaters look nicer","It does not matter"],"answerIndex":1,"explanation":"The weight of a sweater pulling on a hanger can stretch and distort the shoulder shape over time."}],"apply":{"prompt":"Find three clothing items at home and check their care labels. Write down what each symbol tells you about how to wash or dry it.","checklist":["Found 3 items with care labels","Identified the washing symbol","Identified the drying symbol","Noted any special warnings (like no bleach)"]}}'::jsonb
where type = 'class_topic' and key = 'TextilesAndApparel' and meta->>'topic_key' = 'textileCare';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Development Happens in Stages","body":"Humans move through recognizable life stages — infancy, early childhood, adolescence, adulthood, and older age — each with its own physical, emotional, and social milestones, like learning to walk in infancy or forming identity in adolescence. Development doesn''t stop at any one age; people keep growing emotionally and socially throughout life."},{"heading":"Relationships Take Many Forms","body":"Family, friendship, and romantic relationships each serve different needs and involve different levels of trust and commitment. Healthy relationships of any type share common traits — honest communication, mutual respect, and support during difficult times."}],"practice":[{"question":"During which life stage does forming a personal identity become a major focus?","options":["Infancy","Adolescence","Only old age","It never happens"],"answerIndex":1,"explanation":"Adolescence is widely recognized as the stage where identity formation becomes a central developmental task."},{"question":"Which of these is a trait shared by healthy relationships, regardless of type?","options":["Constant arguing","Mutual respect","Avoiding all communication","One person controlling the other"],"answerIndex":1,"explanation":"Mutual respect is a foundation of healthy relationships whether they are family, friendship, or romantic."}],"apply":{"prompt":"Interview a family member from a different generation than you (a parent, grandparent, or older sibling) about one milestone from their life stage at your current age.","checklist":["Chose a family member to interview","Asked about a milestone at your current age","Took notes on their answer","Compared it briefly to your own experience"]}}'::jsonb
where type = 'class_topic' and key = 'FamilyAndHumanDevelopment' and meta->>'topic_key' = 'lifeStages';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Consistency Builds Security","body":"Effective parenting strategies emphasize consistency — clear, predictable rules and consequences help children feel secure and understand expectations. Positive reinforcement (praising good behavior) tends to be more effective long-term than only punishing bad behavior."},{"heading":"Milestones Guide Expectations","body":"Child development milestones — like a baby smiling around 2 months, walking around 12 months, or speaking in sentences around age 3 — give caregivers a general guide, but every child develops at their own pace within a normal range. Recognizing these milestones helps caregivers know when extra support might be needed."}],"practice":[{"question":"Why is consistency important in parenting strategies?","options":["It makes parenting easier for the parent only","It helps children feel secure and understand expectations","It has no real effect","It is only needed for teenagers"],"answerIndex":1,"explanation":"Predictable rules and responses help children feel safe and learn what is expected of them."},{"question":"What are developmental milestones used for?","options":["Punishing children who are behind","Giving a general guide to typical growth and development","Comparing children competitively","Replacing parental instinct entirely"],"answerIndex":1,"explanation":"Milestones are a general reference range, helping caregivers recognize typical progress and possible areas needing support."}],"apply":{"prompt":"Research three developmental milestones typical for a specific age (choose an age between 1 and 5 years old) and write a short summary of what a caregiver might expect to see.","checklist":["Chose a specific age","Listed three milestones","Cited where you found the information","Wrote a short summary"]}}'::jsonb
where type = 'class_topic' and key = 'FamilyAndHumanDevelopment' and meta->>'topic_key' = 'parentingChildDev';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Aging Well Involves the Whole Person","body":"Healthy aging includes staying physically active, eating well, keeping the mind engaged, and maintaining social connections — isolation is one of the biggest risk factors for declining health in older adults. Regular checkups help catch and manage age-related conditions like high blood pressure or vision changes early."},{"heading":"Home Safety Prevents Falls","body":"Falls are a leading cause of injury for older adults, so elder care often focuses on reducing hazards: securing rugs, adding grab bars in bathrooms, improving lighting, and clearing walkways of clutter. Simple home modifications can significantly lower fall risk and help older adults stay independent longer."}],"practice":[{"question":"Which of these is a major risk factor for declining health in older adults?","options":["Regular checkups","Social isolation","Staying physically active","Eating balanced meals"],"answerIndex":1,"explanation":"Social isolation is strongly linked to declining physical and mental health in older adults."},{"question":"What is a simple home modification that helps prevent falls?","options":["Adding more loose rugs","Installing grab bars in the bathroom","Turning off hallway lights","Removing handrails"],"answerIndex":1,"explanation":"Grab bars provide extra support in areas like bathrooms where falls are common, especially on wet floors."}],"apply":{"prompt":"Walk through your home (or a relative''s home) with an adult and identify two potential fall hazards for an older adult, then suggest a fix for each.","checklist":["Identified hazard #1","Suggested a fix for hazard #1","Identified hazard #2","Suggested a fix for hazard #2"]}}'::jsonb
where type = 'class_topic' and key = 'FamilyAndHumanDevelopment' and meta->>'topic_key' = 'agingElderCare';

update public.app_content
set meta = meta || '{"learn":[{"heading":"A Place for Everything","body":"Home organization works best when every item has a specific \"home\" — a designated spot it always returns to — so things are easy to find and put away. Grouping similar items together (like all school supplies in one bin) makes cleanup faster and keeps clutter from spreading."},{"heading":"Time Management Uses Simple Tools","body":"A daily or weekly checklist helps break big chores into small, manageable steps, and doing a little bit each day (like making your bed or tidying one shelf) is easier than one huge cleaning session. Setting a timer for a task, like 10 minutes of tidying, can make chores feel less overwhelming."}],"practice":[{"question":"What does it mean to give an item a \"home\" in an organized space?","options":["Throwing it away","Giving it one designated spot it always returns to","Hiding it in a random drawer","Buying a new one each time"],"answerIndex":1,"explanation":"A designated spot for each item makes it quick to find and easy to put away, keeping spaces tidy."},{"question":"What is one benefit of using a timer for a cleaning task?","options":["It makes the task take longer","It can make the task feel more manageable and less overwhelming","It has no effect","It replaces the need to clean"],"answerIndex":1,"explanation":"Breaking a chore into a short, timed burst makes it feel achievable rather than overwhelming."}],"apply":{"prompt":"Pick one messy area at home (a desk, drawer, or shelf) and organize it in 15 minutes, giving each item a designated spot.","checklist":["Picked one messy area","Set a 15-minute timer","Grouped similar items together","Gave each item a specific spot"]}}'::jsonb
where type = 'class_topic' and key = 'HouseholdAndResourceManagement' and meta->>'topic_key' = 'homeOrganization';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Function Before Décor","body":"Good interior design starts with how a room will be used — furniture placement should support traffic flow and daily activities before adding decorative elements like color or artwork. A common rule is leaving at least 30 inches of walking space in main pathways."},{"heading":"Housing Options Have Tradeoffs","body":"Renting an apartment offers flexibility and fewer maintenance responsibilities, while owning a house builds equity but comes with property taxes, repairs, and a bigger upfront cost. Comparing housing options means weighing cost, location, space needs, and long-term goals."}],"practice":[{"question":"What should be considered first when arranging furniture in a room?","options":["Wall paint color","How the room will be used and traffic flow","The most expensive furniture piece","Matching curtains"],"answerIndex":1,"explanation":"Function and traffic flow should guide furniture placement before decorative choices are made."},{"question":"What is one advantage of renting over owning a home?","options":["Building equity","More flexibility and fewer maintenance responsibilities","Lower total lifetime cost","Unlimited customization"],"answerIndex":1,"explanation":"Renters typically are not responsible for major repairs and can move more easily than homeowners."}],"apply":{"prompt":"Sketch a simple floor plan for your bedroom or living room, showing furniture placement that keeps at least 30 inches of walking space in the main path.","checklist":["Sketched the room outline","Placed furniture on the sketch","Marked a clear walking path","Checked the path is wide enough"]}}'::jsonb
where type = 'class_topic' and key = 'HouseholdAndResourceManagement' and meta->>'topic_key' = 'interiorDesign';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Small Habits, Big Impact","body":"Environmental sustainability at home means using resources — water, energy, materials — in ways that don''t deplete them for the future. Simple habits like turning off lights when leaving a room, taking shorter showers, and unplugging unused electronics reduce both waste and utility bills."},{"heading":"Energy Conservation Targets the Biggest Users","body":"Heating and cooling systems typically use the most energy in a home, so sealing drafts around windows and doors and adjusting the thermostat a few degrees can save significant energy. Switching to LED light bulbs uses up to 75% less energy than older incandescent bulbs."}],"practice":[{"question":"Which home system typically uses the most energy overall?","options":["Lighting","Heating and cooling","Phone chargers","Doorbells"],"answerIndex":1,"explanation":"Heating and cooling systems are usually the largest energy consumers in a home."},{"question":"About how much less energy do LED bulbs use compared to older incandescent bulbs?","options":["About 5%","About 25%","Up to 75%","They use the same amount"],"answerIndex":2,"explanation":"LED bulbs are far more efficient, using up to about 75% less energy than incandescent bulbs."}],"apply":{"prompt":"Do a simple energy audit of one room in your home: count the light bulbs, note if any are LED, and check for drafts around one window or door.","checklist":["Counted light bulbs in the room","Noted bulb type (LED or not)","Checked for drafts","Suggested one improvement"]}}'::jsonb
where type = 'class_topic' and key = 'HouseholdAndResourceManagement' and meta->>'topic_key' = 'sustainability';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Everyday Hygiene Habits","body":"Washing your hands with soap for 20 seconds, brushing your teeth twice a day, and taking a bath or shower regularly are simple habits that keep germs away and help your body stay healthy. These habits are most helpful when they become part of your daily routine, like right after using the bathroom or before eating."},{"heading":"Self-Care Means Taking Care of You","body":"Self-care includes getting enough sleep, eating healthy food, and taking time to rest or play — it helps your body and mind feel good. Asking a grown-up for help when you''re not feeling well or need new hygiene supplies is part of taking care of yourself too."}],"practice":[{"question":"How long should you wash your hands with soap to clean them well?","options":["2 seconds","About 20 seconds","1 minute","You don''t need soap"],"answerIndex":1,"explanation":"Washing with soap for about 20 seconds — roughly the time it takes to hum a short song twice — helps remove germs effectively."},{"question":"Which of these is an example of self-care?","options":["Skipping meals","Getting enough sleep","Staying up all night","Ignoring when you feel sick"],"answerIndex":1,"explanation":"Getting enough sleep helps your body and mind rest and stay healthy, making it an important self-care habit."}],"apply":{"prompt":"With a grown-up, make a simple daily hygiene checklist (like washing hands, brushing teeth, and bathing) and check it off for one full day.","checklist":["Made a hygiene checklist","Included hand washing","Included teeth brushing","Checked off each item for one day"]}}'::jsonb
where type = 'class_topic' and key = 'HealthAndWellness' and meta->>'topic_key' = 'personalHygiene';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Stress Has Warning Signs","body":"Stress can show up as physical signs (headaches, trouble sleeping), emotional signs (feeling irritable or overwhelmed), or behavioral signs (avoiding friends, changes in appetite). Recognizing these early signs helps you respond before stress builds up too much."},{"heading":"Coping Strategies That Actually Help","body":"Techniques like deep breathing, physical activity, talking to a trusted friend or adult, and breaking big problems into smaller steps can reduce stress in healthy ways. It''s normal to need support sometimes — reaching out to a counselor, teacher, or trusted adult is a sign of strength, not weakness."}],"practice":[{"question":"Which of these is a physical sign of stress?","options":["Trouble sleeping","Getting straight A''s","Feeling well-rested","Having no opinions"],"answerIndex":0,"explanation":"Stress often shows up physically, including through sleep problems, headaches, or fatigue."},{"question":"What is a healthy way to cope with stress?","options":["Bottling up feelings and avoiding everyone","Talking to a trusted friend or adult","Ignoring the problem completely","Skipping sleep to worry more"],"answerIndex":1,"explanation":"Talking to someone you trust is a healthy coping strategy that can help you process stress and find solutions."}],"apply":{"prompt":"The next time you feel stressed this week, try one coping technique (deep breathing, a short walk, or talking to someone) and write a sentence about how it made you feel.","checklist":["Noticed a stressful moment","Tried one coping technique","Wrote how it felt before","Wrote how it felt after"]}}'::jsonb
where type = 'class_topic' and key = 'HealthAndWellness' and meta->>'topic_key' = 'stressManagement';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Check, Call, Care","body":"The basic first aid sequence is: check the scene and person for danger, call for help (an adult or 911) if it''s serious, and care for the injury using safe, simple steps. For a minor cut, that means washing your hands, rinsing the wound, applying pressure to stop bleeding, and covering it with a clean bandage."},{"heading":"Know When to Get an Adult","body":"Small scrapes and minor burns can often be treated with basic first aid, but deep cuts, heavy bleeding, burns that blister badly, or any injury involving trouble breathing always need an adult or emergency services right away. First aid is about helping safely — it''s never worth risking your own safety to help someone else."}],"practice":[{"question":"What is the correct first step when treating a minor cut?","options":["Cover it immediately without cleaning","Wash your hands before touching the wound","Ignore it","Apply a bandage over dirt"],"answerIndex":1,"explanation":"Washing your hands first helps prevent introducing germs into the wound."},{"question":"When should you always get an adult for help with an injury?","options":["For any small paper cut","When there is heavy bleeding or trouble breathing","Only if it doesn''t hurt","Never, kids should always handle it alone"],"answerIndex":1,"explanation":"Serious signs like heavy bleeding or breathing trouble mean it is time to get an adult or call emergency services immediately."}],"apply":{"prompt":"With an adult, find or put together a basic first aid kit at home and identify what each item is used for (bandages, antiseptic wipes, gauze, etc.).","checklist":["Located or assembled a first aid kit","Identified at least 4 items","Explained what each item is for","Checked with an adult where the kit is stored"]}}'::jsonb
where type = 'class_topic' and key = 'HealthAndWellness' and meta->>'topic_key' = 'firstAid';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Measure Twice, Cut Once","body":"Accurate woodworking starts with precise measuring and marking — using a tape measure, square, and pencil to mark cut lines clearly before touching a saw. The old rule \"measure twice, cut once\" exists because wood cut too short can''t be uncut, so double-checking measurements saves material and time."},{"heading":"Joinery Holds Wood Together","body":"Joinery is how two pieces of wood are connected — simple butt joints are easy but weaker, while interlocking joints like dovetails or dados are stronger and don''t rely only on glue or nails. Finishing with sanding, stain, or sealant protects the wood from moisture and wear after the piece is built."}],"practice":[{"question":"Why do woodworkers follow the rule \"measure twice, cut once\"?","options":["To waste time","Because a board cut too short cannot be uncut","Because saws are inaccurate","It is just a superstition"],"answerIndex":1,"explanation":"A mismeasured cut wastes material, so double-checking before cutting prevents costly mistakes."},{"question":"What is the purpose of a wood joint like a dovetail?","options":["To make the wood a different color","To create a strong mechanical connection between two pieces","To weaken the wood on purpose","To replace the need for sanding"],"answerIndex":1,"explanation":"Interlocking joints like dovetails create strong connections that hold pieces together without relying solely on glue or nails."}],"apply":{"prompt":"With adult supervision, measure and mark a cut line on a piece of scrap wood using a tape measure and square, checking the measurement twice before marking.","checklist":["Used a tape measure to find the length","Used a square to mark a straight line","Double-checked the measurement","Had adult supervision"]}}'::jsonb
where type = 'class_topic' and key = 'MaterialWorking' and meta->>'topic_key' = 'woodworking';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Metal Properties Guide the Process","body":"Different metals behave differently under heat and force — steel is strong and can be welded, aluminum is lighter and resists rust but has a lower melting point, and copper conducts electricity and heat well. Choosing the right metal depends on the project''s strength, weight, and corrosion needs."},{"heading":"Joining Methods Vary in Strength","body":"Welding melts metal pieces together at their edges to form a permanent, very strong bond, while soldering uses a lower-temperature filler metal to join pieces without melting them — common for electronics or small joints. Safety gear like face shields, heat-resistant gloves, and proper ventilation is essential any time metal is heated or cut."}],"practice":[{"question":"What is a key difference between welding and soldering?","options":["They are the same process","Welding melts the base metal itself; soldering uses a lower-temperature filler metal","Soldering is only used on steel","Welding never requires safety gear"],"answerIndex":1,"explanation":"Welding fuses the actual metal pieces together, while soldering joins them with a separate melted filler metal at a lower temperature."},{"question":"Why might aluminum be chosen over steel for a project?","options":["It is heavier","It is lighter and resists rust","It cannot be shaped","It is always cheaper"],"answerIndex":1,"explanation":"Aluminum is prized for being lightweight and naturally resistant to rust compared to steel."}],"apply":{"prompt":"Research two metals (like steel and aluminum) and compare their strength, weight, and rust resistance in a short chart.","checklist":["Chose two metals to compare","Compared their strength","Compared their weight","Compared their rust resistance"]}}'::jsonb
where type = 'class_topic' and key = 'MaterialWorking' and meta->>'topic_key' = 'metalworking';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Lathes Spin, Mills Cut","body":"A lathe spins a piece of metal rapidly while a cutting tool shapes it from the outside, ideal for making round parts like shafts or bolts. A mill instead spins the cutting tool itself and moves it across a stationary workpiece, making it useful for flat surfaces, slots, and precise holes."},{"heading":"Precision Requires Careful Setup","body":"Basic machining relies on precise measurement tools like calipers and micrometers to check that a part matches the design within tiny tolerances, sometimes as small as a thousandth of an inch. Machines spin or move very fast and can catch loose clothing, jewelry, or hair, so proper PPE and following safety procedures is critical before ever turning a machine on."}],"practice":[{"question":"What is the main difference between a lathe and a mill?","options":["A lathe spins the workpiece; a mill spins the cutting tool","They are the exact same machine","A mill only works on wood","A lathe cannot make round parts"],"answerIndex":0,"explanation":"A lathe rotates the workpiece against a fixed tool, while a mill rotates the cutting tool over a stationary workpiece."},{"question":"Why is loose clothing or jewelry dangerous near a lathe or mill?","options":["It can get caught in the spinning machine parts","It makes the machine slower","It has no safety impact","It only matters for wood machines"],"answerIndex":0,"explanation":"Fast-spinning machine parts can catch loose clothing, jewelry, or hair, leading to serious injury."}],"apply":{"prompt":"Research the difference between a lathe and a milling machine, then sketch or describe one small part you could make with each and why that machine fits the job.","checklist":["Described what a lathe does","Described what a mill does","Sketched or described a lathe project","Sketched or described a milling project"]}}'::jsonb
where type = 'class_topic' and key = 'MaterialWorking' and meta->>'topic_key' = 'basicMachining';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Blueprints Speak a Visual Language","body":"Blueprints use standardized symbols and lines — like solid lines for walls, dashed lines for hidden features, and specific symbols for doors, windows, and electrical outlets — so any builder can read the same plan the same way. A scale (like 1/4 inch = 1 foot) tells you how the drawing''s measurements relate to the real, full-size structure."},{"heading":"Sketching Plans Before Building","body":"Hand sketches let builders and designers quickly explore layout ideas before committing to a formal, precise blueprint, using simple tools like graph paper, a ruler, and a pencil. Getting comfortable sketching to scale — even roughly — helps you catch spacing problems early, before construction begins."}],"practice":[{"question":"On a blueprint, what does a dashed line typically represent?","options":["A visible wall","A hidden feature, like something behind another structure","The scale of the drawing","A colored accent"],"answerIndex":1,"explanation":"Dashed lines are a standard blueprint convention showing features that are hidden from the current view."},{"question":"What does a blueprint scale of 1/4 inch = 1 foot tell you?","options":["The drawing is full size","Every 1/4 inch on paper represents 1 real foot","The building is 1/4 foot tall","It has no relationship to real measurements"],"answerIndex":1,"explanation":"A scale defines the ratio between the drawing''s measurements and the actual size of the structure."}],"apply":{"prompt":"Using graph paper, sketch a simple floor plan of one room in your home, choosing a scale (like 1 square = 1 foot) and labeling doors and windows.","checklist":["Chose and noted a scale","Drew the room outline to scale","Labeled at least one door","Labeled at least one window"]}}'::jsonb
where type = 'class_topic' and key = 'Construction' and meta->>'topic_key' = 'blueprintReading';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Framing Creates the Skeleton","body":"Framing is the wood or metal skeleton of a building — studs form vertical wall supports spaced at regular intervals (commonly 16 inches apart), joists support floors, and rafters or trusses form the roof structure. This skeleton carries the building''s loads down to the foundation."},{"heading":"Loads Must Travel Down Safely","body":"Structural framing has to transfer weight — from the roof, through walls, down to the foundation — without any weak points, which is why headers (extra-strong beams) are placed above doors and windows to redirect the load around the opening. Understanding load paths is what separates a load-bearing wall (structural) from a non-load-bearing wall (just a divider)."}],"practice":[{"question":"What is the typical spacing for wall studs in standard framing?","options":["16 inches apart","10 feet apart","1 inch apart","There is no standard spacing"],"answerIndex":0,"explanation":"16 inches on center is a very common standard spacing for wall studs in residential framing."},{"question":"What is the purpose of a header above a door or window opening?","options":["Decoration only","To redirect structural load around the opening","To block sound","To hold up the roof shingles"],"answerIndex":1,"explanation":"A header is a strong beam that carries the load from above and transfers it around the opening to the studs on either side."}],"apply":{"prompt":"Look at a wall in your home (or photos of a house under construction) and try to identify where studs likely are, using the standard 16-inch spacing as a guide (you can look for outlet or switch locations as clues).","checklist":["Chose a wall to examine","Estimated stud spacing","Noted any clues used (outlets, trim, etc.)","Sketched your findings"]}}'::jsonb
where type = 'class_topic' and key = 'Construction' and meta->>'topic_key' = 'framingStructural';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Drywall Needs Multiple Steps","body":"Installing drywall involves hanging panels on the wall framing, then taping the seams and applying joint compound in several thin coats, sanding smooth between coats, before it''s ready to paint. Rushing the drying and sanding steps is the most common reason drywall seams show through paint later."},{"heading":"Finishing Work Is the Final Layer","body":"Flooring and trim carpentry (like baseboards and door casings) are usually the last steps in a project because they finish and protect the edges where other materials meet. Choosing flooring means balancing durability, water resistance, and cost — vinyl and tile handle moisture well, while hardwood offers a classic look but needs more care."}],"practice":[{"question":"Why do drywall installers apply joint compound in several thin coats instead of one thick coat?","options":["To waste material","Thin coats dry and sand more evenly, preventing seams from showing later","It is required by law","Thick coats are illegal"],"answerIndex":1,"explanation":"Multiple thin coats dry more evenly and sand smoother, which prevents visible seams once painted."},{"question":"Why is trim carpentry like baseboards usually installed near the end of a project?","options":["It has to go first","It finishes and covers the edges where other materials meet","Trim is never actually needed","It has nothing to do with other materials"],"answerIndex":1,"explanation":"Trim covers transitions and gaps between materials like flooring and walls, so it goes on after those are in place."}],"apply":{"prompt":"Compare two flooring materials (like vinyl and hardwood) for a room in your home, noting which handles moisture better and which costs more.","checklist":["Chose two flooring materials","Compared moisture resistance","Compared approximate cost","Picked which would suit a specific room and why"]}}'::jsonb
where type = 'class_topic' and key = 'Construction' and meta->>'topic_key' = 'finishingWork';

update public.app_content
set meta = meta || '{"learn":[{"heading":"The Four-Stroke Cycle","body":"Most car engines run on a four-stroke cycle: intake (fuel and air enter the cylinder), compression (the piston squeezes the mixture), combustion (a spark ignites it, pushing the piston down for power), and exhaust (spent gases leave). This cycle repeats hundreds of times per minute to keep the car moving."},{"heading":"Maintenance Prevents Bigger Problems","body":"Routine maintenance like changing the oil, checking coolant levels, and replacing air filters keeps an engine running smoothly and prevents expensive damage — motor oil lubricates moving parts and breaks down over time, so most vehicles need it changed every 5,000-7,500 miles. Ignoring warning lights or unusual noises can turn a small, cheap fix into a major repair."}],"practice":[{"question":"What are the four strokes of a standard car engine cycle, in order?","options":["Exhaust, compression, intake, combustion","Intake, compression, combustion, exhaust","Combustion, intake, exhaust, compression","Compression, exhaust, intake, combustion"],"answerIndex":1,"explanation":"The four-stroke cycle runs intake, compression, combustion, then exhaust, in that repeating order."},{"question":"Why does motor oil need to be changed regularly?","options":["It changes color for fun","It breaks down over time and loses its ability to lubricate properly","Cars run better with less oil","It has no real function"],"answerIndex":1,"explanation":"Oil degrades with heat and use, so regular changes keep engine parts properly lubricated and protected."}],"apply":{"prompt":"With an adult, check your family car''s owner''s manual (or look up the model online) to find the recommended oil change interval and what type of oil it uses.","checklist":["Found the owner''s manual or looked up the model","Noted the recommended oil change interval","Noted the oil type recommended","Checked when the car was last serviced, if known"]}}'::jsonb
where type = 'class_topic' and key = 'Automotive' and meta->>'topic_key' = 'engineFundamentals';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Brakes Convert Motion to Heat","body":"Most cars use disc brakes, where a caliper squeezes brake pads against a spinning rotor, using friction to slow the wheel — this friction converts the car''s motion into heat. Brake pads wear down over time and need replacement, often signaled by a squealing sound when the pads get thin."},{"heading":"Suspension and Steering Work Together","body":"The suspension system (springs, shocks, and struts) absorbs bumps in the road and keeps tires in contact with the pavement, while the steering system translates the driver turning the wheel into the front tires actually turning. Worn suspension parts can cause a bouncy ride or uneven tire wear, both signs it''s time for an inspection."}],"practice":[{"question":"What happens when disc brakes are applied?","options":["A caliper squeezes pads against a rotor to create friction","The engine automatically shuts off","The steering wheel locks","Nothing physical happens"],"answerIndex":0,"explanation":"Disc brakes work by squeezing pads against a spinning rotor, using friction to slow the wheel."},{"question":"What is one common sign that a car''s suspension may be worn?","options":["A perfectly smooth, quiet ride","A bouncy ride or uneven tire wear","Better fuel economy","Brighter headlights"],"answerIndex":1,"explanation":"Worn suspension components often cause a bouncy ride and can lead to uneven tire wear over time."}],"apply":{"prompt":"With an adult, inspect one tire on a family vehicle and check the tread wear pattern — even wear across the tire is a good sign, while wear only on one edge may signal a suspension or alignment issue.","checklist":["Inspected one tire with an adult","Checked the tread wear pattern","Noted whether wear looked even or uneven","Discussed findings with the adult"]}}'::jsonb
where type = 'class_topic' and key = 'Automotive' and meta->>'topic_key' = 'brakeSteering';

update public.app_content
set meta = meta || '{"learn":[{"heading":"The Battery Powers the System","body":"A car battery provides the electrical power to start the engine and run electronics when the engine is off, while the alternator recharges the battery and powers the electrical system once the engine is running. A weak battery is one of the most common reasons a car won''t start, especially in cold weather."},{"heading":"Diagnosing Starts with a Multimeter","body":"Technicians use a multimeter to check voltage at the battery and connections, helping pinpoint whether a problem is a dead battery, a bad connection (like corroded terminals), or a failing alternator. Following wiring diagrams carefully matters because auto electrical systems carry enough current to cause sparks, burns, or damage if shorted incorrectly."}],"practice":[{"question":"What is the main job of the alternator in a car''s electrical system?","options":["To start the engine only","To recharge the battery and power electronics while the engine runs","To steer the car","To cool the engine"],"answerIndex":1,"explanation":"The alternator generates electricity while the engine runs, recharging the battery and powering the car''s electrical systems."},{"question":"What tool do technicians commonly use to check a car''s electrical voltage?","options":["A wrench","A multimeter","A tire gauge","A screwdriver"],"answerIndex":1,"explanation":"A multimeter measures voltage, current, and resistance, making it the standard tool for diagnosing electrical issues."}],"apply":{"prompt":"With an adult, locate the battery in a family car and check the terminals for any visible corrosion (a white or greenish crusty buildup).","checklist":["Located the battery with an adult","Checked both terminals","Noted whether corrosion was present","Reported findings to the adult"]}}'::jsonb
where type = 'class_topic' and key = 'Automotive' and meta->>'topic_key' = 'electricalDiagnostics';

update public.app_content
set meta = meta || '{"learn":[{"heading":"PPE Matches the Hazard","body":"Different tools create different dangers, so PPE is chosen to match: safety goggles protect eyes from flying wood chips or metal shavings, gloves protect hands from sharp edges or splinters, and ear protection guards against hearing damage from loud power tools. Wearing the wrong or no PPE for a task is one of the most common causes of workshop injuries."},{"heading":"Clothing Matters Too","body":"Loose sleeves, dangling jewelry, or untied long hair can get caught in moving tools like drills or saws, so proper workshop clothing means snug sleeves, no dangling accessories, and hair tied back. Closed-toe shoes protect feet from dropped tools or materials."}],"practice":[{"question":"Which piece of PPE protects your eyes from flying wood chips or metal shavings?","options":["Ear protection","Safety goggles","Gloves","Closed-toe shoes"],"answerIndex":1,"explanation":"Safety goggles create a barrier that protects the eyes from flying debris produced by many shop tools."},{"question":"Why should loose sleeves or dangling jewelry be avoided in a workshop?","options":["They look unprofessional","They can get caught in moving tool parts","They make tools slower","They have no safety impact"],"answerIndex":1,"explanation":"Loose clothing or jewelry can be pulled into spinning or moving tool parts, causing serious injury."}],"apply":{"prompt":"Before your next workshop or craft activity, put together the correct PPE (like goggles and gloves) for the task and have an adult check that your clothing and hair are secured safely.","checklist":["Identified PPE needed for the task","Put on goggles or gloves as needed","Secured loose hair or sleeves","Had an adult check your setup"]}}'::jsonb
where type = 'class_topic' and key = 'ToolSafetyAndShopPractices' and meta->>'topic_key' = 'ppe';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Clean and Sharp Tools Are Safer Tools","body":"A dull blade or bit actually requires more force to use, which increases the chance of slipping and causing injury — regularly sharpening cutting tools keeps them working safely and efficiently. Wiping tools clean after each use, especially removing sawdust or moisture, prevents rust and keeps them working longer."},{"heading":"Organization Saves Time and Prevents Accidents","body":"Storing tools in a designated spot — like a pegboard, labeled drawer, or toolbox — means you always know where to find them and can quickly spot if one is missing. A cluttered workspace with tools scattered on the floor is a tripping hazard and makes it easy to accidentally step on or grab something sharp."}],"practice":[{"question":"Why is a dull cutting tool actually more dangerous than a sharp one?","options":["Dull tools never need force","It requires more force to use, increasing the chance of it slipping","Dull tools are always locked away","There is no safety difference"],"answerIndex":1,"explanation":"A dull tool needs more force to cut, which raises the risk of it slipping and causing an injury."},{"question":"What is one benefit of storing tools in a labeled, designated spot?","options":["It makes tools rust faster","You always know where to find them and can spot if one is missing","It has no real benefit","It hides tools from being used at all"],"answerIndex":1,"explanation":"Designated storage keeps a workspace organized, saves time searching, and helps you notice a missing tool right away."}],"apply":{"prompt":"With an adult, clean and inspect one hand tool at home (like a hammer or screwdriver), checking for rust or damage, then find or create a proper storage spot for it.","checklist":["Cleaned the tool","Checked for rust or damage","Reported any damage to an adult","Stored the tool in a designated spot"]}}'::jsonb
where type = 'class_topic' and key = 'ToolSafetyAndShopPractices' and meta->>'topic_key' = 'maintenanceOrganization';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Ergonomics Reduces Strain","body":"Good workshop ergonomics means setting workbench height so you don''t have to hunch over, positioning frequently used tools within easy reach, and taking breaks during repetitive tasks to avoid muscle strain. Standing with a stable, balanced stance while using tools also reduces fatigue and improves control."},{"heading":"Clean-Up Is Part of the Job","body":"A tidy workspace isn''t just about appearance — sawdust, scraps, and spilled liquids on the floor create slip and fire hazards, so cleaning as you go (not just at the end) keeps a shop safer throughout the whole project. Returning tools to their storage spot immediately after use prevents them from becoming tripping hazards or getting lost."}],"practice":[{"question":"Why should a workbench be set to an appropriate height?","options":["It has no effect on the body","To prevent hunching over and reduce strain on the back","To make tools harder to reach","Only for decoration"],"answerIndex":1,"explanation":"A properly set workbench height helps maintain good posture and reduces physical strain during long tasks."},{"question":"Why is cleaning up sawdust and scraps during a project important, not just at the end?","options":["It slows down the work for no reason","It reduces slip and fire hazards throughout the project","Sawdust is not a hazard","Clean-up should only happen once a year"],"answerIndex":1,"explanation":"Ongoing clean-up keeps the workspace safe throughout the project instead of letting hazards build up."}],"apply":{"prompt":"Set up a small workstation for a task (like a desk or table) at a height where your elbows are roughly level with the work surface, and practice cleaning up scraps immediately after finishing.","checklist":["Adjusted or checked workstation height","Positioned tools within easy reach","Completed a short task","Cleaned up immediately afterward"]}}'::jsonb
where type = 'class_topic' and key = 'ToolSafetyAndShopPractices' and meta->>'topic_key' = 'ergonomicsCleanup';

