insert into public.app_content (type, key, title, body, meta, sort_order) values
  ('class_topic', 'TechnologyAndEngineering', 'Algorithms & Sequencing', 'An algorithm is a step-by-step set of instructions to finish a task. Computers need instructions in the exact right order — this is an introduction to sequencing through everyday, unplugged examples.', '{"grade":"K-2","color":"#FF6B6B","help":{"videos":[{"title":"What are Algorithms? | Computer Science for Kids Part 5 | Grades K-2","url":"https://www.youtube.com/watch?v=578hB0E6y4o"},{"title":"Sequencing - Coding Concepts Explained for Kids","url":"https://www.youtube.com/watch?v=QbhQ6G61SMs"}]},"topic_key":"algorithmsSequencing","learn":[{"heading":"What Is an Algorithm?","body":"An algorithm is just a set of steps, done in order, to get something done — like a recipe for a cake, or the steps to brush your teeth. If you skip a step or do them in the wrong order, it doesn''t work right."},{"heading":"Order Matters","body":"Putting on socks before shoes works — putting on shoes before socks doesn''t! Sequencing means thinking carefully about which step has to happen first, second, and last."}],"practice":[{"question":"Put these steps in order to put on shoes: 1) Tie laces, 2) Put on socks, 3) Slip feet into shoes.","options":["1, 2, 3","2, 3, 1","3, 2, 1","2, 1, 3"],"answerIndex":1,"explanation":"Socks go on first, then shoes, then you tie the laces."},{"question":"What do we call a list of steps done in the right order to finish a task?","options":["A guess","An algorithm","A question","A color"],"answerIndex":1,"explanation":"An algorithm is a step-by-step set of instructions."}],"apply":{"prompt":"Write or draw a 4-step algorithm telling a friend how to make a paper airplane or draw a smiley face.","checklist":["Listed exactly 4 steps","Put the steps in the correct order","Tested it by having someone follow the steps"]}}'::jsonb, 0),
  ('class_topic', 'TechnologyAndEngineering', 'Block-Based Coding & Loops', 'An introduction to visual, block-based programming (like Scratch), focused on using loops to repeat instructions instead of writing the same block over and over.', '{"grade":"3-5","color":"#4D96FF","help":{"videos":[{"title":"Scratch Coding Tutorial - Basic Loops","url":"https://www.youtube.com/watch?v=m57Gmc7wFIM"},{"title":"Coding with Loops and If Statements in Scratch","url":"https://www.youtube.com/watch?v=OWwGMYj5Efg"}]},"topic_key":"blockCodingLoops","learn":[{"heading":"What a Loop Does","body":"A loop repeats a set of instructions a certain number of times (or forever) so you don''t have to write the same block again and again. Instead of stacking 10 \"move forward\" blocks, you put 1 \"move forward\" block inside a \"repeat 10\" loop."},{"heading":"Loops Save Work — and Catch Bugs","body":"Loops make programs shorter and easier to fix — change the number in the loop once, and every repetition updates. But a loop that repeats a mistake also repeats it 10 times, so testing what''s inside the loop first is important."}],"practice":[{"question":"If a block inside a \"Repeat 4 Times\" loop says \"Turn Right 90 Degrees,\" what shape path will your character trace?","options":["A straight line","A full turn back to where it started (like a square)","It won''t move","A zigzag"],"answerIndex":1,"explanation":"Four 90-degree turns add up to 360 degrees — a full turn, like tracing a square."},{"question":"Why use a loop instead of copying a block 10 times?","options":["Loops run slower","Loops make it easy to change how many times something repeats","Loops use more blocks","There is no difference"],"answerIndex":1,"explanation":"A loop lets you change one number instead of editing 10 separate blocks."}],"apply":{"prompt":"Write a short block-style pseudo-code routine (on paper or in Scratch) that makes a character walk forward 3 steps, jump, and repeat that whole sequence 3 times using a loop.","checklist":["Wrote the walk + jump sequence","Wrapped it in a \"repeat 3\" loop instead of copying it 3 times","Checked the total number of walk steps matches (3 steps × 3 repeats = 9)"]}}'::jsonb, 1),
  ('class_topic', 'TechnologyAndEngineering', '3D Modeling & CAD Fundamentals', 'Computer-Aided Design (CAD) builds 3D digital objects using primitive shapes. Introduces additive (joining parts) and subtractive (cutting holes) modeling using free tools like Tinkercad.', '{"grade":"6-8","color":"#3AC860","help":{"videos":[{"title":"Introduction to TinkerCAD","url":"https://www.youtube.com/watch?v=uCqxyweqQ1Q"},{"title":"Getting Started in Tinkercad: A Tutorial for Complete Beginners","url":"https://www.youtube.com/watch?v=60xfIu-lqAs"}]},"topic_key":"cadModeling","learn":[{"heading":"Building With Primitive Shapes","body":"CAD programs build objects out of \"primitive\" shapes — cubes, cylinders, spheres, cones — the same way a sculpture can be built from simple blocks of clay. You move, resize, and combine these shapes to build more complex objects."},{"heading":"Additive vs. Subtractive Modeling","body":"Additive modeling joins solid shapes together, like stacking blocks. Subtractive modeling uses a shape as a \"hole\" to cut material away from another shape — grouping a solid cylinder with a hole-shaped cylinder turns a solid rod into a hollow pipe."}],"practice":[{"question":"What modeling technique removes volume from an object to create a window or socket?","options":["Additive modeling","Subtractive modeling (hole grouping)","Coloring","Rotating"],"answerIndex":1,"explanation":"Subtractive modeling uses a \"hole\" shape to cut material away, like drilling a hole through a block."},{"question":"To turn a solid cylinder into a pipe in a CAD program, what would you do?","options":["Change its color","Group it with a smaller hole-cylinder set to \"hole\"","Make it bigger","Delete it"],"answerIndex":1,"explanation":"Grouping a solid shape with a same-shaped \"hole\" cuts out the inside, leaving a hollow pipe."}],"apply":{"prompt":"Sketch a 3D object (like a mug or a pencil holder) on paper and break down which primitive shapes — and which additive/subtractive steps — you would combine to build it in a CAD program.","checklist":["Sketched the object","Listed at least 2 primitive shapes used","Identified at least 1 subtractive (hole) step"]}}'::jsonb, 2),
  ('class_topic', 'TechnologyAndEngineering', 'RESTful APIs & Web Communication', 'How software applications talk to each other over the web. Covers REST architecture and the standard HTTP verbs — GET, POST, PUT/PATCH, and DELETE.', '{"grade":"9-12","color":"#8B4FC4","help":{"videos":[{"title":"HTTP Methods Explained: GET, POST, PUT, DELETE - REST API Basics with Express.js","url":"https://www.youtube.com/watch?v=aHx9x-nmRio"},{"title":"REST API Fundamentals: Learn to Use GET, POST, PUT, & DELETE","url":"https://www.youtube.com/watch?v=PfujVETI-i4"}]},"topic_key":"restfulApis","learn":[{"heading":"What an API Does","body":"An API (Application Programming Interface) lets one piece of software ask another for data or actions, without needing to know how it works internally. A RESTful API does this over standard web requests, usually exchanging data as JSON."},{"heading":"The Four Core HTTP Verbs","body":"GET fetches data without changing anything. POST creates something new (like submitting a form). PUT or PATCH updates something that already exists. DELETE removes it. A status code like 200 OK tells you whether the request succeeded."}],"practice":[{"question":"Which HTTP method should a client send when submitting a new user registration form?","options":["GET","POST","DELETE","PATCH"],"answerIndex":1,"explanation":"POST is used to create a new resource, like a new user account."},{"question":"A GET request to an API returns status code 200. What does that mean?","options":["The request failed","The server is down","The request succeeded and returned data","The data was deleted"],"answerIndex":2,"explanation":"200 OK means the request was successful."}],"apply":{"prompt":"Use a browser developer console or a free tool like Postman to send a GET request to a public API (e.g. api.github.com/users/octocat) and find the JSON field containing the account name.","checklist":["Sent a GET request to a real public API","Read the JSON response","Found and wrote down the specific field requested","Noted the response status code"]}}'::jsonb, 3),
  ('class_topic', 'ForeignLanguage', 'Greetings, Feelings & Manners', 'The first building blocks of Spanish conversation: saying hello and goodbye, asking how someone feels, and using polite words like "please" and "thank you."', '{"grade":"K-2","color":"#FF6B6B","help":{"videos":[{"title":"¡Hola! Spanish Greetings Song for Kids | Saludos en Español para Niños","url":"https://www.youtube.com/watch?v=PAbcvJAEoEE"},{"title":"Hola Hola ¿Cómo Estás? | Spanish Greeting Song for Kids","url":"https://www.youtube.com/watch?v=_7ef62sjZP8"}]},"topic_key":"greetingsManners","learn":[{"heading":"Say Hello & Ask How Someone Feels","body":"\"¡Hola!\" means Hello! \"¿Cómo estás?\" means How are you? and \"Estoy bien\" or \"Estoy feliz\" means I am good / I am happy. These four phrases are enough to start a real conversation in Spanish."},{"heading":"Manners Matter Everywhere","body":"\"Gracias\" means Thank you, and \"Por favor\" means Please. Using them is just as important in Spanish as it is in English — they show respect and make people want to keep talking with you."}],"practice":[{"question":"How do you say \"Thank you\" in Spanish?","options":["Por favor","Gracias","Hola","Adiós"],"answerIndex":1,"explanation":"\"Gracias\" means \"thank you\"; \"por favor\" means \"please.\""},{"question":"What does \"¿Cómo estás?\" mean?","options":["What is your name?","How are you?","Where do you live?","Goodbye"],"answerIndex":1,"explanation":"\"¿Cómo estás?\" is how you ask someone how they are feeling."}],"apply":{"prompt":"Record a 5-second voice note greeting someone in Spanish, asking how they are, and saying goodbye (\"¡Hola! ¿Cómo estás? ¡Adiós!\").","checklist":["Said \"¡Hola!\"","Asked \"¿Cómo estás?\"","Said \"¡Adiós!\" to close"]}}'::jsonb, 4),
  ('class_topic', 'ForeignLanguage', 'Colors, Numbers & Family Words', 'Core vocabulary for describing the world around you: counting, naming colors, and talking about family members — plus how Spanish word order differs from English.', '{"grade":"3-5","color":"#4D96FF","help":{"videos":[{"title":"Learn Spanish for Kids - Numbers, Colors & More","url":"https://www.youtube.com/watch?v=8yuiUvi568I"},{"title":"Learn the Colors in Spanish - Spanish Vocab for Kids","url":"https://www.youtube.com/watch?v=Lf60AKfbaEo"}]},"topic_key":"colorsNumbersFamily","learn":[{"heading":"Counting and Coloring in Spanish","body":"Numbers 1–5 are uno, dos, tres, cuatro, cinco. Colors include rojo (red), azul (blue), verde (green), and amarillo (yellow). Once you know a handful of nouns, colors and numbers let you describe almost anything."},{"heading":"Colors Go AFTER the Noun","body":"In English we say \"the red car,\" but in Spanish the adjective usually comes after the noun: \"el carro rojo\" (literally \"the car red\"). Family words like madre (mother), padre (father), and hermano/hermana (brother/sister) follow normal noun rules too."}],"practice":[{"question":"Translate into English: \"Tengo un hermano.\"","options":["I have a sister.","I have one brother.","I am a brother.","He has one brother."],"answerIndex":1,"explanation":"\"Tengo\" = I have, \"un hermano\" = one brother."},{"question":"How do you say \"the red car\" in Spanish?","options":["El rojo carro","El carro rojo","Rojo el carro","Carro el rojo"],"answerIndex":1,"explanation":"In Spanish, most adjectives (like colors) come after the noun: \"el carro rojo.\""}],"apply":{"prompt":"Point to 3 colored items in your room and say their color out loud in Spanish while recording a short clip.","checklist":["Named 3 different colored items","Used the correct Spanish color word for each","Said each sentence with the color after the noun"]}}'::jsonb, 5),
  ('class_topic', 'ForeignLanguage', 'Descriptive Sentences & Daily Routines', 'Building real sentences by conjugating regular -AR verbs to describe daily routines and activities.', '{"grade":"6-8","color":"#3AC860","help":{"videos":[{"title":"SPANISH VERBS EXPLAINED! - Conjugate AR Verbs","url":"https://www.youtube.com/watch?v=oEVfwmt0oVA"}]},"topic_key":"dailyRoutinesVerbs","learn":[{"heading":"Conjugating -AR Verbs","body":"Regular Spanish verbs end in -ar, -er, or -ir. For -ar verbs, drop the -ar and add a new ending based on who''s doing the action: hablar (to speak) becomes yo hablo (I speak), tú hablas (you speak), él/ella habla (he/she speaks)."},{"heading":"Everyday Verbs Build Everyday Sentences","body":"Common -ar verbs like estudiar (to study), escuchar (to listen), and caminar (to walk) let you describe a whole daily routine once you know the conjugation pattern — it applies the same way to every regular -ar verb."}],"practice":[{"question":"What is the correct form of necesitar (to need) for \"I need\"?","options":["Yo necesita","Yo necesito","Tú necesitas","Él necesito"],"answerIndex":1,"explanation":"Drop -ar from necesitar and add -o for \"yo\": necesito."},{"question":"How do you conjugate hablar for \"tú\" (you)?","options":["Hablo","Hablas","Habla","Hablan"],"answerIndex":1,"explanation":"For \"tú,\" drop -ar and add -as: hablas."}],"apply":{"prompt":"Write 3 sentences in Spanish describing your daily schedule using common -ar verbs (estudiar, comer, escuchar, caminar).","checklist":["Wrote 3 complete Spanish sentences","Used a different -ar verb correctly conjugated in each","Sentences describe real parts of your day"]}}'::jsonb, 6),
  ('class_topic', 'ForeignLanguage', 'Ordering Food & Polite Requests', 'Real-world conversational Spanish: ordering a meal, making polite requests, and using formal address with waitstaff or strangers.', '{"grade":"9-12","color":"#8B4FC4","help":{"videos":[{"title":"Spanish for Beginners: Ordering Food at a Restaurant","url":"https://www.youtube.com/watch?v=xZCW3bnq5ds"},{"title":"How to Order Food in Spanish: Restaurant Vocab & Phrases","url":"https://www.youtube.com/watch?v=t8V2Gw8MyiM"}]},"topic_key":"orderingFoodPoliteRequests","learn":[{"heading":"Making Polite Requests","body":"\"Quisiera...\" means I would like... — a softer, more polite way to ask than \"quiero\" (I want). \"¿Me trae...?\" means Could you bring me...? and \"La cuenta, por favor\" means The bill, please."},{"heading":"Formal vs. Informal \"You\"","body":"Spanish has two ways to say \"you\": tú (informal, for friends) and usted (formal, for strangers, elders, or service staff). Restaurant conversations almost always use the formal usted forms as a sign of respect."}],"practice":[{"question":"Translate to Spanish: \"I would like a water, please.\"","options":["Quiero un agua.","Quisiera un agua, por favor.","Necesito un agua, gracias.","Un agua, ahora."],"answerIndex":1,"explanation":"\"Quisiera\" is the polite conditional form of \"quiero,\" and \"por favor\" adds \"please.\""},{"question":"When ordering at a restaurant, which form of \"you\" should you typically use with the waiter?","options":["Tú","Usted (formal)","Vosotros","Neither — skip it"],"answerIndex":1,"explanation":"Usted is the polite, formal form used with strangers and service staff."}],"apply":{"prompt":"Record a 15-second audio snippet simulating ordering a full meal — one drink, one main dish, and asking for the check — in Spanish.","checklist":["Ordered a drink using \"quisiera\"","Ordered a main dish","Asked for the bill with \"la cuenta, por favor\""]}}'::jsonb, 7),
  ('class_topic', 'HealthAndFitness', 'Handwashing & Hygiene Habits', 'Germs are tiny living things that can make you sick. Learning to wash hands properly, and knowing when it matters most, is the single best defense against getting sick.', '{"grade":"K-2","color":"#FF6B6B","help":{"videos":[{"title":"The Hand Washing Song 🧼 | Healthy Habits Kids Song | Super Simple Songs","url":"https://www.youtube.com/watch?v=8lu587o8T3c"}]},"topic_key":"handwashingHygiene","learn":[{"heading":"Why We Wash","body":"Germs are so small you can''t see them, but they can make you sick if they get into your body. Scrubbing your hands with soap and warm water lifts germs off your skin and washes them away."},{"heading":"How Long & When","body":"Wash for about 20 seconds — the time it takes to sing \"Happy Birthday\" twice — scrubbing between your fingers and under your nails. Always wash before eating and after using the bathroom, coughing, or playing outside."}],"practice":[{"question":"How long should you wash your hands with soap and water?","options":["5 seconds","20 seconds","2 minutes","You don''t need soap"],"answerIndex":1,"explanation":"About 20 seconds — roughly the time it takes to sing \"Happy Birthday\" twice — is long enough to remove germs."},{"question":"Which of these is a good time to wash your hands?","options":["Only in the morning","Before eating and after the bathroom","Only if hands look dirty","Once a week"],"answerIndex":1,"explanation":"Handwashing matters most before eating and after the bathroom, coughing, or playing outside — even if hands look clean."}],"apply":{"prompt":"Wash your hands properly while singing a 20-second song, then check off a hygiene tracking sheet for today.","checklist":["Used soap and warm water","Scrubbed for about 20 seconds","Scrubbed between fingers and under nails","Dried hands with a clean towel"]}}'::jsonb, 8),
  ('class_topic', 'HealthAndFitness', 'MyPlate Food Groups & Balanced Meals', 'Healthy bodies need a variety of foods from all 5 MyPlate groups. Learn to build a balanced plate, with fruits and vegetables filling about half of it.', '{"grade":"3-5","color":"#4D96FF","help":{"videos":[{"title":"MyPlate! #1: Food Groups for Kids!","url":"https://www.youtube.com/watch?v=-0Ql8Iq6PnE"}]},"topic_key":"myPlateFoodGroups","learn":[{"heading":"The 5 Food Groups","body":"MyPlate divides food into 5 groups: Fruits, Vegetables, Grains, Protein, and Dairy. Each group gives your body something different — grains give energy, protein builds muscle, and fruits and vegetables provide vitamins."},{"heading":"Build a Balanced Plate","body":"A good rule of thumb: make about half your plate fruits and vegetables, with the rest split between grains (aim for whole grains) and protein, plus a serving of dairy on the side."}],"practice":[{"question":"Which two food groups should make up about half of your dinner plate?","options":["Dairy and grains","Fruits and vegetables","Protein and dairy","Just protein"],"answerIndex":1,"explanation":"Filling half the plate with fruits and vegetables is the core MyPlate guideline."},{"question":"How many food groups does MyPlate divide food into?","options":["3","4","5","7"],"answerIndex":2,"explanation":"MyPlate has 5 groups: Fruits, Vegetables, Grains, Protein, and Dairy."}],"apply":{"prompt":"Draw a dinner plate divided into sections and fill each part with foods you like from the 5 main food groups.","checklist":["Drew all 5 food groups on the plate","Made fruits + vegetables about half the plate","Labeled each section with a real food"]}}'::jsonb, 9),
  ('class_topic', 'HealthAndFitness', 'Cardiovascular Health & Target Heart Rate', 'Your heart is a muscle strengthened by aerobic exercise. Learn to measure your pulse and understand what a target heart rate zone means during exercise.', '{"grade":"6-8","color":"#3AC860","help":{"videos":[{"title":"HOW TO CALCULATE TARGET HEART RATE","url":"https://www.youtube.com/watch?v=emBa3HDVZ9Y"}]},"topic_key":"cardiovascularHeartRate","learn":[{"heading":"The Heart Is a Muscle","body":"Aerobic exercise — running, swimming, cycling — makes your heart stronger over time, the same way lifting weights strengthens other muscles. A stronger heart pumps more blood per beat, which is why a fit person''s resting heart rate is often lower."},{"heading":"Finding Your Target Heart Rate","body":"A rough estimate of your maximum heart rate is 220 minus your age. Your target heart rate zone during moderate exercise is usually 50–85% of that number — high enough to build fitness, low enough to sustain safely."}],"practice":[{"question":"If you count 12 heartbeats in 10 seconds while resting, what is your heart rate in beats per minute (BPM)?","options":["12 BPM","60 BPM","72 BPM","120 BPM"],"answerIndex":2,"explanation":"12 beats in 10 seconds × 6 = 72 BPM."},{"question":"What type of exercise is best known for strengthening the heart over time?","options":["Stretching","Aerobic exercise like running or swimming","Sitting still","Sleeping"],"answerIndex":1,"explanation":"Aerobic (cardio) exercise conditions the heart muscle to pump more efficiently."}],"apply":{"prompt":"Measure and record your resting heart rate. Do 30 jumping jacks, measure your heart rate again immediately, and compare the two numbers.","checklist":["Measured resting heart rate (BPM)","Did 30 jumping jacks","Measured heart rate right after exercise","Compared the two numbers and noted the difference"]}}'::jsonb, 10),
  ('class_topic', 'HealthAndFitness', 'Energy Balance & Macronutrient Calculations', 'Energy balance (Calories In vs. Calories Out) determines weight change over time. Learn how each macronutrient contributes calories, and how to calculate them from a nutrition label.', '{"grade":"9-12","color":"#8B4FC4","help":{"videos":[{"title":"Macronutrients - Carbs, Protein, and Fat Explained","url":"https://www.youtube.com/watch?v=uSMvgpxYDnc"}]},"topic_key":"macronutrientEnergyBalance","learn":[{"heading":"Calories In, Calories Out","body":"Energy balance is the relationship between the calories your body takes in from food and the calories it burns through activity and basic functioning. Consistently taking in more than you burn leads to weight gain; consistently burning more leads to weight loss."},{"heading":"What Each Macronutrient Provides","body":"Carbohydrates and protein each provide about 4 kcal per gram, while fat provides about 9 kcal per gram — more than double. That''s why fat-dense foods pack a lot of calories into a small amount."}],"practice":[{"question":"How many total calories are in a snack with 10g Protein, 20g Carbs, and 5g Fat?","options":["70 kcal","120 kcal","165 kcal","200 kcal"],"answerIndex":2,"explanation":"(10×4) + (20×4) + (5×9) = 40 + 80 + 45 = 165 kcal."},{"question":"Which macronutrient provides the most calories per gram?","options":["Carbohydrates","Protein","Fat","They''re all equal"],"answerIndex":2,"explanation":"Fat provides about 9 kcal/g, more than double carbs or protein at about 4 kcal/g each."}],"apply":{"prompt":"Choose a packaged food item. Read its nutrition label and calculate what percentage of its total calories comes from fat versus carbohydrates.","checklist":["Recorded grams of fat, carbs, and protein from the label","Converted each to calories using 4/4/9 kcal per gram","Calculated the percentage of total calories from fat","Calculated the percentage of total calories from carbs"]}}'::jsonb, 11),
  ('class_topic', 'BusinessAndFinance', 'Needs vs. Wants', 'The foundation of every money decision: telling the difference between something you truly need to survive and stay healthy, and something that would just be nice to have.', '{"grade":"K-2","color":"#FF6B6B","help":{"videos":[{"title":"Needs Vs Wants | Lesson for Kids","url":"https://www.youtube.com/watch?v=IlFOepd4pTE"}]},"topic_key":"needsWants","learn":[{"heading":"What Is a Need?","body":"A need is something you must have to survive and stay healthy — food, water, a safe place to live, and warm clothes. Without needs, you can''t stay healthy or safe."},{"heading":"What Is a Want?","body":"A want is something nice to have, but you could live without it — toys, candy, video games. Smart spending means taking care of needs first, then deciding what wants are worth saving for."}],"practice":[{"question":"Is a winter coat a Need or a Want?","options":["Need","Want","Neither","Both equally"],"answerIndex":0,"explanation":"A winter coat keeps you safe and healthy in cold weather, which makes it a need."},{"question":"Which of these is a Want, not a Need?","options":["Drinking water","A video game","A place to sleep","A winter coat"],"answerIndex":1,"explanation":"A video game is fun to have but isn''t required to survive or stay healthy — that makes it a want."}],"apply":{"prompt":"Look around your room. Draw 2 things that are Needs and 2 things that are Wants, labeling each one.","checklist":["Drew 2 Needs","Drew 2 Wants","Labeled each drawing correctly"]}}'::jsonb, 12),
  ('class_topic', 'BusinessAndFinance', 'Earn, Save, Spend & Give', 'Money earned from chores or gifts can be split on purpose into jars — Spend, Save, and Give — building healthy money habits early instead of spending everything right away.', '{"grade":"3-5","color":"#4D96FF","help":{"videos":[{"title":"Elmo''s Spend, Share, and Save Jars | Financial Education","url":"https://www.youtube.com/watch?v=oqgtFqd8nHo"}]},"topic_key":"earnSaveSpendGive","learn":[{"heading":"The Three-Jar System","body":"Splitting money into three jars — Spend (everyday small treats), Save (bigger goals you''re working toward), and Give (helping others) — turns money decisions into a habit instead of a guess."},{"heading":"A Little Bit, Every Time","body":"Every time money comes in — allowance, a birthday gift, or money earned from a chore — divide it among the jars right away. Even putting $1 out of every $10 into Save builds a habit that grows over time."}],"practice":[{"question":"If you earn $10 doing yard work and put 20% into your Save jar, how much goes into Save?","options":["$1.00","$2.00","$5.00","$10.00"],"answerIndex":1,"explanation":"20% of $10 is $2.00 (10 × 0.20 = 2)."},{"question":"What is the purpose of the \"Give\" jar?","options":["Buying video games","Saving for college","Helping others or a cause you care about","Paying rent"],"answerIndex":2,"explanation":"The Give jar sets money aside specifically to help others, like a charity or a gift."}],"apply":{"prompt":"Create a savings goal tracker on paper for an item you want to buy, showing how much you need to save each week to buy it in 4 weeks.","checklist":["Named the savings goal item and its price","Divided the total by 4 weeks","Drew a tracker with 4 weekly boxes to check off"]}}'::jsonb, 13),
  ('class_topic', 'BusinessAndFinance', 'Budgeting & Fixed vs. Variable Costs', 'A budget tracks income and expenses. Learn to tell the difference between fixed expenses (the same every month) and variable expenses (that change), and build a simple budget.', '{"grade":"6-8","color":"#3AC860","help":{"videos":[{"title":"Budgeting Lesson 3: Fixed vs. Variable Expenses | RETHINK Financial Education Curriculum","url":"https://www.youtube.com/watch?v=Llg5HNnpKdU"}]},"topic_key":"budgetingFixedVariable","learn":[{"heading":"Fixed vs. Variable Expenses","body":"Fixed expenses stay the same every month, like a phone plan or a streaming subscription. Variable expenses change based on choices, like groceries, gas, or eating out — you have more control over these."},{"heading":"Building a Simple Budget","body":"A budget starts by listing income, then fixed expenses (so you know what''s locked in), then variable expenses, and finally what''s left over for saving. Listing fixed expenses first makes sure the essentials are always covered."}],"practice":[{"question":"Is a $15 monthly streaming membership a fixed or variable expense?","options":["Fixed expense","Variable expense","Neither","It depends on the day"],"answerIndex":0,"explanation":"A subscription that charges the same amount every month is a fixed expense."},{"question":"Which of these is a variable expense?","options":["Rent","A monthly phone plan","Groceries","A yearly gym membership fee"],"answerIndex":2,"explanation":"Grocery costs change month to month based on choices, making them variable."}],"apply":{"prompt":"Build a mock monthly budget for a student who earns $100/month from tutoring. Allocate income across fixed subscriptions, variable spending, and savings.","checklist":["Listed at least 1 fixed expense with an amount","Listed at least 1 variable expense with an amount","Set aside an amount for savings","Total allocated equals $100"]}}'::jsonb, 14),
  ('class_topic', 'BusinessAndFinance', 'The Power of Compound Interest', 'Simple interest pays only on the original amount saved or borrowed. Compound interest pays on the principal AND on interest already earned — and starting early gives it exponential leverage.', '{"grade":"9-12","color":"#8B4FC4","help":{"videos":[{"title":"COMPOUND INTEREST explained for beginners 2023 (including rule of 72)","url":"https://www.youtube.com/watch?v=JWhkxNLOGFk"}]},"topic_key":"compoundInterest","learn":[{"heading":"Simple vs. Compound Interest","body":"Simple interest only ever grows based on your original principal. Compound interest, A = P(1 + r/n)^(nt), grows based on the principal PLUS all the interest already earned — so the growth accelerates the longer money stays invested."},{"heading":"Time Is the Real Advantage","body":"The compounding curve stays fairly flat for the first several years, then steepens sharply — which is why starting to save even small amounts early beats saving larger amounts later, purely because of extra time compounding."}],"practice":[{"question":"If you invest $1,000 at 10% annual interest compounded yearly, how much do you have after 2 years?","options":["$1,100","$1,200","$1,210","$1,000"],"answerIndex":2,"explanation":"Year 1: $1,000 × 1.10 = $1,100. Year 2: $1,100 × 1.10 = $1,210 (interest earns interest)."},{"question":"What makes compound interest different from simple interest?","options":["Compound interest is always a lower rate","Compound interest grows on principal plus previously earned interest","Simple interest grows faster","There is no real difference"],"answerIndex":1,"explanation":"Compound interest reinvests earned interest, so future interest is calculated on a growing balance."}],"apply":{"prompt":"Use an online compound interest calculator to compute the difference at age 60 between investing $100/month starting at age 20 versus starting at age 30 (assuming a 7% average annual return).","checklist":["Calculated the total at age 60 starting at age 20","Calculated the total at age 60 starting at age 30","Found the dollar difference between the two","Wrote 1 sentence explaining why the earlier start wins"]}}'::jsonb, 15)
on conflict do nothing;